function isPineLibId(id){return typeof id==='string'&&id.startsWith('plib_')}
function pineLibGet(id){return PINE_LIBS.find(l=>l.id===id)||null}
function pineLibNormPath(p){return String(p||'').trim().replace(/^\/+|\/+$/g,'')}
function pineLibBasePath(p){
  const parts=pineLibNormPath(p).split('/');
  return parts.length>=2?(parts[0]+'/'+parts[1]).toLowerCase():pineLibNormPath(p).toLowerCase();
}
function pineLibFind(importPath){
  const norm=pineLibNormPath(importPath).toLowerCase();
  if(!norm)return null;
  const pool=PINE_LIBS.concat(DEFAULT_PINE_LIBS);
  let hit=pool.find(l=>pineLibNormPath(l.path).toLowerCase()===norm);
  if(hit)return hit;
  const base=pineLibBasePath(importPath);
  hit=pool.find(l=>pineLibBasePath(l.path)===base);
  if(hit)return hit;
  const segs=norm.split('/');
  const libNm=segs.length>=2?segs[1]:segs[0];
  return pool.find(l=>String(l.name||'').toLowerCase()===libNm)||null;
}
function pineLibExports(code){
  const ex=[];
  const lines=String(code||'').split(/\r?\n/);
  for(const raw of lines){
    const t=raw.trim();
    let m=/^export\s+(?:method\s+)?([a-zA-Z_]\w*)\s*\(/.exec(t);
    if(m){if(!ex.includes(m[1]))ex.push(m[1]);continue}
    m=/^export\s+(?:type|enum)\s+([a-zA-Z_]\w*)/.exec(t);
    if(m){if(!ex.includes(m[1]))ex.push(m[1]);continue}
  }
  return ex;
}
function ldPines(){try{const a=JSON.parse(localStorage['dx:pines']||'[]');return Array.isArray(a)?a.filter(x=>x&&x.id&&typeof x.code==='string'):[]}catch(e){return[]}}
function svPines(){try{localStorage['dx:pines']=JSON.stringify(PINE_SCRIPTS)}catch(e){}}
PINE_SCRIPTS=ldPines();
function isPineId(id){return typeof id==='string'&&id.startsWith('pine_')}
function isTvPackId(id){return typeof id==='string'&&id.startsWith('pine_tv_')}
function allPineScripts(){return PINE_SCRIPTS.concat(TV_PACK)}
function pineGet(id){return PINE_SCRIPTS.find(p=>p.id===id)||TV_PACK.find(p=>p.id===id)||null}
function pineAsIndList(){return allPineScripts().map(p=>[p.id,p.name,(p.desc||'Pine Script')+' · '+(p.overlay?'Overlay':'Sub-pane'),p.overlay?'o':'s'])}
function allInds(){return IND.concat(pineAsIndList())}
function findIndMeta(id){const m=IND.find(x=>x[0]==id);if(m)return m;const p=pineGet(id);return p?[p.id,p.name,p.desc||'Pine Script',p.overlay?'o':'s']:null}
function pineCfgDef(){
  return {hid:0,inVals:{},pSty:{},hSty:{},fSty:{},shSty:{},bgSty:{},objSty:{boxes:1,lines:1,labels:1,linefills:1,tables:1},showVal:1,showLbl:1,vis:IND_VIS_DEF()};
}
function indCfg(id){
  if(!IND_CFG[id]){
    IND_CFG[id]=isPineId(id)?pineCfgDef():indDefOne(id);
  }
  if(isPineId(id)){
    const o=IND_CFG[id];
    if(!o.inVals)o.inVals={};
    if(!o.pSty)o.pSty={};
    if(!o.hSty)o.hSty={};
    if(!o.fSty)o.fSty={};
    if(!o.shSty)o.shSty={};
    if(!o.bgSty)o.bgSty={};
    if(!o.objSty)o.objSty={boxes:1,lines:1,labels:1,linefills:1,tables:1};
    if(o.showVal===undefined)o.showVal=1;
    if(o.showLbl===undefined)o.showLbl=1;
    if(!o.vis)o.vis=IND_VIS_DEF();
  }
  return IND_CFG[id];
}
function indVisOk(id,tfId){
  const c=indCfg(id);if(c.hid)return false;
  const v=c.vis;if(!v)return true;
  const I=ti(tfId||tf);if(!I)return true;
  const r=v[I.u];if(!r)return true;
  return !!r[0]&&I.n>=r[1]&&I.n<=r[2];
}
function indTitle(id){
  if(isPineId(id)){
    const p=pineGet(id);if(!p)return id;
    const c=indCfg(id), res=S&&S[id];
    const inps=res&&res.inputs?res.inputs.filter(x=>x.type=='int'||x.type=='float').slice(0,3):[];
    const vals=inps.map(x=>c.inVals&&c.inVals[x.key]!=null?c.inVals[x.key]:x.def);
    return (p.shorttitle||p.name)+(vals.length?' ('+vals.join(', ')+')':'');
  }
  const c=indCfg(id);
  if(id=='vwap')return 'VWAP'+(c.anchor&&c.anchor!='session'?' ('+c.anchor[0].toUpperCase()+c.anchor.slice(1)+')':'');
  if(id=='ema20'||id=='ema50')return 'EMA '+c.len+(c.off?' '+c.off:'');
  if(id=='sma200')return 'SMA '+c.len+(c.off?' '+c.off:'');
  if(id=='bb')return 'BB '+c.len+' '+c.mult;
  if(id=='vol')return 'Vol'+(c.maOn?' MA '+c.maLen:'');
  if(id=='cvd'){const am={session:'1D',week:'1W',month:'1M',quarter:'3M',year:'12M'};const al=am[c.anchor];return 'CVD'+(al?' ('+al+')':'');}
  if(id=='rsi')return 'RSI '+c.len+(c.maType&&c.maType!='none'?' · '+c.maType.toUpperCase()+' '+c.maLen:'');
  if(id=='macd')return 'MACD '+c.fast+' '+c.slow+' '+c.sigLen;
  if(id=='atr')return 'ATR '+c.len+' ('+(c.sm||'rma').toUpperCase()+')';
  const m=IND.find(x=>x[0]==id);return m?m[1]:id;
}
function indValsHtml(id,bi,Sref,Dref){
  const c=indCfg(id),So=Sref||S,Do=Dref||D;
  if(!Do||!Do.length||!So)return '';
  const i=Math.max(0,Math.min(Do.length-1,bi));
  const fv=v=>(v===v&&v!=null)?fmtS(v):'—';
  const fn=(v,d=2)=>(v===v&&v!=null)?Number(v).toFixed(d):'—';
  const spn=(v,col)=>`<span style="color:${col}">${v}</span>`;
  if(isPineId(id)){
    const res=So[id];if(!res)return '';
    if(res.err)return `<span style="color:#ef5350" title="${esc(res.err)}">⚠ Script error</span>`;
    if(c.showVal===0)return '';
    const p=pineGet(id), ov=p&&p.overlay;
    return (res.plots||[]).slice(0,5).map((pl,pi)=>{
      const st=c.pSty&&c.pSty[pi];if(st&&st.on===0)return '';
      const v=pl.vals[i];
      const col=(st&&st.cSet&&st.c)||pl.cols[i]||pl.color||'#2962ff';
      return spn(ov?fv(v):fn(v,2),col=='transparent'?'#8b93a3':col);
    }).filter(Boolean).join(' ');
  }
  if(id=='vwap'){
    let s=spn(fv(So.vwap&&So.vwap[i]),c.ln.c);
    if(c.b1on&&So.vwapB1u)s+=' '+spn(fv(So.vwapB1u[i]),c.b1.c)+' '+spn(fv(So.vwapB1l[i]),c.b1.c);
    return s;
  }
  if(id=='ema20'||id=='ema50'||id=='sma200'){
    let s=spn(fv(So[id]&&So[id][i]),c.ln.c);
    const smArr=So[id+'_sm'];
    if(c.smType!='none'&&smArr)s+=' '+spn(fv(smArr[i]),c.sm.c);
    return s;
  }
  if(id=='bb'){
    return spn(fv(So.bbm&&So.bbm[i]),c.basis.c)+' '+spn(fv(So.bbu&&So.bbu[i]),c.upper.c)+' '+spn(fv(So.bbl&&So.bbl[i]),c.lower.c);
  }
  if(id=='vol'){
    const k=Do[i],up=c.cmode=='candle'?(k.c>=k.o):(k.tb>=k.v/2);
    let s=spn(fmtV(k.v),up?c.up.c:c.dn.c);
    if(c.maOn&&So.volMa)s+=' '+spn(fmtV(So.volMa[i]||0),c.ma.c);
    return s;
  }
  if(id=='cvd'){
    const m0=c.mode||'candles',c0=So.cvdC?So.cvdC[i]:(So.cvd?So.cvd[i]:0),o0=So.cvdO?So.cvdO[i]:c0;
    const isUp=(c0>=o0),col0=isUp?((c.up&&c.up.c)||'#26a69a'):((c.dn&&c.dn.c)||'#ef5350');
    if(m0==='candles'||m0==='hollow'){
      const h0=So.cvdH?So.cvdH[i]:c0,l0=So.cvdL?So.cvdL[i]:c0;
      return spn('O '+fmtV(o0),col0)+' '+spn('H '+fmtV(h0),col0)+' '+spn('L '+fmtV(l0),col0)+' '+spn('C '+fmtV(c0),col0);
    }
    const v0=m0==='hist'?(So.cvdDelta?So.cvdDelta[i]:0):c0;
    return spn(fmtV(v0),v0>=0?((c.up&&c.up.c)||c.ln.c):((c.dn&&c.dn.c)||'#ef5350'));
  }
  if(id=='rsi'){
    let s=spn(fn(So.rsi&&So.rsi[i],2),c.ln.c);
    if(c.maType!='none'&&So.rsiMa)s+=' '+spn(fn(So.rsiMa[i],2),c.ma.c);
    return s;
  }
  if(id=='macd'){
    const hv=So.hist&&So.hist[i];
    return spn(fn(So.macd&&So.macd[i],2),c.macdLn.c)+' '+spn(fn(So.sig&&So.sig[i],2),c.sigLn.c)+' '+spn(fn(hv,2),hv>=0?c.hist.u1:c.hist.d2);
  }
  if(id=='atr')return spn(fv(So.atr&&So.atr[i]),c.ln.c);
  return '';
}
