function pnStartResize(bd,startY,fromRight){
  if(!bd)return;
  const FP_TH0=(typeof fpTableHeight==='function')?fpTableHeight(CFG,H-BX):0;
  const AV_H0=Math.max(120,H-BX-FP_TH0);
  const SP0=allInds().filter(q=>q[3]=='s'&&ind[q[0]]).sort(pcmp);
  const lay0=calcPaneLayout(SP0,AV_H0,true);
  PN_RSZ={idx:bd.idx,avH:AV_H0,fpTh:FP_TH0,minMain:Math.max(110,Math.round(AV_H0*0.20)),minSub:44,spIds:SP0.map(q=>q[0]),hs0:lay0.hs.slice(),topPrevY:bd.idx>0?PN_RECTS[bd.idx-1].y0:0,fromRight:!!fromRight,y0:startY,bY0:bd.y};
}
function calcPaneLayout(SP, AV_H, useCustom){
  const k=SP.length;
  if(!k)return{ph:AV_H,hs:[]};
  const defTot=Math.round(AV_H*(k===1?0.23:k===2?0.35:0.44));
  const defEach=Math.max(54,Math.floor(defTot/k));
  const minMain=Math.max(110,Math.round(AV_H*0.20));
  const minSub=44;
  const pMap=(useCustom!==false&&CFG&&CFG.paneH&&typeof CFG.paneH==='object')?CFG.paneH:{};
  const hs=SP.map(s=>{
    const v=+pMap[s[0]];
    return Math.max(minSub,(v>0?Math.round(v):defEach));
  });
  let sumH=hs.reduce((a,b)=>a+b,0);
  const maxSubTot=Math.max(minSub*k,AV_H-minMain);
  if(sumH>maxSubTot&&sumH>0){
    const sc=maxSubTot/sumH;
    for(let i=0;i<k;i++)hs[i]=Math.max(minSub,Math.floor(hs[i]*sc));
    sumH=hs.reduce((a,b)=>a+b,0);
  }
  const ph=Math.max(minMain,Math.round(AV_H-sumH));
  const rem=AV_H-ph-sumH;
  if(k>0&&rem!==0)hs[k-1]=Math.max(minSub,hs[k-1]+rem);
  return{ph,hs};
}
function pnBorderAt(x,y,tol){
  if(x<0||x>W||!PN_BORDERS.length)return null;
  const t=tol||5;
  let best=null,bd=1e9;
  for(let i=0;i<PN_BORDERS.length;i++){
    const d=Math.abs(y-PN_BORDERS[i].y);
    if(d<=t&&d<bd){bd=d;best=PN_BORDERS[i]}
  }
  return best;
}
function pnApplyDrag(rawY){
  if(!PN_RSZ)return;
  const r=PN_RSZ, minMain=r.minMain, minSub=r.minSub;
  const curY=r.fromRight?(r.bY0+(rawY-r.y0)):rawY;
  if(!CFG.paneH||typeof CFG.paneH!=='object')CFG.paneH={};
  if(r.idx===0){
    const otherSub=r.hs0.slice(1).reduce((a,b)=>a+b,0);
    const maxPH=r.avH-minSub-otherSub;
    const newPH=Math.max(minMain,Math.min(maxPH,Math.round(curY-r.fpTh)));
    const newH0=Math.max(minSub,r.avH-newPH-otherSub);
    CFG.paneH[r.spIds[0]]=newH0;
    for(let j=1;j<r.spIds.length;j++)CFG.paneH[r.spIds[j]]=r.hs0[j];
  }else{
    const j=r.idx;
    const pairSum=r.hs0[j-1]+r.hs0[j];
    const newPrev=Math.max(minSub,Math.min(pairSum-minSub,Math.round(curY-r.topPrevY)));
    const newCurr=Math.max(minSub,pairSum-newPrev);
    for(let m=0;m<r.spIds.length;m++){
      if(m===j-1)CFG.paneH[r.spIds[m]]=newPrev;
      else if(m===j)CFG.paneH[r.spIds[m]]=newCurr;
      else CFG.paneH[r.spIds[m]]=r.hs0[m];
    }
  }
}
