function buildCexSeed() {
  const out = [];
  const usdEx = ['COINBASE', 'KRAKEN'];
  const perpEx = ['BYBIT', 'MEXC', 'OKX', 'BITGET', 'KUCOIN', 'GATEIO'];
  CEX_SEED_COINS.forEach(([b, full, px], idx) => {
    // Binance Perpetuals (Spot comes from Binance SL)
    if (idx < 35) out.push([`BINANCE:${b}USDT.P`, b, 'USDT', 'F', `${full} / TetherUS Perpetual`, null, 'BINANCE', px, 'BINANCE']);
    perpEx.forEach(ex => {
      out.push([`${ex}:${b}USDT`, b, 'USDT', 'S', `${full} / TetherUS`, null, ex, px, ex]);
      if (idx < 38) out.push([`${ex}:${b}USDT.P`, b, 'USDT', 'F', `${full} / TetherUS Perpetual`, null, ex, px, ex]);
    });
    if (idx < 26) out.push([`HTX:${b}USDT`, b, 'USDT', 'S', `${full} / TetherUS`, null, 'HTX', px, 'HTX']);
    if (idx < 24) usdEx.forEach(ex => {
      out.push([`${ex}:${b}USD`, b, 'USD', 'S', `${full} / U.S. Dollar`, null, ex, px, ex]);
      if (idx < 8) out.push([`${ex}:${b}USDT`, b, 'USDT', 'S', `${full} / TetherUS`, null, ex, px, ex]);
    });
  });
  return out;
}

const CEX_SEED = buildCexSeed();
const CEX_MAP = {};
const CEX_LIVE = {};   // ex -> array of live-fetched entries
const CEX_LOADED = {}; // ex -> timestamp
let CEX_POOL_CACHE = null;

function rebuildCexPool() {
  const seen = new Set();
  const res = [];
  const add = e => {
    if (!e || !e[0] || seen.has(e[0])) return;
    seen.add(e[0]);
    CEX_MAP[e[0]] = e;
    res.push(e);
  };
  CEX_SEED.forEach(add);
  CEX_ORDER.forEach(ex => { if (Array.isArray(CEX_LIVE[ex])) CEX_LIVE[ex].forEach(add); });
  CEX_POOL_CACHE = res;
}
rebuildCexPool();

function splitBaseQuote(raw) {
  const r = String(raw || '').toUpperCase().replace(/\.P$/i, '').replace(/[-_\/]/g, '');
  for (const q of CEX_QUOTES) {
    if (r.length > q.length && r.endsWith(q)) return [r.slice(0, -q.length), q];
  }
  return [r, 'USDT'];
}

function cexParse(s) {
  const str = String(s || '').toUpperCase();
  const ci = str.indexOf(':');
  if (ci > 0) {
    const ex = str.slice(0, ci);
    if (CEX_META[ex]) {
      const rest = str.slice(ci + 1);
      const perp = rest.endsWith('.P');
      const raw = perp ? rest.slice(0, -2) : rest;
      const inf = CEX_MAP[str] || CUSTOM_MAP[str];
      const [base, quote] = inf ? [inf[1], inf[2]] : splitBaseQuote(raw);
      return { ex, raw, base, quote, perp, id: str };
    }
  }
  if (GLOBAL_MAP[s]) return null;
  const inf = SL.find(x => x[0] === s) || CUSTOM_MAP[s];
  if (inf && (inf[3] === 'S' || inf[3] === 'F')) {
    const ex = inf[6] || 'BINANCE';
    return { ex, raw: inf[0].replace(/^[A-Z]+:/, '').replace(/\.P$/, ''), base: inf[1], quote: inf[2], perp: inf[3] === 'F', id: s };
  }
  if (!inf && /^[A-Z0-9]+(USDT|USDC|FDUSD|BTC|ETH|BNB)$/.test(str)) {
    const [base, quote] = splitBaseQuote(str);
    return { ex: 'BINANCE', raw: str, base, quote, perp: false, id: str };
  }
  return null;
}

function cexMakeEntry(ex, raw, base, quote, perp, nameOpt, pxOpt) {
  const cleanRaw = String(raw).toUpperCase().replace(/[-_\/]/g, '').replace(/\.P$/i, '');
  const id = `${ex}:${cleanRaw}${perp ? '.P' : ''}`;
  const full = nameOpt || `${COIN_NAMES[base] || base} / ${quote === 'USDT' ? 'TetherUS' : quote}${perp ? ' Perpetual' : ''}`;
  return [id, base, quote, perp ? 'F' : 'S', full, null, ex, pxOpt || 100, ex];
}

const cexOf = s => { const p = cexParse(s); return p ? p.ex : null; };
const isBinance = s => cexOf(s) === 'BINANCE';
const isAltCex = s => { const e = cexOf(s); return !!e && e !== 'BINANCE'; };

const ALL_POOL = () => {
  if (!CEX_POOL_CACHE) rebuildCexPool();
  return GLOBAL_SYMS.concat(CUSTOM_SYMS, SL, CEX_POOL_CACHE);
};
const symInfo = s => {
  if (!s) return null;
  const hit = GLOBAL_MAP[s] || CUSTOM_MAP[s] || CEX_MAP[s] || SL.find(x => x[0] == s);
  if (hit) return hit;
  const cp = cexParse(s);
  if (cp) return cexMakeEntry(cp.ex, cp.raw, cp.base, cp.quote, cp.perp);
  return null;
};
const isCrypto = s => { const m = mkt(s); return m === 'S' || m === 'F'; };
const nm = s => {
  const x = symInfo(s);
  if (x && x[4]) return x[4];
  return NAMES[s] || (x ? x[1] + ' / ' + x[2] : s);
};
const lab = s => {
  const x = symInfo(s);
  if (!x) return s;
  const m = x[3];
  if (m === 'S' || m === 'F') {
    const ex = x[6] || 'BINANCE';
    const pair = x[1] + '/' + x[2] + (m === 'F' && x[0].endsWith('.P') ? '.P' : '');
    return ex === 'BINANCE' && !x[0].startsWith('BINANCE:') ? pair : `${ex}:${pair}`;
  }
  return m === 'FX' ? (x[1] + '/' + x[2]) : x[0];
};
