// --- UNIFIED LIVE PRICE STORE, WEBSOCKET & 5Y ELLIOTT WAVE HISTORY ENGINE ---
const FIVE_Y_MS = 5 * 365.25 * 864e5;
const LIVE_PX = {};   // LIVE_PX[sym] = {p, t, bid, ask} — single source of truth across ALL timeframes
const DAY_REF = {};   // DAY_REF[sym] = {pd, h, l, t} — UTC daily reference consistent across all TFs
const HCACHE  = {};   // HCACHE[sym+':'+base] = {arr, done, mkt} — instant TF switching & deep history cache
