function symEndpoints(s){
  const cp = cexParse(s);
  const m0 = (cp && cp.perp) ? 'F' : (mkt(s) || 'S');
  const raw = (cp && cp.raw) ? cp.raw : s;
  if(m0 === 'F') return { m:'F', raw, rest:[['https://fapi.binance.com','/fapi/v1']], ws:['wss://fstream.binance.com'] };
  return {
    m:'S', raw,
    rest:[['https://api.binance.com','/api/v3'], ['https://data-api.binance.vision','/api/v3']],
    ws:['wss://stream.binance.com:9443', 'wss://data-stream.binance.vision']
  };
}

function setLivePx(s, px, ts, bid, ask, prio){
  px = +px; if(!(px > 0)) return;
  const now = Date.now();
  const pr = (prio === true) ? 2 : (+prio || 1); // 3=WS Trade/Deal, 2=WS Ticker/Kline/BBO, 1=REST
  const cur = LIVE_PX[s];
  const syncBA = () => {
    if(!cur) return;
    if(bid != null && +bid > 0) cur.bid = +bid;
    if(ask != null && +ask > 0) cur.ask = +ask;
    if(s === sym && cur.bid && cur.ask) BA = { b: cur.bid, a: cur.ask };
  };
  // Never let REST (1) overwrite fresh WS (2/3)
  if(pr === 1 && cur && cur.wsT && (now - cur.wsT) < 3500){ syncBA(); return; }
  // Never let slower batched WS kline/ticker (2) overwrite real-time WS trade tick (3) received within 1.5s!
  if(pr === 2 && cur && cur.trT && (now - cur.trT) < 1500){ syncBA(); return; }
  // Always use local monotonic receive time so PC clock drift vs exchange server time NEVER drops live ticks!
  LIVE_PX[s] = {
    p: px,
    t: now,
    exTs: ts || now,
    wsT: pr >= 2 ? now : (cur ? (cur.wsT || 0) : 0),
    trT: pr >= 3 ? now : (cur ? (cur.trT || 0) : 0),
    bid: (bid != null && +bid > 0) ? +bid : (cur ? cur.bid : 0),
    ask: (ask != null && +ask > 0) ? +ask : (cur ? cur.ask : 0)
  };
  if(DAY_REF[s]){
    if(px > DAY_REF[s].h) DAY_REF[s].h = px;
    if(px < DAY_REF[s].l) DAY_REF[s].l = px;
  }
  if(s === sym && LIVE_PX[s].bid && LIVE_PX[s].ask){
    BA = { b: LIVE_PX[s].bid, a: LIVE_PX[s].ask };
  }
}

function candleCloseTime(t, I){
  if(!I) return t + 18e4;
  if(I.u === 'M'){
    const d = new Date(t);
    return Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + I.n, 1);
  }
  return t + I.ms;
}

function candleOpenTime(now, I){
  if(!I) return Math.floor(now / 18e4) * 18e4;
  if(I.u === 'M'){
    const d = new Date(now);
    const mi = Math.floor((d.getUTCFullYear()*12 + d.getUTCMonth()) / I.n) * I.n;
    return Date.UTC(Math.floor(mi/12), mi%12, 1);
  }
  if(I.u === 'w') return Math.floor((now - 3456e5) / I.ms) * I.ms + 3456e5;
  return Math.floor(now / I.ms) * I.ms;
}

// Anchors the active candle of ANY timeframe to the single authoritative LIVE_PX[s]
function syncLiveCandle(arr, s, I){
  if(!arr || !arr.length) return;
  const lp = LIVE_PX[s];
  if(!lp || !(lp.p > 0)) return;
  const px = lp.p, now = Date.now();
  let last = arr[arr.length - 1];
  // Spike guard: reject stale/mismatched quotes (e.g. >3% instant jump on FX or stale >6h gap on intraday)
  if(last.c > 0){
    const maxJump = mkt(s) === 'FX' ? 0.025 : 0.15;
    if(Math.abs(px - last.c) / last.c > maxJump) return;
  }
  if(I && I.k === 'time'){
    const ct = candleCloseTime(last.t, I);
    // Only auto-open a new candle if the previous candle is recent (prevents drawing fake bar across weekend close)
    if(now >= ct && (now - ct) < Math.max(I.ms * 4, 600000)){
      const nt = candleOpenTime(now, I);
      if(nt > last.t){
        last = { t: nt, o: last.c, h: Math.max(last.c, px), l: Math.min(last.c, px), c: px, v: 0, tb: 0 };
        arr.push(last);
      }
    }
  }
  last.c = px;
  if(px > last.h) last.h = px;
  if(px < last.l) last.l = px;
}

// Deterministic multi-year offline simulator anchored to a single DEMO_PX[s] across ALL timeframes
function simBuild(s, tfId, bars, anchorPx){
  const I = ti(tfId) || ti('3m');
  const inf = symInfo(s), mt = inf ? inf[3] : 'S';
  const base0 = anchorPx || (LIVE_PX[s] && LIVE_PX[s].p) || (inf && inf[7])
    || {BTCUSDT:61000,ETHUSDT:2400,SOLUSDT:140,BNBUSDT:580,XRPUSDT:.55,EURUSDT:1.08,GBPUSDT:1.27,PAXGUSDT:2650}[s]
    || (10 + [...s].reduce((a,c)=>a+c.charCodeAt(0),0) % 400);
  const volF = mt === 'FX' ? 0.18 : mt === 'BND' ? 0.25 : (mt === 'IDX' || mt === 'ETF' || mt === 'FUT') ? 0.45 : mt === 'STK' ? 0.65 : 1.0;
  const seed = [...s].reduce((a,c)=>((a*31)+c.charCodeAt(0))>>>0, 7);
  const m = I.k === 'time' ? I.ms : 6e4;
  const now = Date.now();
  const n = bars || Math.min(2500, Math.max(800, Math.ceil(FIVE_Y_MS / m)));
  const wavePx = t => {
    const d = t / 864e5;
    const cyc = 1 + volF*(0.30*Math.sin(d/240 + seed%7) + 0.15*Math.sin(d/65 + seed%13)
      + 0.065*Math.sin(d/14 + seed%19) + 0.02*Math.sin(d*2.1 + seed%29)
      + 0.006*Math.sin(d*48 + seed%37));
    return Math.max(base0 * 0.25, base0 * cyc);
  };
  if(anchorPx) DEMO_PX[s] = anchorPx;
  else if(!DEMO_PX[s]) DEMO_PX[s] = base0;
  const scale = DEMO_PX[s] / wavePx(now);
  const lastT = candleOpenTime(now, I);
  const out = [];
  for(let i = n - 1; i >= 0; i--){
    const t = lastT - i * m;
    const o = wavePx(t) * scale;
    const c = i === 0 ? DEMO_PX[s] : wavePx(t + m) * scale;
    const mid = wavePx(t + m * 0.5) * scale;
    const sp = Math.abs(c - o) * 0.35 + o * (0.0014 * volF);
    const h = Math.max(o, c, mid) + sp;
    const l = Math.min(o, c, mid) - sp;
    const vol = 200 + Math.abs(Math.sin(t/1e5 + seed)) * 800;
    out.push({ t, o, h, l, c, v: vol, tb: vol * (c >= o ? 0.6 : 0.4) });
  }
  out.key = s + tfId;
  return out;
}
