function ti(id){
  id = String(id);
  if(TIC[id] !== undefined) return TIC[id];
  let r = null;
  const m = /^([1-9]\d{0,4})([tsmhdwMR])$/.exec(id);
  if(m){
    const n = +m[1], u = m[2];
    if(n <= TFLIM[u]){
      r = { id, n, u };
      if(u === 't'){ r.k = 'tick'; r.ms = 1e3; }
      else if(u === 'R'){ r.k = 'range'; r.ms = 1e3; }
      else {
        r.k = 'time'; r.ms = n * TFC1[u];
        let b, bm = 1;
        if(u === 's'){ b = '1s'; bm = n; }
        else if(u === 'm'){
          const q = [[30,'30m'],[15,'15m'],[5,'5m'],[3,'3m']].find(x => n % x[0] === 0);
          b = q ? q[1] : '1m'; bm = n / (q ? q[0] : 1);
        } else if(u === 'h'){
          const q = [[12,'12h'],[8,'8h'],[6,'6h'],[4,'4h'],[2,'2h']].find(x => n % x[0] === 0);
          b = q ? q[1] : '1h'; bm = n / (q ? q[0] : 1);
        } else if(u === 'd'){
          if(n % 3 === 0){ b = '3d'; bm = n / 3; } else { b = '1d'; bm = n; }
        } else { b = '1' + u; bm = n; }
        r.base = b; r.mult = bm; r.bms = TFC1[b.slice(-1)] * parseInt(b);
      }
    }
  }
  return TIC[id] = r;
}
const tfS = id => { id = id || tf; const I = ti(id); return I ? I.n + (I.u=='t'?'T':I.u) : id; };
const tfL = id => { const I = ti(id); return I.n + ' ' + TFU[I.u] + (I.n==1?'':'s'); };

let BK = null, TR = null;
// Always pass OLDER first, NEWER second so newer live candles NEVER get overwritten!
const mg = (older, newer) => {
  const m = new Map();
  if(older) older.forEach(k => m.set(k.t, k));
  if(newer) newer.forEach(k => m.set(k.t, k));
  return [...m.values()].sort((x, y) => x.t - y.t);
};

// Initial target base candles: 5-10Y immediately on 1M/1w/3d/1d/12h, deep history + auto-backfill on lower TFs
function initChunks(I){
  if(I.base === '1M' || I.base === '1w' || I.base === '3d') return 1; // 1000 bars = 8-10+ years
  if(I.base === '1d') return 3;   // 3,000 bars = ~8.2 years!
  if(I.base === '12h') return 4;  // 4,000 bars = ~5.5 years!
  if(I.base === '8h' || I.base === '6h') return 5; // 5,000 bars = 3.5-4.5 years (backfills to 5Y+)
  if(I.base === '4h') return 5;   // 5,000 bars = ~2.3 years initially (scroll/5Y backfills to 11,500+ bars / 5Y+)
  if(I.base === '1s') return Math.min(12, Math.max(4, Math.ceil(260 * I.mult / 1000))); // ~260-4000 real second-bars!
  return Math.min(5, Math.max(3, Math.ceil(2500 * I.mult / 1000))); // 3,000-5,000 base bars on intraday
}

async function fetchKlinePage(h, pre, s, base, limit, endTime){
  let u = `${h}${pre}/klines?symbol=${s}&interval=${base}&limit=${limit}`;
  if(endTime != null) u += `&endTime=${endTime}`;
  const r = await fetch(u);
  if(!r.ok) throw new Error('HTTP ' + r.status);
  const j = await r.json();
  return j.map(k => ({ t: k[0], o: +k[1], h: +k[2], l: +k[3], c: +k[4], v: +k[5], tb: +k[9] }));
}

// Chained exact-endTime pagination: zero gaps, zero overlaps, newest ALWAYS wins
async function kl(h, pre, s, I, chunks, endTime){
  let merged = [];
  let cursor = endTime;
  let reachedStart = false;
  for(let j = 0; j < chunks; j++){
    const page = await fetchKlinePage(h, pre, s, I.base, 1000, cursor);
    if(!page.length){ reachedStart = true; break; }
    merged = mg(page, merged);
    if(page.length < 1000){ reachedStart = true; break; }
    cursor = page[0].t - 1;
    if(I.bms >= 864e5 && merged[0].t <= Date.now() - FIVE_Y_MS * 1.15) break;
  }
  return { arr: merged, done: reachedStart };
}

function agg(K, I){
  if(I.mult === 1) return K.slice();
  const out = []; let cur = null, ck = null;
  for(const k of K){
    let key, st;
    if(I.u === 'M'){
      const d = new Date(k.t), mi = d.getUTCFullYear()*12 + d.getUTCMonth();
      key = Math.floor(mi / I.n); st = Date.UTC(Math.floor(key*I.n/12), (key*I.n)%12, 1);
    } else if(I.u === 'w'){
      key = Math.floor((k.t - 3456e5) / I.ms); st = key*I.ms + 3456e5;
    } else {
      key = Math.floor(k.t / I.ms); st = key * I.ms;
    }
    if(key !== ck){
      if(cur) out.push(cur);
      ck = key;
      cur = { t: st, o: k.o, h: k.h, l: k.l, c: k.c, v: k.v, tb: k.tb };
    } else {
      cur.h = Math.max(cur.h, k.h);
      cur.l = Math.min(cur.l, k.l);
      cur.c = k.c; cur.v += k.v; cur.tb += k.tb;
    }
  }
  if(cur) out.push(cur);
  return out;
}

const TR_MAX_TRADES = 350000;
const TR_MAX_BARS   = 10000;

function trDecOf(rawArr){
  let d = 0;
  for(let i = 0; i < rawArr.length; i++){
    const ps = String(rawArr[i].p);
    const pt = ps.indexOf('.');
    if(pt >= 0){
      const fr = ps.slice(pt + 1).replace(/0+$/, '');
      if(fr.length > d) d = fr.length;
    }
  }
  return d;
}

function tradesTo1sBars(trades){
  if(!trades || !trades.length) return [];
  const out = [];
  let cur = null, ck = -1;
  for(let i = 0; i < trades.length; i++){
    const x = trades[i], p = x.p, q = x.q || 0, sec = Math.floor(x.t / 1000);
    if(sec !== ck){
      if(cur) out.push(cur);
      ck = sec;
      cur = { t: sec * 1000, o: p, h: p, l: p, c: p, v: q, tb: x.m ? 0 : q };
    } else {
      if(p > cur.h) cur.h = p;
      if(p < cur.l) cur.l = p;
      cur.c = p; cur.v += q; if(!x.m) cur.tb += q;
    }
  }
  if(cur) out.push(cur);
  return out;
}

async function fetchAggTradesWaves(u, firstId, pages, conc){
  const step = conc || 6;
  const chunks = [];
  let curFirst = firstId;
  for(let done = 0; done < pages && curFirst > 1; ){
    const batch = Math.min(step, pages - done);
    const reqs = [];
    for(let k = 1; k <= batch; k++){
      const st = curFirst - 1000 * k;
      if(st < 0) break;
      reqs.push(fetch(u + '&fromId=' + st + '&limit=1000').then(r => r.ok ? r.json() : []).catch(() => []));
    }
    if(!reqs.length) break;
    const res = await Promise.all(reqs);
    let gotAny = false;
    for(let k = 0; k < res.length; k++){
      if(Array.isArray(res[k]) && res[k].length){ chunks.push(res[k]); gotAny = true; }
    }
    if(!gotAny) break;
    curFirst -= 1000 * reqs.length;
    done += reqs.length;
  }
  // Sort oldest -> newest by aggTrade id
  chunks.sort((a, b) => a[0].a - b[0].a);
  return [].concat(...chunks);
}

// Fetch real 1-second OHLCV for Binance Futures (fapi has NO interval=1s!):
// Combines real Futures aggTrades on the live edge + basis-aligned Binance Spot 1s klines for deep history!
async function fetchBinanceFutures1s(rawSym, I, chunks, endTime, basisOpt){
  const spotHosts = [['https://api.binance.com','/api/v3'], ['https://data-api.binance.vision','/api/v3']];
  const futUrl = 'https://fapi.binance.com/fapi/v1/aggTrades?symbol=' + rawSym;
  const scaleBars = (bars, r) => (Math.abs(r - 1) < 1e-6 ? bars : bars.map(k => ({
    t: k.t, o: k.o * r, h: k.h * r, l: k.l * r, c: k.c * r, v: k.v, tb: k.tb
  })));

  // Backfill older 1s bars (scroll-left)
  if(endTime != null){
    const r0 = basisOpt || 1;
    for(const [sh, sp] of spotHosts){
      try{
        const res = await kl(sh, sp, rawSym, I, chunks, endTime);
        if(res.arr && res.arr.length) return { arr: scaleBars(res.arr, r0), done: res.done, basis: r0 };
      }catch(e){}
    }
    return { arr: [], done: true, basis: r0 };
  }

  // Initial load: fetch latest Futures aggTrades + Spot 1s klines in parallel!
  const futProm = (async () => {
    try{
      const r0 = await fetch(futUrl + '&limit=1000');
      if(!r0.ok) return [];
      const j0 = await r0.json();
      if(!Array.isArray(j0) || !j0.length) return [];
      const old = await fetchAggTradesWaves(futUrl, j0[0].a, 10, 5);
      const all = old.concat(j0).map(x => ({ a: x.a, t: x.T, p: +x.p, q: +x.q, m: x.m }));
      return tradesTo1sBars(all);
    }catch(e){ return []; }
  })();

  const spotProm = (async () => {
    for(const [sh, sp] of spotHosts){
      try{
        const res = await kl(sh, sp, rawSym, I, chunks);
        if(res.arr && res.arr.length) return res;
      }catch(e){}
    }
    return null;
  })();

  const [futBars, spotRes] = await Promise.all([futProm, spotProm]);

  if(futBars.length && spotRes && spotRes.arr.length){
    const cutT = futBars[0].t;
    const futBoundary = futBars[0].o;
    // Find Spot bar closest to Futures aggTrades start time for seamless basis alignment
    let spotMatch = spotRes.arr[spotRes.arr.length - 1];
    for(let i = spotRes.arr.length - 1; i >= 0; i--){
      if(spotRes.arr[i].t <= cutT){ spotMatch = spotRes.arr[i]; break; }
    }
    let ratio = (spotMatch && spotMatch.c > 0 && futBoundary > 0) ? (futBoundary / spotMatch.c) : 1;
    if(!(ratio > 0.96 && ratio < 1.04)) ratio = 1;
    const olderSpot = scaleBars(spotRes.arr.filter(k => k.t < cutT), ratio);
    const merged = olderSpot.concat(futBars);
    return { arr: merged, done: spotRes.done, basis: ratio };
  }
  if(futBars.length){
    // Futures-only token (no Spot pair): pull deeper Futures aggTrades (up to 35 pages)
    try{
      const r0 = await fetch(futUrl + '&limit=1000');
      const j0 = r0.ok ? await r0.json() : [];
      if(Array.isArray(j0) && j0.length){
        const old = await fetchAggTradesWaves(futUrl, j0[0].a, 35, 6);
        const all = old.concat(j0).map(x => ({ a: x.a, t: x.T, p: +x.p, q: +x.q, m: x.m }));
        return { arr: tradesTo1sBars(all), done: false, basis: 1 };
      }
    }catch(e){}
    return { arr: futBars, done: false, basis: 1 };
  }
  if(spotRes && spotRes.arr.length){
    // Fallback if fapi aggTrades temporarily throttled: align Spot 1s to live Futures price if known
    const fPx = LIVE_PX[sym] && LIVE_PX[sym].p;
    const sPx = spotRes.arr[spotRes.arr.length - 1].c;
    let ratio = (fPx > 0 && sPx > 0) ? (fPx / sPx) : 1;
    if(!(ratio > 0.96 && ratio < 1.04)) ratio = 1;
    return { arr: scaleBars(spotRes.arr, ratio), done: spotRes.done, basis: ratio };
  }
  return { arr: [], done: false, basis: 1 };
}

async function trd(h, pre, I, isBackfill, symOverride, rawOverride, basisOverride){
  const sUse = symOverride || sym;
  const rawSym = rawOverride || symEndpoints(sUse).raw;
  const u = h + pre + '/aggTrades?symbol=' + rawSym;
  const key = sUse + tf;
  const scale = (basisOverride && Math.abs(basisOverride - 1) > 1e-6) ? basisOverride : 1;
  const mp = x => ({ a: x.a, t: x.T, p: (+x.p) * scale, q: +x.q, m: x.m });
  const J = async q => { const r = await fetch(u + q); if(!r.ok) throw 0; return r.json(); };

  // Scroll-left backfill for Ticks / Range!
  if(isBackfill && TR && TR.key === key && TR.first > 1 && !TR.done){
    const olderRaw = await fetchAggTradesWaves(u, TR.first, 45, 6);
    if(!olderRaw.length){ TR.done = true; return false; }
    const dedup = olderRaw.filter(x => x.a < TR.first);
    if(!dedup.length){ TR.done = true; return false; }
    TR.dc = Math.max(TR.dc, trDecOf(dedup));
    TR.tk = Math.pow(10, -TR.dc);
    const mapped = dedup.map(mp);
    TR.arr = mapped.concat(TR.arr);
    TR.first = TR.arr[0].a;
    if(TR.arr.length > TR_MAX_TRADES){
      const cut = TR.arr.length - TR_MAX_TRADES;
      const ex = I.k === 'tick' ? Math.ceil(cut / I.n) * I.n : cut;
      TR.arr = TR.arr.slice(ex);
      TR.first = TR.arr[0].a;
      TR.done = true;
    }
    return true;
  }

  // Incremental live top-up
  if(TR && TR.key === key && TR.src === 'binance'){
    let n = 0, more = 1;
    while(more && n < 6){
      const j = await J('&fromId=' + (TR.last + 1) + '&limit=1000'); n++;
      if(!j.length) break;
      TR.dc = Math.max(TR.dc, trDecOf(j));
      const a = j.filter(x => x.a > TR.last).map(mp);
      if(!a.length) break;
      TR.arr = TR.arr.concat(a);
      TR.last = a[a.length - 1].a;
      more = j.length === 1000;
    }
    if(TR.arr.length > TR_MAX_TRADES){
      const cut = TR.arr.length - TR_MAX_TRADES, ex = I.k === 'tick' ? Math.ceil(cut / I.n) * I.n : cut;
      TR.arr = TR.arr.slice(ex);
      TR.first = TR.arr[0].a;
    }
  } else {
    // Deep initial load: 20-90 pages (20,000 - 90,000 real aggTrades!) with adaptive Range expansion
    const j0 = await J('&limit=1000'); if(!j0.length) throw 0;
    const initPages = I.k === 'tick'
      ? Math.max(15, Math.min(90, Math.ceil(Math.min(800, Math.max(120, 450)) * I.n / 1000)))
      : 30;
    const f0 = j0[0].a;
    let old = await fetchAggTradesWaves(u, f0, initPages, 6);
    let raw = old.concat(j0);
    let curFirst = raw[0].a;
    let dc0 = trDecOf(raw);
    let tk0 = Math.pow(10, -dc0);

    // Adaptive depth for Range bars (100R / 1000R): keep fetching older waves until >= 150 bars or 90 pages!
    if(I.k === 'range'){
      let totalPages = initPages;
      while(totalPages < 90 && curFirst > 1000){
        const testBars = bRg(raw.map(mp), I.n * tk0);
        if(testBars.length >= 150) break;
        const moreOld = await fetchAggTradesWaves(u, curFirst, 30, 6);
        if(!moreOld.length) break;
        const cleanMore = moreOld.filter(x => x.a < curFirst);
        if(!cleanMore.length) break;
        raw = cleanMore.concat(raw);
        curFirst = raw[0].a;
        dc0 = Math.max(dc0, trDecOf(cleanMore));
        tk0 = Math.pow(10, -dc0);
        totalPages += 30;
      }
    }
    const mapped = raw.map(mp);
    TR = {
      key, src: 'binance', h, pre, rawSym, scale,
      arr: mapped, first: mapped[0].a, last: mapped[mapped.length - 1].a,
      dc: dc0, tk: tk0, done: false
    };
  }
  TR.tk = Math.pow(10, -TR.dc);
  if(TR.arr.length) setLivePx(sUse, TR.arr[TR.arr.length - 1].p, TR.arr[TR.arr.length - 1].t);
  return true;
}

function trBuildBars(I){
  if(!TR || !TR.arr || !TR.arr.length) return [];
  const bars = (I.k === 'tick' ? bTk(TR.arr, I.n) : bRg(TR.arr, I.n * TR.tk));
  return bars.length > TR_MAX_BARS ? bars.slice(-TR_MAX_BARS) : bars;
}

// Feed real-time WebSocket trade/tick directly into TR.arr for 0ms live Tick & Range bar updates!
function trPushLiveTrade(s, px, qty, ts, idOpt, isBuyerMaker){
  if(s !== sym || !TR || TR.key !== sym + tf || (typeof RPL !== 'undefined' && RPL.active)) return false;
  const I = ti(tf);
  if(!I || (I.k !== 'tick' && I.k !== 'range')) return false;
  if(idOpt != null && TR.last != null && idOpt <= TR.last) return false;
  const nextId = idOpt != null ? idOpt : ((TR.last || 0) + 1);
  const trItem = { a: nextId, t: ts || Date.now(), p: +px, q: +qty || 1, m: !!isBuyerMaker };
  TR.arr.push(trItem);
  TR.last = nextId;
  if(TR.arr.length > TR_MAX_TRADES){
    const cut = TR.arr.length - TR_MAX_TRADES;
    const ex = I.k === 'tick' ? Math.ceil(cut / I.n) * I.n : cut;
    TR.arr = TR.arr.slice(ex);
    TR.first = TR.arr[0].a;
  }
  // Fast incremental update of the active Tick or Range bar in D (O(1) per tick!)
  if(!D.length){
    D = trBuildBars(I); D.key = sym + tf;
    return true;
  }
  const last = D[D.length - 1];
  let newBar = false;
  if(I.k === 'tick'){
    if((last.n || 0) >= I.n){
      D.push({ t: trItem.t, o: trItem.p, h: trItem.p, l: trItem.p, c: trItem.p, v: trItem.q, tb: trItem.m ? 0 : trItem.q, n: 1 });
      if(D.length > TR_MAX_BARS) D.shift();
      newBar = true;
    } else {
      if(trItem.p > last.h) last.h = trItem.p;
      if(trItem.p < last.l) last.l = trItem.p;
      last.c = trItem.p; last.v += trItem.q; if(!trItem.m) last.tb += trItem.q; last.n = (last.n || 0) + 1;
    }
  } else {
    const sz = I.n * (TR.tk || 1e-4);
    if(last.h - last.l >= sz - sz * 1e-9){
      D.push({ t: trItem.t, o: trItem.p, h: trItem.p, l: trItem.p, c: trItem.p, v: trItem.q, tb: trItem.m ? 0 : trItem.q, n: 1 });
      if(D.length > TR_MAX_BARS) D.shift();
      newBar = true;
    } else {
      if(trItem.p > last.h) last.h = trItem.p;
      if(trItem.p < last.l) last.l = trItem.p;
      last.c = trItem.p; last.v += trItem.q; if(!trItem.m) last.tb += trItem.q; last.n = (last.n || 0) + 1;
    }
  }
  chkBr(); chkAlr(); updHistStat(); schedDraw(); schedCalc(newBar);
  return true;
}

function bTk(a,N){const o=[];for(let i=0;i<a.length;i+=N){const e=Math.min(a.length,i+N),f=a[i];let h=f.p,l=f.p,v=0,tb=0;for(let j=i;j<e;j++){const x=a[j];if(x.p>h)h=x.p;if(x.p<l)l=x.p;v+=x.q;if(!x.m)tb+=x.q}o.push({t:f.t,o:f.p,h,l,c:a[e-1].p,v,tb,n:e-i})}return o}
function bRg(a,size){const o=[];let b=null;for(const x of a){if(!b)b={t:x.t,o:x.p,h:x.p,l:x.p,c:x.p,v:0,tb:0,n:0};if(x.p>b.h)b.h=x.p;if(x.p<b.l)b.l=x.p;b.c=x.p;b.v+=x.q;if(!x.m)b.tb+=x.q;b.n++;if(b.h-b.l>=size-size*1e-9){o.push(b);b=null}}if(b)o.push(b);return o}


