function parts(t,z){z=z||(CFG.tz=='local'?'':CFG.tz);let f=PFc[z];if(!f){try{f=PFc[z]=new Intl.DateTimeFormat('en-US',{timeZone:z||undefined,year:'numeric',month:'numeric',day:'numeric',weekday:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'})}catch(e){return null}}const r={};f.formatToParts(new Date(t)).forEach(p=>r[p.type]=p.value);return r}
function fmtD(t,pat,z){const q=parts(t,z);if(!q)return'';const m=+q.month,d=+q.day,y=q.year;return pat.replace(/YYYY|YY|MMM|MM|DD|D|ddd|QQ/g,k=>({YYYY:y,YY:y.slice(-2),MMM:MN[m-1],MM:String(m).padStart(2,'0'),DD:String(d).padStart(2,'0'),D:d,ddd:q.weekday,QQ:'Q'+Math.ceil(m/3)})[k])}
