function lvl(p,c,V,L){const y=py(p);if(!(y>0&&y<PH))return;if(L){X.strokeStyle=c;X.lineWidth=1;X.setLineDash([2,3]);X.beginPath();X.moveTo(X0,y);X.lineTo(X1,y);X.stroke();X.setLineDash([])}if(V)lbl(p,y,c)}
