function indCatalogItems(){
  const items=[];
  IND.forEach(i=>{
    const m=IND_NATIVE_META[i[0]]||{cat:'trend',grp:'tech',author:'DreamX Built-in'};
    items.push({id:i[0],name:indTitle(i[0]),rawName:i[1],desc:i[2],overlay:i[3]==='o',cat:m.cat,grp:m.grp,author:m.author,kind:'native'});
  });
  TV_PACK.forEach(p=>{
    items.push({id:p.id,name:p.name,rawName:p.name,desc:p.desc||'',overlay:!!p.overlay,cat:p.cat||'trend',grp:p.grp||'tech',author:p.author||'TradingView Pack',kind:'tv'});
  });
  return items;
}
function pineDownloadFile(filename, content, mime){
  const blob=new Blob([content],{type:mime||'text/plain;charset=utf-8'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download=filename;
  document.body.appendChild(a);
  a.click();
  setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},300);
}
function pineExportSingle(obj, isLib){
  if(!obj||!obj.code)return;
  const base=String(obj.name||'indicator').replace(/[^a-zA-Z0-9_\-]+/g,'_').replace(/^_+|_+$/g,'')||'script';
  pineDownloadFile(base+(isLib?'_lib':'')+'.pine', obj.code, 'text/plain;charset=utf-8');
  toast('Exported '+base+(isLib?'_lib':'')+'.pine');
}
function pineExportPack(libsOnly){
  const pack={
    type:'dreamx_pine_pack',
    version:1,
    exportedAt:new Date().toISOString(),
    scripts:libsOnly?[]:PINE_SCRIPTS.map(s=>({name:s.name,shorttitle:s.shorttitle||s.name,overlay:!!s.overlay,modeOverride:s.modeOverride||'auto',code:s.code})),
    libraries:PINE_LIBS.map(l=>({name:l.name,path:l.path,desc:l.desc||'',code:l.code})),
    favorites:libsOnly?[]:IND_FAV.slice()
  };
  const dStr=new Date().toISOString().slice(0,10);
  const fname=(libsOnly?'DreamX-Pine-Libraries-':'DreamX-Pine-Pack-')+dStr+'.json';
  pineDownloadFile(fname, JSON.stringify(pack,null,2), 'application/json;charset=utf-8');
  toast(`Exported ${pack.scripts.length} script(s) & ${pack.libraries.length} librar${pack.libraries.length===1?'y':'ies'}`);
}
function pineIngestText(rawText, fileName, forceLib){
  const txt=String(rawText||'').trim();
  if(!txt)return {scripts:0,libs:0,errs:0};
  const out={scripts:0,libs:0,errs:0};
  // Try JSON DreamX Pack first
  if(txt[0]==='{'||txt[0]==='['){
    try{
      const j=JSON.parse(txt);
      const libList=Array.isArray(j.libraries)?j.libraries:[];
      const scrList=Array.isArray(j)?j:(Array.isArray(j.scripts)?j.scripts:[]);
      if(libList.length||scrList.length||j.type==='dreamx_pine_pack'){
        libList.forEach(l=>{
          if(!l||typeof l.code!=='string'||!l.code.trim())return;
          const m=pineExtractMeta(l.code);
          const nm0=String(l.name||m.name||'Library').trim();
          const pth=pineLibNormPath(l.path||('Custom/'+nm0.replace(/\s+/g,'_')+'/1'));
          const ex=PINE_LIBS.find(x=>pineLibNormPath(x.path).toLowerCase()===pth.toLowerCase());
          if(ex){ex.name=nm0;ex.code=l.code;if(l.desc)ex.desc=l.desc}
          else PINE_LIBS.push({id:'plib_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,6),name:nm0,path:pth,desc:l.desc||'',code:l.code});
          out.libs++;
        });
        scrList.forEach(s=>{
          if(!s||typeof s.code!=='string'||!s.code.trim())return;
          const m=pineExtractMeta(s.code);
          const nm0=String(s.name||m.name||'Imported Script').trim();
          const ov=(s.overlay!=null)?!!s.overlay:m.overlay;
          const ex=PINE_SCRIPTS.find(x=>x.name.toLowerCase()===nm0.toLowerCase());
          if(ex){ex.code=s.code;ex.overlay=ov;ex.shorttitle=s.shorttitle||m.shorttitle||nm0}
          else PINE_SCRIPTS.push({id:'pine_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,6),name:nm0,shorttitle:s.shorttitle||m.shorttitle||nm0,overlay:ov,modeOverride:s.modeOverride||'auto',code:s.code});
          out.scripts++;
        });
        if(Array.isArray(j.favorites)){
          j.favorites.forEach(fid=>{if(typeof fid==='string'&&!IND_FAV.includes(fid))IND_FAV.push(fid)});
          svIndFav();
        }
        return out;
      }
    }catch(e){}
  }
  // Plain .pine / .txt script or library
  const meta=pineExtractMeta(txt);
  const cleanFile=String(fileName||'').replace(/\.[^.]+$/,'').trim();
  const isLib=forceLib||meta.isLibrary;
  if(isLib){
    const nm0=(meta.name&&meta.name!=='Custom Pine Indicator')?meta.name:(cleanFile||'CustomLib');
    const safeSeg=nm0.replace(/[^a-zA-Z0-9_]+/g,'_').replace(/^_+|_+$/g,'')||'CustomLib';
    const pth='Custom/'+safeSeg+'/1';
    const ex=PINE_LIBS.find(x=>x.name.toLowerCase()===nm0.toLowerCase()||pineLibNormPath(x.path).toLowerCase()===pth.toLowerCase());
    if(ex){ex.code=txt;ex.name=nm0}
    else PINE_LIBS.push({id:'plib_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,6),name:nm0,path:pth,desc:'Imported Pine Library',code:txt});
    out.libs++;
  }else{
    const nm0=(meta.name&&meta.name!=='Custom Pine Indicator')?meta.name:(cleanFile||'Imported Indicator');
    const ex=PINE_SCRIPTS.find(x=>x.name.toLowerCase()===nm0.toLowerCase());
    if(ex){ex.code=txt;ex.overlay=meta.overlay;ex.shorttitle=meta.shorttitle||nm0}
    else PINE_SCRIPTS.push({id:'pine_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,6),name:nm0,shorttitle:meta.shorttitle||nm0,overlay:meta.overlay,modeOverride:'auto',code:txt});
    out.scripts++;
  }
  return out;
}
function pineHandleFileList(fileList, forceLib){
  const files=Array.from(fileList||[]);
  if(!files.length)return;
  let totS=0, totL=0, done=0;
  files.forEach(fl=>{
    const r=new FileReader();
    r.onload=()=>{
      const res=pineIngestText(String(r.result||''),fl.name,forceLib);
      totS+=res.scripts; totL+=res.libs;
      if(++done===files.length){
        PINE_COMPILE_CACHE.clear();
        svPines(); svPineLibs();
        if(totL&&!totS)IND_TAB='libs';
        else if(totS)IND_TAB='my';
        rl(); ismRecalcRedraw();
        if(totS||totL)toast(`Imported ${totS} indicator${totS===1?'':'s'} & ${totL} librar${totL===1?'y':'ies'}`);
        else toast('No valid Pine Script or Pack JSON found');
      }
    };
    r.onerror=()=>{if(++done===files.length)rl()};
    r.readAsText(fl);
  });
}
function pineBulkImport(forceLib){
  const inp=document.createElement('input');
  inp.type='file'; inp.multiple=true; inp.accept='.pine,.txt,.json,.pinescript,*/*';
  inp.onchange=()=>{if(inp.files&&inp.files.length)pineHandleFileList(inp.files,forceLib)};
  inp.click();
}
function pineLibDelete(id){
  const lib=pineLibGet(id);if(!lib)return;
  if(!confirm('Delete library "'+lib.path+'"?'))return;
  PINE_LIBS=PINE_LIBS.filter(x=>x.id!==id);
  svPineLibs();
  PINE_COMPILE_CACHE.clear();
  rl(); ismRecalcRedraw();
  toast('Deleted library '+lib.path);
}
