// --- COMPARE INSTRUMENTS ---
const CMPC=['#ff9800','#2962ff','#e91e63','#00bcd4','#ab47bc','#8bc34a'];
let CMPS=[];
async function cmpFetch(s){
  const I=ti(tf);
  if(!isCrypto(s)){
    const res=await fetchNonCrypto(s,I,false,false);
    if(res&&res.arr&&res.arr.length)return res.arr.map(k=>({t:k.t,c:k.c}));
  }else if(isAltCex(s)){
    const res=await fetchAltCexCandles(s,I,false,null);
    if(res&&res.arr&&res.arr.length)return res.arr.map(k=>({t:k.t,c:k.c}));
  }else if(I.k=='time'){
    const ep=symEndpoints(s);
    for(const [h,pre] of ep.rest){
      try{
        const r=await fetch(h+pre+`/klines?symbol=${ep.raw}&interval=${I.base}&limit=1000`);
        if(!r.ok)continue;
        const j=await r.json();
        return agg(j.map(k=>({t:k[0],c:+k[4]})),I);
      }catch(e){}
    }
  }
  return simBuild(s,tf,Math.max(400,D.length)).map(k=>({t:k.t,c:k.c}));
}
async function cmpAdd(s){
  if(s==sym||CMPS.some(x=>x.s==s))return;
  const c=CMPC[CMPS.length%CMPC.length];
  const item={s,c,d:[]};
  CMPS.push(item);
  rcmp();
  item.d=await cmpFetch(s);
  draw();
}
function cmpRem(s){CMPS=CMPS.filter(x=>x.s!=s);rcmp();draw()}
async function cmpRefresh(){
  for(const item of CMPS){item.d=await cmpFetch(item.s)}
  draw();
}
function cmpDraw(a,z){
  if(!CMPS.length||!D.length)return;
  const base0=D[a]?D[a].c:D[0].c;
  if(!base0)return;
  let ly=34;
  CMPS.forEach(item=>{
    if(!item.d||!item.d.length)return;
    const arr=item.d,nn=arr.length;
    const atT=t=>{
      if(t<arr[0].t-STEP()*3||t>arr[nn-1].t+STEP()*3)return null;
      let lo=0,hi=nn-1;
      while(lo<hi){const m=(lo+hi+1)>>1;if(arr[m].t<=t)lo=m;else hi=m-1}
      return arr[lo].c;
    };
    let c0=null;
    for(let i=a;i<=z;i++){const v=atT(D[i].t);if(v){c0=v;break}}
    if(!c0)c0=arr[0].c;
    X.strokeStyle=item.c;X.lineWidth=1.5;X.setLineDash([]);X.beginPath();
    let st=1,lastP=null;
    for(let i=a;i<=z;i++){
      const v=atT(D[i].t);
      if(!v){st=1;continue}
      const mapped=base0*(v/c0);
      lastP=((v-c0)/c0*100);
      const x=xi(i),y=py(mapped);
      st?X.moveTo(x,y):X.lineTo(x,y);st=0;
    }
    X.stroke();
    X.fillStyle=item.c;X.font='bold 11px system-ui';X.textAlign='left';
    X.fillText('● '+lab(item.s)+(lastP!=null?' ('+(lastP>=0?'+':'')+lastP.toFixed(2)+'%)':''),X0+12,PH-ly);
    ly+=15;
  });
}
function rcmp(skipRemote){
  const raw=$('#cmpq').value.trim(),t=raw.toUpperCase().replace(/[\/\s]/g,'');
  if(!skipRemote)schedYfSearch(raw);
  $('#cmptags').innerHTML=CMPS.length?CMPS.map(x=>`<span class="ctag" style="border-color:${x.c}"><span style="color:${x.c}">●</span> ${lab(x.s)} <button data-cr="${x.s}">✕</button></span>`).join(''):'<span class="mu" style="font-size:12px">No comparison instruments added yet.</span>';
  $('#cmpqf').innerHTML=['All','Forex','Stocks','Indices','Commodities','Futures','ETFs','Bonds','Crypto'].map(q=>`<button data-cq="${q}" class="${CMPF==q?'on':''}">${q}</button>`).join('');
  const pool=ALL_POOL();
  const l=pool.filter(x=>x[0]!=sym&&symCatMatch(x,CMPF,'All')&&(!t||x[0].toUpperCase().includes(t)||x[1].toUpperCase().includes(t)||(x[1]+x[2]).toUpperCase().includes(t)||(x[6]&&x[6].toUpperCase().includes(t))||(x[4]&&x[4].toUpperCase().includes(raw.toUpperCase())))).slice(0,120);
  let h=l.map(x=>symRowHtml(x,'cmp')).join('');
  if(raw.length>=2){
    const seen=new Set(l.map(x=>x[0]));
    const extra=YF_SEARCH_RES.filter(x=>x[0]!=sym&&!seen.has(x[0]));
    if(extra.length){
      h+=`<div class="sy-sec"><span>GLOBAL SEARCH</span><span>Yahoo Finance</span></div>`;
      h+=extra.map((x,idx)=>symRowHtml(x,'cmp').replace('data-cs="',`data-cyidx="${idx}" data-cs="`)).join('');
    }
  }
  $('#cmpls').innerHTML=h||'<div class="it">No symbols found</div>';
  document.querySelectorAll('#cmpqf [data-cq]').forEach(b=>b.onclick=()=>{CMPF=b.dataset.cq;rcmp(true)});
  document.querySelectorAll('#cmptags [data-cr]').forEach(b=>b.onclick=()=>cmpRem(b.dataset.cr));
  document.querySelectorAll('#cmpls [data-cs]').forEach(r=>r.onclick=()=>{
    const s=r.dataset.cs,yidx=r.dataset.cyidx;
    if(yidx!=null&&YF_SEARCH_RES[+yidx])addCustomSym(YF_SEARCH_RES[+yidx]);
    CMPS.some(c=>c.s==s)?cmpRem(s):cmpAdd(s);
  });
}
