function lytSvg(tpl,w,h){
  w=w||22;h=h||16;
  const pad=1.5,iw=w-2*pad,ih=h-2*pad;
  let rects='';
  tpl.c.forEach(c=>{
    const x=(pad+c[0]*iw).toFixed(2),y=(pad+c[1]*ih).toFixed(2),rw=(c[2]*iw).toFixed(2),rh=(c[3]*ih).toFixed(2);
    rects+=`<rect x="${x}" y="${y}" width="${rw}" height="${rh}"/>`;
  });
  return `<svg viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" fill="none" stroke="currentColor" stroke-width="1.35">${rects}</svg>`;
}

let LYT={id:'1_1',act:0,max:-1,sync:{sym:0,tf:0,ch:1,tm:0,dr:0},panes:[],chT:null,chP:null};
