  const tIdx2=t=>{if(n<2)return 0;if(t<=D2[0].t)return(t-D2[0].t)/stMs;if(t>=D2[n-1].t)return n-1+(t-D2[n-1].t)/stMs;let loI=0,hiI=n-1;while(hiI-loI>1){const m=(loI+hiI)>>1;if(D2[m].t<=t)loI=m;else hiI=m}return loI+(t-D2[loI].t)/((D2[hiI].t-D2[loI].t)||1)};
  const iTime2=f=>{if(n<2)return Date.now();if(f<=0)return D2[0].t+f*stMs;if(f>=n-1)return D2[n-1].t+(f-n+1)*stMs;const i=Math.floor(f);return D2[i].t+(f-i)*(D2[i+1].t-D2[i].t)};
