  ctx.save();ctx.beginPath();ctx.rect(X02,0,X12-X02,h-BX2);ctx.clip();
  p._lastG={Dp:Dp2,CD:CD2,cfg:CFG,a:aP2,z:zP2,xi:xiP2,ix:ixP2,py:py2,yp:yp2,bw:p.bw,X0:X02,X1:X12,PH:PH2,PT:PT2,LO:LO2,HI:HI2,tr:tr2,itr:itr2,tfId:p.tf,srcD:D2,sym:p.sym};
  ctRender(ctx,Dp2,CD2,CFG,p._lastG);
  const ln2=(arr,st,ob0)=>{if(!arr)return;const ob=Math.round(+ob0||0),i0=Math.max(0,a-Math.max(0,ob)-1),i1=Math.min(arr.length-1,z-Math.min(0,ob)+1);ctx.save();const w0=+st.w||1.2;ctx.strokeStyle=rgba(st.c,st.o==null?1:st.o);ctx.lineWidth=w0;ctx.setLineDash(dsh(st.s||'solid',w0));ctx.beginPath();let s0=1;for(let i=i0;i<=i1;i++){const v=arr[i];if(v!==v){s0=1;continue}const xx=xi2(i+ob);s0?ctx.moveTo(xx,py2(v)):ctx.lineTo(xx,py2(v));s0=0}ctx.stroke();ctx.restore()};
  if(p.ind.vwap&&indVisOk('vwap',p.tf)){const vc=indCfg('vwap');if(vc.b1on){ln2(p.S.vwapB1u,vc.b1,vc.off);ln2(p.S.vwapB1l,vc.b1,vc.off)}if(vc.b2on){ln2(p.S.vwapB2u,vc.b2,vc.off);ln2(p.S.vwapB2l,vc.b2,vc.off)}if(vc.b3on){ln2(p.S.vwapB3u,vc.b3,vc.off);ln2(p.S.vwapB3l,vc.b3,vc.off)}if(vc.ln.on)ln2(p.S.vwap,vc.ln,vc.off)}
  ['ema20','ema50','sma200'].forEach(id=>{if(!p.ind[id]||!indVisOk(id,p.tf))return;const mc=indCfg(id);if(mc.ln.on)ln2(p.S[id],mc.ln,mc.off);if(mc.smType!='none'&&p.S[id+'_sm'])ln2(p.S[id+'_sm'],mc.sm,mc.off)});
  if(p.ind.bb&&indVisOk('bb',p.tf)){const bc=indCfg('bb');if(bc.upper.on)ln2(p.S.bbu,bc.upper,bc.off);if(bc.lower.on)ln2(p.S.bbl,bc.lower,bc.off);if(bc.basis.on)ln2(p.S.bbm,bc.basis,bc.off)}
  if(typeof pineDrawSeries==='function'){allPineScripts().forEach(ps=>{if(!ps.overlay||!p.ind[ps.id]||!indVisOk(ps.id,p.tf))return;if(!p.S[ps.id])p.S[ps.id]=pineRun(ps,D2);pineDrawSeries(ctx,ps,p.S[ps.id],D2,a,z,xi2,py2,p.bw,X02,X12,0,PH2,AXL2,true)})}

  // Sub-panes
