let drg = null; // active drawing anchor/body drag state
let DT_POS = null; // remembered manual drag position for #dtbar
let DT_TPLS = [];
let DR_DEFS = {}; // per-tool default styles ("Save as default")
try { DT_TPLS = JSON.parse(localStorage['dx:drtpls'] || '[]'); if (!Array.isArray(DT_TPLS)) DT_TPLS = []; } catch (e) { DT_TPLS = []; }
try { DR_DEFS = JSON.parse(localStorage['dx:drdefs'] || '{}') || {}; } catch (e) { DR_DEFS = {}; }
function svDtTpls() { try { localStorage['dx:drtpls'] = JSON.stringify(DT_TPLS); } catch (e) {} }
function svDrDefs() { try { localStorage['dx:drdefs'] = JSON.stringify(DR_DEFS); } catch (e) {} }

const isLineTool     = k => !!(TD[k] && TD[k].g === 'ln');
const isPlainLine    = k => ['t','y','il','el','ta','h','hr','v','xl'].includes(k);
const isChanTool     = k => ['pc','rt','ft','dc'].includes(k);
const isPitchTool    = k => ['pf','sp','mp','ip'].includes(k);
const isFbGroupTool  = k => !!(TD[k] && TD[k].g === 'fb');
const isFibTool      = k => ['f','fx','fc','fz','ff','fi','fo','fs','fa','fw'].includes(k);
const isPitchfanTool = k => k === 'pn';
const isGannTool     = k => ['gb','gf','gs','gn'].includes(k);
const isGannBoxTool  = k => ['gb','gf','gs'].includes(k);
const isPatGroupTool = k => !!(TD[k] && TD[k].g === 'pt');
const isChartPatTool = k => ['p_xabcd','p_cypher','p_hs','p_abcd','p_tri','p_3d'].includes(k);
const isElliottTool  = k => ['p_eimp','p_ecor','p_etri','p_edbl','p_etrp'].includes(k);
const isCycleTool      = k => ['p_cyc','p_tcy','p_sin'].includes(k);
const isShapeGroupTool = k => !!(TD[k] && TD[k].g === 'sh');
const isBrushTool      = k => k === 'b_br' || k === 'b_hl';
const isArrowMarkTool  = k => k === 'a_up' || k === 'a_dn';
const isShapeTextTool  = k => ['r','s_ci','s_el','a_ar','a_mk','a_up','a_dn'].includes(k);
const isShapeFillTool  = k => ['r','rr','s_ci','s_el','s_pl','s_tr','s_arc','s_cv','s_dc','b_br'].includes(k);
const isFpGroupTool    = k => !!(TD[k] && TD[k].g === 'fp');
const isPosTool        = k => k === 'q_lp' || k === 'q_sp';
const isVpTool         = k => k === 'q_fv' || k === 'q_ap';
const isMeasTool       = k => k === 'q_pr' || k === 'q_dr' || k === 'q_dp';
const isFpInputsTool   = k => ['q_lp','q_sp','q_gf','q_av','q_fv','q_ap'].includes(k);
const isTxGroupTool    = k => !!(TD[k] && TD[k].g === 'tx');
const isTxEditableTool = k => ['x','tn','tpn','tpin','ttb','tco','tcm','tsg','tpo','tid'].includes(k);
const isCfgTool        = k => isLineTool(k) || isFbGroupTool(k) || isPatGroupTool(k) || isShapeGroupTool(k) || isFpGroupTool(k) || isTxGroupTool(k);

function txDef(k) {
  const base = {
    tc: '#ffffff', sz: 14, b: 0, i: 0, ha: 'left',
    bg: 1, bgc: '#2962ff', bgo: 0.90,
    bor: 1, borc: '#2962ff', bw: 1, ls: 'solid',
    wrap: 1, wrapW: 220, mc: '#2962ff',
    showP: 1, scale: 1, op: 1,
    emOn: 0, em: '📌',
    hbgc: '#2962ff', hbgo: 0.30, htc: '#ffffff', hb: 1,
    author: '@DreamX'
  };
  if (k === 'x')    return Object.assign(base, { tc: '#2962ff', sz: 14, bg: 0, bgc: '#1e222d', bgo: 0.85, bor: 0, borc: '#2962ff', bw: 1, wrap: 0, wrapW: 220, ha: 'left' });
  if (k === 'tn')   return Object.assign(base, { tc: '#ffffff', sz: 14, bg: 1, bgc: '#2962ff', bgo: 0.92, bor: 1, borc: '#2962ff', bw: 1, mc: '#2962ff', wrap: 1, wrapW: 220 });
  if (k === 'tpn')  return Object.assign(base, { tc: '#ffffff', sz: 14, bg: 1, bgc: '#2962ff', bgo: 0.90, bor: 1, borc: '#2962ff', bw: 1, ls: 'solid', mc: '#2962ff', showP: 1, wrap: 1, wrapW: 200 });
  if (k === 'tpin') return Object.assign(base, { tc: '#ffffff', sz: 12, bg: 1, bgc: '#131722', bgo: 0.92, bor: 1, borc: '#2962ff', bw: 1, mc: '#2962ff', scale: 1, wrap: 1, wrapW: 180 });
  if (k === 'ttb')  return Object.assign(base, { tc: '#d1d4dc', sz: 13, bg: 1, bgc: '#131722', bgo: 0.94, bor: 1, borc: '#2962ff', bw: 1, hbgc: '#2962ff', hbgo: 0.30, htc: '#ffffff', hb: 1 });
  if (k === 'tco')  return Object.assign(base, { tc: '#ffffff', sz: 14, bg: 1, bgc: '#2962ff', bgo: 0.88, bor: 1, borc: '#2962ff', bw: 1, wrap: 1, wrapW: 200 });
  if (k === 'tcm')  return Object.assign(base, { tc: '#ffffff', sz: 14, bg: 1, bgc: '#2962ff', bgo: 0.90, bor: 1, borc: '#2962ff', bw: 1, wrap: 1, wrapW: 200 });
  if (k === 'tpl')  return Object.assign(base, { tc: '#ffffff', sz: 12, b: 1, bg: 1, bgc: '#2962ff', bgo: 1.00, bor: 1, borc: '#2962ff', bw: 1 });
  if (k === 'tsg')  return Object.assign(base, { tc: '#ffffff', sz: 13, bg: 1, bgc: '#2962ff', bgo: 0.95, bor: 1, borc: '#2962ff', bw: 2, mc: '#2962ff', emOn: 0, em: '📌', wrap: 1, wrapW: 180 });
  if (k === 'tfl')  return Object.assign(base, { mc: '#089981', borc: '#787b86', bw: 2, scale: 1 });
  if (k === 'ti')   return Object.assign(base, { op: 1.0, scale: 1.0, bor: 0, borc: '#2962ff', bw: 1 });
  if (k === 'tpo')  return Object.assign(base, { tc: '#e7e9ea', sz: 13, bg: 1, bgc: '#0f1419', bgo: 0.96, bor: 1, borc: '#2962ff', bw: 1, wrap: 1, wrapW: 240, author: '@DreamX' });
  if (k === 'tid')  return Object.assign(base, { tc: '#d1d4dc', sz: 13, bg: 1, bgc: '#131722', bgo: 0.92, bor: 1, borc: '#2962ff', bw: 1, mc: '#f5c542', scale: 1, wrap: 1, wrapW: 200 });
  return base;
}

function drTplGroup(k) {
  if (isTxGroupTool(k)) return 'tx_' + k;
  if (isPosTool(k)) return 'fp_pos';
  if (k === 'q_pf') return 'fp_pf';
  if (k === 'q_bp') return 'fp_bp';
  if (k === 'q_gf') return 'fp_gf';
  if (k === 'q_sc') return 'fp_sc';
  if (k === 'q_av') return 'fp_av';
  if (isVpTool(k))  return 'fp_vp';
  if (isMeasTool(k)) return 'fp_ms';
  if (k === 'b_br') return 'sh_br';
  if (k === 'b_hl') return 'sh_hl';
  if (k === 'a_mk') return 'sh_mk';
  if (k === 'a_ar') return 'sh_ar';
  if (k === 'a_up' || k === 'a_dn') return 'sh_ud';
  if (k === 'r') return 'sh_r';
  if (k === 'b_pa') return 'sh_pa';
  if (k === 's_cv' || k === 's_dc') return 'sh_cv';
  if (isShapeGroupTool(k)) return 'sh_geo';
  if (isChartPatTool(k)) return 'cp';
  if (isElliottTool(k)) return 'ew';
  if (isCycleTool(k)) return 'cy';
  if (k === 'fs') return 'fs';
  if (isFibTool(k)) return 'fib';
  if (isPitchfanTool(k)) return 'pn';
  if (k === 'gn') return 'gn';
  if (isGannBoxTool(k)) return 'gb';
  if (isPitchTool(k)) return 'pf';
  if (k === 'rt') return 'rt';
  if (isChanTool(k)) return 'ch';
  return 'ln';
}

