// =========================================================================
const EW_DEGREES = [
  { id:'grand_supercycle', n:'Grand Supercycle', wrap:'double', imp:['I','II','III','IV','V'],     cor:['A','B','C','D','E'], cmb:['W','X','Y','X','Z'] },
  { id:'supercycle',       n:'Supercycle',       wrap:'paren',  imp:['I','II','III','IV','V'],     cor:['A','B','C','D','E'], cmb:['W','X','Y','X','Z'] },
  { id:'cycle',            n:'Cycle',            wrap:'none',   imp:['I','II','III','IV','V'],     cor:['A','B','C','D','E'], cmb:['W','X','Y','X','Z'] },
  { id:'primary',          n:'Primary',          wrap:'circle', imp:['1','2','3','4','5'],         cor:['A','B','C','D','E'], cmb:['W','X','Y','X','Z'] },
  { id:'intermediate',     n:'Intermediate',     wrap:'paren',  imp:['1','2','3','4','5'],         cor:['A','B','C','D','E'], cmb:['W','X','Y','X','Z'] },
  { id:'minor',            n:'Minor',            wrap:'none',   imp:['1','2','3','4','5'],         cor:['A','B','C','D','E'], cmb:['W','X','Y','X','Z'] },
  { id:'minute',           n:'Minute',           wrap:'circle', imp:['1','2','3','4','5'],         cor:['a','b','c','d','e'], cmb:['w','x','y','x','z'] },
  { id:'minuette',         n:'Minuette',         wrap:'paren',  imp:['i','ii','iii','iv','v'],     cor:['a','b','c','d','e'], cmb:['w','x','y','x','z'] },
  { id:'subminuette',      n:'Subminuette',      wrap:'none',   imp:['i','ii','iii','iv','v'],     cor:['a','b','c','d','e'], cmb:['w','x','y','x','z'] },
  { id:'micro',            n:'Micro',            wrap:'circle', imp:['1','2','3','4','5'],         cor:['a','b','c','d','e'], cmb:['w','x','y','x','z'] },
  { id:'submicro',         n:'Submicro',         wrap:'paren',  imp:['1','2','3','4','5'],         cor:['a','b','c','d','e'], cmb:['w','x','y','x','z'] },
  { id:'minuscule',        n:'Minuscule',        wrap:'none',   imp:['1','2','3','4','5'],         cor:['a','b','c','d','e'], cmb:['w','x','y','x','z'] }
];

function ewDegObj(id) {
  return EW_DEGREES.find(g => g.id === id) || EW_DEGREES[7]; // Minuette default
}

function ewFmtGlyph(sym0, wrap) {
  if (!sym0) return '';
  if (wrap === 'double') return '((' + sym0 + '))';
  if (wrap === 'paren')  return '(' + sym0 + ')';
  return sym0;
}

function ewLabelsFor(k, degId) {
  const g = ewDegObj(degId);
  let seq = [];
  if (k === 'p_eimp') seq = g.imp.slice(0, 5);
  else if (k === 'p_ecor') seq = g.cor.slice(0, 3);
  else if (k === 'p_etri') seq = g.cor.slice(0, 5);
  else if (k === 'p_edbl') seq = g.cmb.slice(0, 3);
  else if (k === 'p_etrp') seq = g.cmb.slice(0, 5);
  return {
    wrap: g.wrap,
    items: ['0', ...seq].map((s, idx) => ({ raw: s, txt: ewFmtGlyph(s, g.wrap), circle: g.wrap === 'circle' && idx > 0 }))
  };
}

function ewDegPreview(k, g) {
  let seq = [];
  if (k === 'p_eimp') seq = g.imp.slice(0, 5);
  else if (k === 'p_ecor') seq = g.cor.slice(0, 3);
  else if (k === 'p_etri') seq = g.cor.slice(0, 5);
  else if (k === 'p_edbl') seq = g.cmb.slice(0, 3);
  else seq = g.cmb.slice(0, 5);
  const circMap = { '1':'①','2':'②','3':'③','4':'④','5':'⑤','A':'Ⓐ','B':'Ⓑ','C':'Ⓒ','D':'Ⓓ','E':'Ⓔ','W':'Ⓦ','X':'Ⓧ','Y':'Ⓨ','Z':'Ⓩ','a':'ⓐ','b':'ⓑ','c':'ⓒ','d':'ⓓ','e':'ⓔ','w':'ⓦ','x':'ⓧ','y':'ⓨ','z':'ⓩ' };
  return seq.map(s => g.wrap === 'circle' ? (circMap[s] || s) : ewFmtGlyph(s, g.wrap)).join(' ');
}

function cpDef(k) {
  const bc = (k === 'p_cypher' || k === 'p_tri' || k === 'p_3d') ? '#9c27b0' : (k === 'p_hs' ? '#26a69a' : '#2962ff');
  const hasBg = k !== 'p_abcd';
  return {
    lc: '#ffffff',
    lsz: 12,
    lb: 0,
    li: 0,
    bc,
    bw: 2,
    bs: 'solid',
    bg: hasBg ? 1 : 0,
    bgc: bc,
    bgo: 0.20
  };
}

function ewDef(k) {
  const isTri = k === 'p_etri';
  const isDash = isTri || k === 'p_edbl' || k === 'p_etrp';
  return {
    deg: 'minuette',
    c: isTri ? '#9c27b0' : '#2962ff',
    lw: 1,
    ls: isDash ? 'dashed' : 'solid',
    show: 1
  };
}

function cyDef(k) {
  return {
    c: '#26a69a',
    lw: k === 'p_sin' ? 2 : 1,
    ls: 'solid',
    bg: k === 'p_tcy' ? 1 : 0,
    bgc: '#26a69a',
    bgo: 0.20
  };
}

