  $('#cp_lsz').onchange = e => { cp.lsz = +e.target.value; draw(); };
  $('#cp_lb').onclick = () => { cp.lb = cp.lb ? 0 : 1; dsmRender(); draw(); };
  $('#cp_li').onclick = () => { cp.li = cp.li ? 0 : 1; dsmRender(); draw(); };
  $('#cp_bc').oninput = e => { cp.bc = e.target.value; d.c = cp.bc; e.target.parentNode.style.background = cp.bc; dtUpd(); draw(); };
  $('#cp_bw').onchange = e => { cp.bw = +e.target.value; dtUpd(); draw(); };
  $('#cp_bs').onchange = e => { cp.bs = e.target.value; dtUpd(); draw(); };
