// v26: FULLSCREEN, PROFILE MENU, DARK/LIGHT THEME, DRAWINGS PANEL TOGGLE,
// ALL WORLD LANGUAGES (120+) FULL-SYSTEM TRANSLATOR & CUSTOMIZABLE SHORTCUTS
// =========================================================================

// --- 1. FULLSCREEN MODE ---
const FS_IC_ENTER = '<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/></svg>';
const FS_IC_EXIT  = '<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M9 4v5H4M15 4v5h5M9 20v-5H4M15 20v-5h5"/></svg>';

function fsIsOn() {
  return !!(document.fullscreenElement || document.webkitFullscreenElement || document.mozFullScreenElement || document.msFullscreenElement);
}
function fsUpdUI() {
  const b = $('#fsbtn'); if (!b) return;
  const on = fsIsOn();
  b.innerHTML = on ? FS_IC_EXIT : FS_IC_ENTER;
  b.classList.toggle('on', on);
  b.title = on ? 'Exit fullscreen (Esc)' : 'Fullscreen mode (Shift + F)';
  try { applyTbWidth(TB_W, false); draw(); } catch (e) {}
  setTimeout(() => { try { applyTbWidth(TB_W, false); draw(); } catch (e) {} }, 60);
  setTimeout(() => { try { draw(); } catch (e) {} }, 200);
}
if (typeof ResizeObserver !== 'undefined' && $('#wrap')) {
  new ResizeObserver(() => { try { draw(); } catch (e) {} }).observe($('#wrap'));
}
function fsToggle() {
  try {
    if (fsIsOn()) {
      const ex = document.exitFullscreen || document.webkitExitFullscreen || document.mozCancelFullScreen || document.msExitFullscreen;
      if (ex) ex.call(document);
    } else {
      const el = document.documentElement;
      const rq = el.requestFullscreen || el.webkitRequestFullscreen || el.mozRequestFullScreen || el.msRequestFullscreen;
      if (rq) rq.call(el).catch(() => {});
    }
  } catch (e) { toast('Fullscreen not supported in this window'); }
}
$('#fsbtn').onclick = fsToggle;
['fullscreenchange','webkitfullscreenchange','mozfullscreenchange','MSFullscreenChange'].forEach(ev => {
  document.addEventListener(ev, fsUpdUI);
});

// --- 2. DARK / LIGHT THEME ENGINE ---
let DARK_ON = true;
try { const st = localStorage['dx:theme']; if (st === 'light') DARK_ON = false; } catch (e) {}

const THEME_PRESETS = {
  dark:  { bgc:'#0b0e14', bg2:'#1e2a44', gv:'#1c212c', gh:'#1c212c', ch:'#5d6475', wm:'#ffffff', wmo:0.12, sct:'#8b93a3', scl:'#2a2e39' },
  light: { bgc:'#ffffff', bg2:'#eef2fa', gv:'#e8ecf4', gh:'#e8ecf4', ch:'#787b86', wm:'#131722', wmo:0.08, sct:'#4e5665', scl:'#d6dae3' }
};

function applyThemeToCfg(cfgObj, isDark) {
  if (!cfgObj) return;
  const p = isDark ? THEME_PRESETS.dark : THEME_PRESETS.light;
  cfgObj.bgc.c1 = p.bgc;
  cfgObj.bgc.c2 = p.bg2;
  cfgObj.gv.c   = p.gv;
  cfgObj.gh.c   = p.gh;
  cfgObj.ch.c   = p.ch;
  cfgObj.wm.c   = p.wm;
  cfgObj.wm.o   = p.wmo;
  cfgObj.sc.tc  = p.sct;
  cfgObj.sc.lc  = p.scl;
}

function setDarkTheme(on, skipSave) {
  DARK_ON = !!on;
  document.body.classList.toggle('light-theme', !DARK_ON);
  applyThemeToCfg(CFG, DARK_ON);
  if (typeof LYT !== 'undefined' && Array.isArray(LYT.panes)) {
    LYT.panes.forEach(p => { if (p && p.CFG) applyThemeToCfg(p.CFG, DARK_ON); });
  }
  if (!skipSave) {
    try { localStorage['dx:theme'] = DARK_ON ? 'dark' : 'light'; } catch (e) {}
    svC();
  }
  if ($('#profm').style.display === 'block') profRender();
  if (typeof hmSyncTheme === 'function') hmSyncTheme();
  draw();
}

// --- 3. DRAWINGS PANEL TOGGLE ---
let DPANEL_ON = true;
try { const dp = localStorage['dx:dpanel']; if (dp === '0') DPANEL_ON = false; } catch (e) {}

function setDrawPanel(on, skipSave) {
  DPANEL_ON = !!on;
  const tl = $('#tools');
  if (tl) tl.classList.toggle('dp-off', !DPANEL_ON);
  if (!DPANEL_ON) flyClose();
  if (!skipSave) {
    try { localStorage['dx:dpanel'] = DPANEL_ON ? '1' : '0'; } catch (e) {}
  }
  if ($('#profm').style.display === 'block') profRender();
  setTimeout(() => { try { draw(); } catch (e) {} }, 20);
}

