let CUR_LANG = 'en';
try { CUR_LANG = localStorage['dx:lang'] || 'en'; } catch (e) {}
const I18N_CACHE = {}; // lang -> { orig: translated }
const I18N_ORIG_TXT = new WeakMap();
const I18N_ORIG_ATTR = new WeakMap();
let I18N_MUT_LOCK = false, I18N_TMR = null, I18N_INFLIGHT = new Set();

function i18nLangMeta(code) {
  return WORLD_LANGS.find(l => l[0] === code) || WORLD_LANGS[0];
}
function i18nDict(code) {
  if (!I18N_CACHE[code]) {
    let saved = {};
    try { saved = JSON.parse(localStorage['dx:i18n:' + code] || '{}') || {}; } catch (e) {}
    I18N_CACHE[code] = Object.assign({}, BUILTIN_I18N[code] || {}, saved);
  }
  return I18N_CACHE[code];
}
function i18nSaveDict(code) {
  try { localStorage['dx:i18n:' + code] = JSON.stringify(I18N_CACHE[code] || {}); } catch (e) {}
}

function i18nShouldSkipText(raw) {
  const t = String(raw || '').trim();
  if (!t || t.length < 2 || t.length > 260) return true;
  if (!/[A-Za-z]/.test(t)) return true;
  if (/^[\d.,%+\-−:/$€£¥₹\s()·•●○★☆✓✕▾▸‹›«»⏱🔔📷⚙✂▶⏸|]+$/.test(t)) return true;
  if (/^[A-Z0-9]{2,14}([/:.\-][A-Z0-9]{2,10})?(\.P)?$/.test(t)) return true; // Tickers like BTCUSDT, EUR/USD, BYBIT:BTCUSDT.P
  if (/^\d+\s*[tsmhdwMRYT]$/i.test(t) || /^[1-9]\d*[MYWD]$/i.test(t)) return true; // Timeframe chips like 1m, 3Y, 5Y
  if (/^(Alt|Ctrl|Shift|Cmd|Meta)(\s*\+\s*[A-Za-z0-9/]+)+$/.test(t)) return true; // Shortcut keys
  if (/^(O|H|L|C|Vol|POC|VAH|VAL|VWAP|RSI|MACD|ATR|CVD|EMA|SMA)\b/.test(t) && t.length <= 16) return true;
  if (/^DreamX\b/.test(t)) return true;
  if (/^nuwanidu/i.test(t)) return true;
  return false;
}

function i18nSplitDecor(str) {
  const m = /^([\s◆●○★☆⚙📷🔔✂▶⏸↺＋✓✕\u2600-\u27BF\uD83C-\uDBFF\uDC00-\uDFFF]*)(.*?)([\s▾▸‹›…:]*)$/.exec(str);
  if (!m) return ['', str, ''];
  return [m[1], m[2], m[3]];
}

function i18nWalkApply(root, code, missingSet) {
  if (!root) return;
  const dict = code === 'en' ? null : i18nDict(code);
  const skipTags = new Set(['SCRIPT','STYLE','SVG','CODE','PRE','CANVAS']);
  const skipIds = new Set(['sb2','pill','clk','histst','sl','tfs','langls','profav']);
  const walk = el => {
    if (!el) return;
    if (el.nodeType === 1) {
      if (skipTags.has(el.tagName) || skipIds.has(el.id) || el.dataset.noI18n === '1') return;
      if (el.classList && (el.classList.contains('ks-key') || el.classList.contains('pm-uname') || el.classList.contains('lg-nat') || el.classList.contains('lg-en'))) return;
      ['placeholder','title'].forEach(at => {
        if (!el.hasAttribute(at)) return;
        let orig = I18N_ORIG_ATTR.get(el);
        if (!orig) { orig = {}; I18N_ORIG_ATTR.set(el, orig); }
        if (orig[at] === undefined) orig[at] = el.getAttribute(at);
        const oVal = orig[at];
        if (code === 'en') {
          if (el.getAttribute(at) !== oVal) el.setAttribute(at, oVal);
          return;
        }
        const [pre, core, suf] = i18nSplitDecor(oVal);
        if (i18nShouldSkipText(core)) return;
        if (dict[core]) {
          const nv = pre + dict[core] + suf;
          if (el.getAttribute(at) !== nv) el.setAttribute(at, nv);
        } else if (missingSet) missingSet.add(core);
      });
      for (let ch = el.firstChild; ch; ch = ch.nextSibling) walk(ch);
    } else if (el.nodeType === 3) {
      let oVal = I18N_ORIG_TXT.get(el);
      if (oVal === undefined) {
        oVal = el.nodeValue;
        if (i18nShouldSkipText(i18nSplitDecor(oVal)[1])) return;
        I18N_ORIG_TXT.set(el, oVal);
      }
      if (code === 'en') {
        if (el.nodeValue !== oVal) el.nodeValue = oVal;
        return;
      }
      const [pre, core, suf] = i18nSplitDecor(oVal);
      if (i18nShouldSkipText(core)) return;
      if (dict[core]) {
        const nv = pre + dict[core] + suf;
        if (el.nodeValue !== nv) el.nodeValue = nv;
      } else if (missingSet) missingSet.add(core);
    }
  };
  I18N_MUT_LOCK = true;
  try { walk(root); } finally { I18N_MUT_LOCK = false; }
}

async function i18nFetchBatch(lang, list) {
  if (!list.length || lang === 'en') return false;
  const dict = i18nDict(lang);
  const sep = '\n@@DXSEP@@\n';
  const joined = list.join(sep);
  let translatedList = null;

  // Primary: Google Translate public endpoint (supports all 120+ world languages, CORS-enabled)
  try {
    const url = 'https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl=' + encodeURIComponent(lang) + '&dt=t&q=' + encodeURIComponent(joined);
    const j = await fetchWithTimeout(url, 7000);
    if (Array.isArray(j) && Array.isArray(j[0])) {
      const full = j[0].map(p => (p && p[0]) || '').join('');
      const parts0 = full.split(/\s*@@\s*DXSEP\s*@@\s*/i);
      if (parts0.length === list.length) translatedList = parts0.map(s => s.trim());
    }
  } catch (e) {}

  // Fallback: translate items individually if batch delimiter shifted or MyMemory fallback
  if (!translatedList) {
    translatedList = await Promise.all(list.map(async txt => {
      try {
        const u1 = 'https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl=' + encodeURIComponent(lang) + '&dt=t&q=' + encodeURIComponent(txt);
        const j1 = await fetchWithTimeout(u1, 4500);
        if (Array.isArray(j1) && Array.isArray(j1[0])) return j1[0].map(p => (p && p[0]) || '').join('').trim();
      } catch (e) {}
      try {
        const u2 = 'https://api.mymemory.translated.net/get?q=' + encodeURIComponent(txt) + '&langpair=en|' + encodeURIComponent(lang.split('-')[0]);
        const j2 = await fetchWithTimeout(u2, 4500);
        if (j2 && j2.responseData && j2.responseData.translatedText) return String(j2.responseData.translatedText).trim();
      } catch (e) {}
      return null;
    }));
  }

  let any = false;
  list.forEach((orig, idx) => {
    const tr0 = translatedList && translatedList[idx];
    if (tr0 && tr0.length) { dict[orig] = tr0; any = true; }
  });
  if (any) i18nSaveDict(lang);
  return any;
}

async function i18nTranslateMissing(lang, missingSet) {
  if (lang === 'en' || !missingSet || !missingSet.size) return;
  const todo = [...missingSet].filter(t => !I18N_INFLIGHT.has(lang + ':' + t));
  if (!todo.length) return;
  todo.forEach(t => I18N_INFLIGHT.add(lang + ':' + t));
  const stat = $('#langstat');
  if (stat && $('#langm').style.display === 'flex') stat.textContent = 'Translating interface…';
  try {
    // Chunk into ~28 items / <=1500 chars per request
    let i = 0;
    while (i < todo.length) {
      const chunk = [];
      let chars = 0;
      while (i < todo.length && chunk.length < 28 && chars + todo[i].length < 1400) {
        chunk.push(todo[i]); chars += todo[i].length + 12; i++;
      }
      if (!chunk.length) { chunk.push(todo[i++]); }
      await i18nFetchBatch(lang, chunk);
      if (CUR_LANG !== lang) break;
      i18nWalkApply(document.body, lang, null);
    }
  } finally {
    todo.forEach(t => I18N_INFLIGHT.delete(lang + ':' + t));
    if (stat && $('#langm').style.display === 'flex') {
      const lm = i18nLangMeta(CUR_LANG);
      stat.textContent = `Active: ${lm[2]} (${lm[1]}) · ${WORLD_LANGS.length} languages available`;
    }
  }
}

function i18nApplyNow(root) {
  const missing = new Set();
  i18nWalkApply(root || document.body, CUR_LANG, missing);
  if (CUR_LANG !== 'en' && missing.size) i18nTranslateMissing(CUR_LANG, missing);
}

function setLanguage(code, silent) {
  const lm = i18nLangMeta(code);
  CUR_LANG = lm[0];
  try { localStorage['dx:lang'] = CUR_LANG; } catch (e) {}
  document.documentElement.lang = CUR_LANG;
  document.documentElement.dir = lm[3] ? 'rtl' : 'ltr';
  // Keep chart workspace & price/time axes LTR so candles and scales always read left-to-right
  const mainEl = $('#main'); if (mainEl) mainEl.dir = 'ltr';
  const footEl = $('#foot'); if (footEl) footEl.dir = 'ltr';
  i18nApplyNow(document.body);
  if ($('#profm').style.display === 'block') profRender();
  if ($('#langm').style.display === 'flex') langRender();
  if (!silent) toast(`Language: ${lm[2]} (${lm[1]})`);
}

// Auto-translate dynamically opened menus, settings tabs, flyouts & modals
const I18N_OBS = new MutationObserver(() => {
  if (I18N_MUT_LOCK || CUR_LANG === 'en') return;
  clearTimeout(I18N_TMR);
  I18N_TMR = setTimeout(() => i18nApplyNow(document.body), 45);
});
I18N_OBS.observe(document.body, { childList: true, subtree: true });

function langRender() {
  const q = ($('#langq').value || '').trim().toLowerCase();
  const list = WORLD_LANGS.filter(l => !q || l[0].toLowerCase().includes(q) || l[1].toLowerCase().includes(q) || l[2].toLowerCase().includes(q));
  $('#langls').innerHTML = list.map(l => `
    <div class="lg-it ${l[0] === CUR_LANG ? 'sel' : ''}" data-lg="${esc(l[0])}">
      <div><span class="lg-nat">${esc(l[2])}</span><span class="lg-en">${esc(l[1])} · ${esc(l[0].toUpperCase())}</span></div>
      ${l[0] === CUR_LANG ? '<span style="color:#26a69a;font-weight:700">✓</span>' : ''}
    </div>
  `).join('') || '<div style="padding:18px;color:#8b93a3">No matching language found</div>';
  const lm = i18nLangMeta(CUR_LANG);
  $('#langstat').textContent = `Active: ${lm[2]} (${lm[1]}) · ${WORLD_LANGS.length} languages available`;
  $('#langls').querySelectorAll('[data-lg]').forEach(el => {
    el.onclick = () => { setLanguage(el.dataset.lg); };
  });
}
function langOpen() {
  cm();
  $('#langm').style.display = 'flex';
  $('#langq').value = '';
  langRender();
  $('#langq').focus();
}
$('#langq').oninput = langRender;
$('#langx').onclick = cm;
$('#langm').onclick = e => { if (e.target.id === 'langm') cm(); };
$('#langreset').onclick = () => setLanguage('en');

