const KS_CMD_LIST = [
  ['replay',   'Toggle Bar Replay',        () => $('#rpb').click()],
  ['compare',  'Open Compare Symbols',     () => $('#cmpb').click()],
  ['objtree',  'Toggle Object Tree',       () => { if (typeof objToggle === 'function') objToggle(); }],
  ['tblview',  'Open Table View',          () => { if (typeof tblOpen === 'function') tblOpen(); }],
  ['closepos', 'Close Open Position',      () => closePos()],
  ['revpos',   'Reverse Open Position',    () => revPos()],
  ['cleardr',  'Delete All Drawings',      () => $('#cl').click()],
  ['favbar',   'Toggle Favorites Toolbar', () => { CFG.fvs = CFG.fvs ? 0 : 1; svC(); rfv(); tbUp(); }],
  ['zoomin',   'Zoom In Chart',            () => { if (D.length) { zoomTo(bw * 1.25); draw(); } }],
  ['zoomout',  'Zoom Out Chart',           () => { if (D.length) { zoomTo(bw / 1.25); maybeBackfill(); draw(); } }],
  ['latest',   'Scroll to Latest Bar',     () => { off = 5; draw(); }]
];

let KS_MAP = {};    // id -> combo string (e.g. 'Alt+KeyT' or '')
let KS_CUSTOM = []; // [{ id, cat:'Custom', n, kind, val }]

function ksRunCustom(item) {
  if (!item) return;
  const k = item.kind, v = item.val;
  if (k === 'tool' && TD[v]) { act(v); return; }
  if (k === 'tf') { setTf(v); return; }
  if (k === 'ct' && typeof ctSet === 'function') { ctSet(v); return; }
  if (k === 'ind') {
    if (typeof LYT !== 'undefined' && LYT.id !== '1_1') { lytToggleInd(v); return; }
    ind[v] = ind[v] ? 0 : 1; sI(); draw();
    const meta = IND.find(x => x[0] === v);
    toast((meta ? meta[1] : v) + (ind[v] ? ' added' : ' removed'));
    return;
  }
  if (k === 'sym' && v) {
    const up = String(v).trim().toUpperCase();
    if (up) selectSym(up);
    return;
  }
  if (k === 'rng') { applyRange(v); return; }
  if (k === 'cmd') {
    const c = KS_CMD_LIST.find(x => x[0] === v);
    if (c) c[2]();
  }
}

function ksAllItems() { return KS_DEFS.concat(KS_CUSTOM); }

function ksLoad() {
  let saved = {};
  try { saved = JSON.parse(localStorage['dx:keys'] || '{}') || {}; } catch (e) {}
  try {
    const c = JSON.parse(localStorage['dx:keys_custom'] || '[]');
    KS_CUSTOM = Array.isArray(c) ? c.filter(x => x && x.id && x.kind && x.val) : [];
  } catch (e) { KS_CUSTOM = []; }
  KS_MAP = {};
  KS_DEFS.forEach(d => { KS_MAP[d.id] = (d.id in saved) ? saved[d.id] : d.def; });
  KS_CUSTOM.forEach(c => { KS_MAP[c.id] = (c.id in saved) ? saved[c.id] : (c.combo || ''); });
}
function ksSave() {
  try {
    localStorage['dx:keys'] = JSON.stringify(KS_MAP);
    localStorage['dx:keys_custom'] = JSON.stringify(KS_CUSTOM);
  } catch (e) {}
}
ksLoad();

function ksCodeLabel(code) {
  if (!code) return '';
  if (code.startsWith('Key')) return code.slice(3);
  if (code.startsWith('Digit')) return code.slice(5);
  const map = { Slash:'/', Backslash:'\\', Comma:',', Period:'.', Semicolon:';', Quote:"'", BracketLeft:'[', BracketRight:']', Minus:'-', Equal:'=', Backquote:'`', Space:'Space', ArrowUp:'↑', ArrowDown:'↓', ArrowLeft:'←', ArrowRight:'→' };
  return map[code] || code;
}
function ksFmtCombo(combo) {
  if (!combo) return 'None';
  return combo.split('+').map(p => (p === 'Ctrl' || p === 'Alt' || p === 'Shift') ? p : ksCodeLabel(p)).join(' + ');
}
function ksEventCombo(e) {
  const modOnly = ['ControlLeft','ControlRight','AltLeft','AltRight','ShiftLeft','ShiftRight','MetaLeft','MetaRight'];
  if (modOnly.includes(e.code)) return null;
  const parts0 = [];
  if (e.ctrlKey || e.metaKey) parts0.push('Ctrl');
  if (e.altKey) parts0.push('Alt');
  if (e.shiftKey) parts0.push('Shift');
  parts0.push(e.code);
  return parts0.join('+');
}
function ksHintById(id) {
  const combo = KS_MAP[id];
  return combo ? ksFmtCombo(combo) : '';
}
function ksToolHint(toolId) {
  const def = KS_DEFS.find(x => x.tool === toolId);
  if (def && KS_MAP[def.id]) return ksFmtCombo(KS_MAP[def.id]);
  const cus = KS_CUSTOM.find(x => x.kind === 'tool' && x.val === toolId && KS_MAP[x.id]);
  if (cus) return ksFmtCombo(KS_MAP[cus.id]);
  return '';
}

let KS_REC_ID = null, KS_CAT = 'All', KS_NEW_COMBO = '';
function ksStopRec() { KS_REC_ID = null; }

function ksCaptureEvent(e) {
  if (!KS_REC_ID || $('#ksm').style.display !== 'flex') return false;
  e.preventDefault();
  e.stopPropagation();
  e.stopImmediatePropagation();
  if (e.key === 'Escape') {
    KS_REC_ID = null;
    ksUpdNewRecBtn();
    ksRender();
    return true;
  }
  const combo = ksEventCombo(e);
  if (!combo) return true;
  if (KS_REC_ID === '__NEW__') {
    KS_NEW_COMBO = combo;
    KS_REC_ID = null;
    ksUpdNewRecBtn();
    return true;
  }
  const conflict = ksAllItems().find(x => x.id !== KS_REC_ID && KS_MAP[x.id] === combo);
  if (conflict) {
    KS_MAP[conflict.id] = '';
    toast(`Reassigned ${ksFmtCombo(combo)} (removed from ${conflict.n})`);
  } else {
    toast(`Shortcut set to ${ksFmtCombo(combo)}`);
  }
  KS_MAP[KS_REC_ID] = combo;
  KS_REC_ID = null;
  ksSave();
  urUpd();
  ksRender();
  if ($('#fly').style.display === 'block') flyRender();
  return true;
}

function ksHandleEvent(e) {
  const combo = ksEventCombo(e);
  if (!combo) return false;
  if (typeof HOME_OPEN !== 'undefined' && HOME_OPEN) {
    if (KS_MAP['sys_srch'] && KS_MAP['sys_srch'] === combo) { e.preventDefault(); $('#sb2').click(); return true; }
    if (KS_MAP['sys_ks'] && KS_MAP['sys_ks'] === combo) { e.preventDefault(); ksOpen(); return true; }
    return false;
  }
  for (const def of KS_DEFS) {
    if (KS_MAP[def.id] && KS_MAP[def.id] === combo) {
      e.preventDefault();
      if (def.tool) act(def.tool);
      else if (def.run) def.run();
      return true;
    }
  }
  for (const cus of KS_CUSTOM) {
    if (KS_MAP[cus.id] && KS_MAP[cus.id] === combo) {
      e.preventDefault();
      ksRunCustom(cus);
      return true;
    }
  }
  return false;
}

function ksUpdNewRecBtn() {
  const btn = $('#ksrec_new');
  if (!btn) return;
  const isRec = KS_REC_ID === '__NEW__';
  btn.classList.toggle('rec', isRec);
  btn.classList.toggle('empty', !isRec && !KS_NEW_COMBO);
  btn.textContent = isRec ? 'Press keys…' : (KS_NEW_COMBO ? ksFmtCombo(KS_NEW_COMBO) : 'Click & press keys');
}

function ksPopulateTarget() {
  const kind = $('#ksat').value, selEl = $('#ksv'), txtEl = $('#ksv_txt');
  let opts = [];
  if (kind === 'tool') {
    opts = Object.keys(TD).map(k => [k, (GT[TD[k].g] ? GT[TD[k].g] + ' · ' : '') + TD[k].n]);
    txtEl.style.display = 'none'; selEl.style.display = '';
  } else if (kind === 'tf') {
    const std = ['1s','5s','15s','30s','1m','2m','3m','5m','10m','15m','30m','45m','1h','2h','3h','4h','6h','8h','12h','1d','3d','1w','1M'];
    opts = std.map(x => [x, tfL(x) + ' (' + tfS(x) + ')']).concat([['__custom__', 'Custom interval…']]);
    selEl.style.display = ''; txtEl.style.display = 'none';
  } else if (kind === 'ct') {
    opts = CT_LIST.map(c => [c.id, c.n]);
    txtEl.style.display = 'none'; selEl.style.display = '';
  } else if (kind === 'ind') {
    opts = IND.map(x => [x[0], x[1]]);
    txtEl.style.display = 'none'; selEl.style.display = '';
  } else if (kind === 'sym') {
    const quick = [...new Set([...SYMFAV, 'BTCUSDT','ETHUSDT','SOLUSDT','EURUSD','GBPUSD','XAUUSD','SPX','NDX','AAPL','NVDA'])];
    opts = quick.map(s => [s, lab(s)]).concat([['__custom__', 'Type any symbol…']]);
    selEl.style.display = ''; txtEl.style.display = 'none';
  } else if (kind === 'rng') {
    opts = [['1M','Fit 1 Month'],['6M','Fit 6 Months'],['1Y','Fit 1 Year'],['3Y','Fit 3 Years'],['5Y','Fit 5 Years (Elliott Wave)'],['ALL','Fit All Loaded History']];
    txtEl.style.display = 'none'; selEl.style.display = '';
  } else if (kind === 'cmd') {
    opts = KS_CMD_LIST.map(c => [c[0], c[1]]);
    txtEl.style.display = 'none'; selEl.style.display = '';
  }
  selEl.innerHTML = opts.map(([v, l]) => `<option value="${esc(v)}">${esc(l)}</option>`).join('');
  ksSyncTargetInput();
}

function ksSyncTargetInput() {
  const kind = $('#ksat').value, selEl = $('#ksv'), txtEl = $('#ksv_txt'), lblEl = $('#kslbl');
  const isCustomVal = selEl.value === '__custom__';
  txtEl.style.display = isCustomVal ? '' : 'none';
  if (isCustomVal) {
    txtEl.placeholder = kind === 'tf' ? 'e.g. 20m, 10t, 50R' : 'e.g. BYBIT:SOLUSDT.P or XAUUSD';
    txtEl.focus();
  }
  const optText = selEl.options[selEl.selectedIndex] ? selEl.options[selEl.selectedIndex].text : '';
  const preMap = { tool:'', tf:'Timeframe: ', ct:'Chart: ', ind:'Toggle ', sym:'Symbol: ', rng:'', cmd:'' };
  if (!isCustomVal) lblEl.placeholder = (preMap[kind] || '') + optText.replace(/^[^·]+·\s*/, '');
  else lblEl.placeholder = kind === 'tf' ? 'e.g. Timeframe 20m' : 'e.g. Open Symbol';
}

function ksAddCustomSave() {
  const kind = $('#ksat').value;
  let val = $('#ksv').value;
  if (val === '__custom__') {
    val = ($('#ksv_txt').value || '').trim();
    if (!val) { toast('Enter a target value first'); $('#ksv_txt').focus(); return; }
    if (kind === 'tf' && !ti(val)) { toast('Invalid interval (use e.g. 5m, 45m, 2h, 1d, 100t)'); $('#ksv_txt').focus(); return; }
    if (kind === 'sym') val = val.toUpperCase();
  }
  if (!KS_NEW_COMBO) {
    toast('Click the key box and press your desired shortcut keys');
    KS_REC_ID = '__NEW__'; ksUpdNewRecBtn();
    return;
  }
  const optText = $('#ksv').options[$('#ksv').selectedIndex] ? $('#ksv').options[$('#ksv').selectedIndex].text : val;
  const defLbl = ($('#ksv').value === '__custom__')
    ? (kind === 'tf' ? 'Timeframe: ' + val : 'Symbol: ' + val)
    : (({ tool:'', tf:'Timeframe: ', ct:'Chart: ', ind:'Toggle ', sym:'Symbol: ', rng:'', cmd:'' }[kind] || '') + optText.replace(/^[^·]+·\s*/, ''));
  const name = ($('#kslbl').value || '').trim() || defLbl;
  const id = 'cus_' + Date.now() + '_' + Math.floor(Math.random() * 1000);

  const conflict = ksAllItems().find(x => KS_MAP[x.id] === KS_NEW_COMBO);
  if (conflict) {
    KS_MAP[conflict.id] = '';
    toast(`Added "${name}" (${ksFmtCombo(KS_NEW_COMBO)}) · cleared from ${conflict.n}`);
  } else {
    toast(`Added shortcut "${name}" → ${ksFmtCombo(KS_NEW_COMBO)}`);
  }
  KS_CUSTOM.unshift({ id, cat: 'Custom', n: name, kind, val, def: '' });
  KS_MAP[id] = KS_NEW_COMBO;
  KS_NEW_COMBO = '';
  KS_REC_ID = null;
  $('#kslbl').value = '';
  $('#ksv_txt').value = '';
  $('#ksform').classList.remove('open');
  ksSave();
  ksUpdNewRecBtn();
  ksRender();
  if ($('#fly').style.display === 'block') flyRender();
}

function ksRender() {
  const cats = ['All','Custom','Drawing Tools','Chart & View','Trading & Alerts','System'];
  $('#kscats').innerHTML = cats.map(c => `<button class="${KS_CAT === c ? 'on' : ''}" data-ksc="${esc(c)}">${esc(c)}${c === 'Custom' && KS_CUSTOM.length ? ' (' + KS_CUSTOM.length + ')' : ''}</button>`).join('');
  $('#kscats').querySelectorAll('[data-ksc]').forEach(b => b.onclick = () => { KS_CAT = b.dataset.ksc; ksRender(); });

  const q = ($('#ksq').value || '').trim().toLowerCase();
  const all = ksAllItems();
  const filtered = all.filter(d => (KS_CAT === 'All' || d.cat === KS_CAT) && (!q || d.n.toLowerCase().includes(q) || ksFmtCombo(KS_MAP[d.id]).toLowerCase().includes(q)));
  const byCat = {};
  filtered.forEach(d => { (byCat[d.cat] = byCat[d.cat] || []).push(d); });

  let h = '';
  Object.keys(byCat).forEach(cat => {
    h += `<div class="ks-sec">${esc(cat)}</div>`;
    byCat[cat].forEach(d => {
      const isCus = d.cat === 'Custom';
      const cur = KS_MAP[d.id] || '', isRec = KS_REC_ID === d.id, changed = !isCus && cur !== d.def;
      h += `<div class="ks-row">
        <div class="ks-nm">${esc(d.n)}${isCus ? '<span class="ks-badge">Custom</span>' : (changed ? '<small>(customized)</small>' : '')}</div>
        <button class="ks-key ${isRec ? 'rec' : ''} ${!cur && !isRec ? 'empty' : ''}" data-ksrec="${esc(d.id)}" title="Click to customize shortcut">${isRec ? 'Press keys…' : esc(ksFmtCombo(cur))}</button>
        <button class="ks-act" data-ksclr="${esc(d.id)}" title="Clear shortcut">✕</button>
        ${isCus
          ? `<button class="ks-act" data-ksdel="${esc(d.id)}" title="Delete custom shortcut" style="color:#ef5350">🗑</button>`
          : `<button class="ks-act" data-ksdef="${esc(d.id)}" title="Reset to default (${esc(ksFmtCombo(d.def))})">↺</button>`}
      </div>`;
    });
  });
  $('#ksls').innerHTML = h || (KS_CAT === 'Custom'
    ? '<div style="padding:18px;color:#8b93a3">No custom shortcuts yet — click <b>+ Add shortcut</b> above to add your own!</div>'
    : '<div style="padding:18px;color:#8b93a3">No shortcuts found</div>');
  $('#ksls').querySelectorAll('[data-ksrec]').forEach(b => b.onclick = () => { KS_REC_ID = (KS_REC_ID === b.dataset.ksrec) ? null : b.dataset.ksrec; ksUpdNewRecBtn(); ksRender(); });
  $('#ksls').querySelectorAll('[data-ksclr]').forEach(b => b.onclick = () => { KS_MAP[b.dataset.ksclr] = ''; if (KS_REC_ID === b.dataset.ksclr) KS_REC_ID = null; ksSave(); urUpd(); ksRender(); });
  $('#ksls').querySelectorAll('[data-ksdef]').forEach(b => b.onclick = () => {
    const def = KS_DEFS.find(x => x.id === b.dataset.ksdef);
    if (def) { KS_MAP[def.id] = def.def; ksSave(); urUpd(); ksRender(); }
  });
  $('#ksls').querySelectorAll('[data-ksdel]').forEach(b => b.onclick = () => {
    const id = b.dataset.ksdel;
    KS_CUSTOM = KS_CUSTOM.filter(x => x.id !== id);
    delete KS_MAP[id];
    if (KS_REC_ID === id) KS_REC_ID = null;
    ksSave(); ksRender();
    if ($('#fly').style.display === 'block') flyRender();
    toast('Custom shortcut deleted');
  });
}

function ksOpen() {
  cm();
  KS_REC_ID = null;
  KS_NEW_COMBO = '';
  $('#ksform').classList.remove('open');
  $('#ksm').style.display = 'flex';
  $('#ksq').value = '';
  ksPopulateTarget();
  ksUpdNewRecBtn();
  ksRender();
  $('#ksq').focus();
}
$('#ksq').oninput = ksRender;
$('#ksx').onclick = cm;
$('#ksm').onclick = e => { if (e.target.id === 'ksm') cm(); };
$('#ksadd').onclick = () => {
  const f = $('#ksform'), open = !f.classList.contains('open');
  f.classList.toggle('open', open);
  if (open) { KS_REC_ID = null; KS_NEW_COMBO = ''; ksPopulateTarget(); ksUpdNewRecBtn(); }
};
$('#ksat').onchange = ksPopulateTarget;
$('#ksv').onchange = ksSyncTargetInput;
$('#ksrec_new').onclick = () => { KS_REC_ID = (KS_REC_ID === '__NEW__') ? null : '__NEW__'; ksUpdNewRecBtn(); ksRender(); };
$('#kssave_new').onclick = ksAddCustomSave;
$('#kscancel_new').onclick = () => { $('#ksform').classList.remove('open'); if (KS_REC_ID === '__NEW__') KS_REC_ID = null; KS_NEW_COMBO = ''; ksUpdNewRecBtn(); };
$('#ksrst').onclick = () => {
  if (!confirm('Reset all built-in keyboard shortcuts to defaults?')) return;
  KS_DEFS.forEach(d => { KS_MAP[d.id] = d.def; });
  KS_REC_ID = null; ksSave(); urUpd(); ksRender(); toast('All built-in shortcuts reset to defaults');
};
