function profOpen() {
  const m = $('#profm'), b = $('#profbtn');
  if (m.style.display === 'block') { m.style.display = 'none'; b.classList.remove('on'); return; }
  cm();
  profRender();
  const r = b.getBoundingClientRect();
  m.style.display = 'block';
  m.style.left = Math.max(6, Math.min(innerWidth - m.offsetWidth - 6, r.left)) + 'px';
  m.style.top  = (r.bottom + 5) + 'px';
  b.classList.add('on');
}

function infoOpen(title, html) {
  cm();
  $('#infot').textContent = title;
  $('#infoc').innerHTML = html;
  $('#infom').style.display = 'flex';
  if (CUR_LANG !== 'en') i18nApplyNow($('#infob'));
}
$('#infox').onclick = cm;
