function hmFmtPx(s, px) {
  if (!(px > 0)) return '—';
  const inf = symInfo(s), m = inf ? inf[3] : 'S';
  let d = px >= 100 ? 2 : px >= 1 ? 4 : 6;
  if (m === 'FX') {
    const b = inf[1], q = inf[2];
    if (b === 'XAU') d = 2;
    else if (b === 'XAG' || q === 'JPY') d = 3;
    else if (q === 'LKR') d = 2;
    else d = 5;
  } else if (m === 'STK' || m === 'IDX' || m === 'ETF' || m === 'FUT' || m === 'CMD') {
    d = px >= 10 ? 2 : 3;
  }
  return Number(px).toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
}

function hmSparkSvg(seed, up) {
  const col = up ? '#26a69a' : '#ef5350';
  let pts = '', v = 18;
  for (let i = 0; i <= 16; i++) {
    const x = (i / 16) * 86;
    const wave = Math.sin(i * 0.72 + seed) * 5.2 + Math.cos(i * 1.4 + seed * 1.7) * 2.5 + (up ? -i * 0.55 : i * 0.55);
    const y = Math.max(3, Math.min(27, v + wave));
    pts += `${x.toFixed(1)},${y.toFixed(1)} `;
  }
  return `<svg viewBox="0 0 86 30" width="86" height="30" fill="none"><polyline points="${pts.trim()}" stroke="${col}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}

function hmLaunch(opts) {
  opts = opts || {};
  if (opts.ct && typeof dxCheckCtGate === 'function' && !dxCheckCtGate(opts.ct, () => hmLaunch(opts))) return;
  if (opts.tf && typeof dxCheckTfGate === 'function' && !dxCheckTfGate(opts.tf, () => hmLaunch(opts))) return;
  hmClose(true);
  const runApply = () => {
    if (opts.layout && typeof lytSelect === 'function') {
      lytSelect(opts.layout);
      return;
    }
    if (typeof LYT !== 'undefined' && LYT.id !== '1_1' && !opts.keepLayout) {
      lytSelect('1_1');
    }
    if (opts.ct && typeof ctSet === 'function') {
      ctSet(opts.ct);
    }
    if (opts.ind && (IND.some(x => x[0] === opts.ind) || (typeof pineGet === 'function' && pineGet(opts.ind)))) {
      ind[opts.ind] = 1; sI();
    }
    const afterGo = () => {
      if (opts.ind && typeof calc === 'function' && D.length) { calc(); draw(); }
      if (opts.tool && TD[opts.tool]) act(opts.tool);
      if (opts.replay && typeof rplStartPick === 'function') setTimeout(rplStartPick, 220);
      if (opts.range && typeof applyRange === 'function') setTimeout(() => applyRange(opts.range), 250);
      if (opts.settingsTab) setTimeout(() => openChartSettings(opts.settingsTab), 180);
      if (opts.openPine && typeof psmOpen === 'function') setTimeout(() => psmOpen(null, opts.openPine === 'lib' ? 'lib' : null), 160);
      if (opts.openInds) setTimeout(() => { if (typeof opts.openInds === 'string') IND_TAB = opts.openInds; $('#ib').click(); }, 160);
    };
    if (opts.sym && opts.sym !== sym) {
      HOME_CHART_BOOTED = true;
      sym = opts.sym;
      try { localStorage['dx:sym'] = sym; } catch (e) {}
      if (opts.tf && ti(opts.tf)) { tf = opts.tf; try { localStorage['dx:tf'] = tf; } catch (e) {} rtb(); }
      go().then(afterGo);
      return;
    }
    if (opts.tf && ti(opts.tf) && opts.tf !== tf) {
      HOME_CHART_BOOTED = true;
      tf = opts.tf; try { localStorage['dx:tf'] = tf; } catch (e) {} rtb();
      go().then(afterGo);
      return;
    }
    if (!HOME_CHART_BOOTED) {
      HOME_CHART_BOOTED = true;
      go().then(afterGo);
      return;
    }
    if (opts.ind && typeof calc === 'function' && D.length) calc();
    if (opts.tool && TD[opts.tool]) act(opts.tool);
    if (opts.replay && typeof rplStartPick === 'function') rplStartPick();
    if (opts.range && typeof applyRange === 'function') applyRange(opts.range);
    if (opts.settingsTab) openChartSettings(opts.settingsTab);
    if (opts.openPine && typeof psmOpen === 'function') psmOpen(null, opts.openPine === 'lib' ? 'lib' : null);
    if (opts.openInds) { if (typeof opts.openInds === 'string') IND_TAB = opts.openInds; $('#ib').click(); }
    draw();
  };
  runApply();
}

function hmOpen() {
  cm();
  HOME_OPEN = true;
  document.body.classList.add('on-home');
  const el = $('#dx-home');
  if (el) el.scrollTop = 0;
  try { if (location.hash !== '#home') history.replaceState(null, '', '#home'); } catch (e) {}
  hmStartHeroAnim();
  hmFetchLiveTickers();
  if (typeof anPingActivity === 'function') anPingActivity();
  if (CUR_LANG && CUR_LANG !== 'en' && typeof i18nApplyNow === 'function') i18nApplyNow(el);
}

function hmClose(skipBoot) {
  HOME_OPEN = false;
  document.body.classList.remove('on-home');
  hmStopHeroAnim();
  try { if (location.hash !== '#chart') history.replaceState(null, '', '#chart'); } catch (e) {}
  if (typeof anPingActivity === 'function') anPingActivity();
  if (!skipBoot && !HOME_CHART_BOOTED) {
    HOME_CHART_BOOTED = true;
    go();
  } else {
    requestAnimationFrame(() => { draw(); ui(); });
  }
}

