    'pine_tv_smc_fvg','pine_tv_ob','pine_tv_fvg','pine_tv_liq','pine_tv_killzones',
    'pine_tv_supertrend','pine_tv_utbot','pine_tv_sqzmom','pine_tv_wavetrend','pine_tv_ichimoku',
