      h+=`<div class="is-row"><span class="islb">Plot Style</span>${isSel('mode',c.mode||'candles',[['candles','CVD Candles (TradingView)'],['hollow','Hollow CVD Candles'],['line','Cumulative Line'],['area','Cumulative Area'],['hist','Bar Delta Histogram']],'fw')}</div>`;
      h+=`<div class="is-sec">CVD Moving Average</div>`;
