const PINE_TEMPLATES = {
  ema_cross: `//@version=5
indicator("EMA Cross + Signals", shorttitle="EMA Cross", overlay=true)
fastLen = input.int(9, "Fast EMA", minval=1)
slowLen = input.int(21, "Slow EMA", minval=1)
src = input.source(close, "Source")

fast = ta.ema(src, fastLen)
slow = ta.ema(src, slowLen)

p1 = plot(fast, title="Fast EMA", color=color.aqua, linewidth=2)
p2 = plot(slow, title="Slow EMA", color=color.orange, linewidth=2)
fill(p1, p2, color=fast > slow ? color.new(color.green, 82) : color.new(color.red, 82))

bull = ta.crossover(fast, slow)
bear = ta.crossunder(fast, slow)
plotshape(bull, title="Buy", style=shape.triangleup, location=location.belowbar, color=color.lime, text="BUY")
plotshape(bear, title="Sell", style=shape.triangledown, location=location.abovebar, color=color.red, text="SELL")`,

  supertrend: `//@version=5
indicator("Supertrend", overlay=true)
atrPeriod = input.int(10, "ATR Length", minval=1)
factor = input.float(3.0, "Factor", minval=0.5, step=0.1)

[st, dir] = ta.supertrend(factor, atrPeriod)
upPlot = plot(dir < 0 ? st : na, title="Up Trend", color=color.green, linewidth=2, style=plot.style_linebr)
dnPlot = plot(dir > 0 ? st : na, title="Down Trend", color=color.red, linewidth=2, style=plot.style_linebr)
bodyMid = plot(hl2, title="Mid", color=color.new(color.gray, 100))
fill(bodyMid, upPlot, color=color.new(color.green, 88))
fill(bodyMid, dnPlot, color=color.new(color.red, 88))`,

  donchian: `//@version=5
indicator("Donchian Channels", shorttitle="DC", overlay=true)
length = input.int(20, "Length", minval=1)
upper = ta.highest(high, length)
lower = ta.lowest(low, length)
basis = math.avg(upper, lower)

u = plot(upper, title="Upper", color=color.blue, linewidth=1.5)
plot(basis, title="Basis", color=color.orange, linewidth=1.2)
l = plot(lower, title="Lower", color=color.blue, linewidth=1.5)
fill(u, l, color=color.new(color.blue, 90))`,

  ichimoku: `//@version=5
indicator("Ichimoku Cloud", shorttitle="Ichimoku", overlay=true)
convLen = input.int(9, "Conversion Line", minval=1)
baseLen = input.int(26, "Base Line", minval=1)
spanBLen = input.int(52, "Leading Span B", minval=1)
disp = input.int(26, "Displacement", minval=1)

donchian(len) => math.avg(ta.lowest(low, len), ta.highest(high, len))
tenkan = donchian(convLen)
kijun = donchian(baseLen)
lead1 = math.avg(tenkan, kijun)
lead2 = donchian(spanBLen)

plot(tenkan, title="Tenkan-sen", color=#2962ff, linewidth=1.5)
plot(kijun, title="Kijun-sen", color=#b71c1c, linewidth=1.5)
plot(close, title="Chikou", color=#43a047, offset=-disp + 1)
p1 = plot(lead1, title="Span A", color=#26a69a, offset=disp - 1)
p2 = plot(lead2, title="Span B", color=#ef5350, offset=disp - 1)
fill(p1, p2, color=lead1 > lead2 ? color.new(#26a69a, 82) : color.new(#ef5350, 82))`,

  liq_heatmap: `//@version=5
indicator("Liquidity Heatmap — MTF Pivots", shorttitle="Liq Heatmap", overlay=true, max_boxes_count=500, max_lines_count=500)
var GRP1 = "INTRADAY PIVOTS"
leftBars = input.int(7, title="Left Bars", minval=2, maxval=25, group=GRP1)
rightBars = input.int(7, title="Right Bars", minval=2, maxval=25, group=GRP1)
zoneAtr = input.float(0.25, title="Zone ATR Mult", minval=0.05, maxval=2.0, step=0.05, group=GRP1)
maxZones = input.int(24, title="Max Active Zones", minval=4, maxval=80, group=GRP1)
bullCol = input.color(#26a69a, title="Buy-Side / Support Liquidity", group=GRP1)
bearCol = input.color(#ef5350, title="Sell-Side / Resistance Liquidity", group=GRP1)

atrVal = ta.atr(14)
ph = ta.pivothigh(high, leftBars, rightBars)
pl = ta.pivotlow(low, leftBars, rightBars)

var box[] hiBoxes = array.new<box>()
var box[] loBoxes = array.new<box>()

if not na(ph)
    top = ph + atrVal * zoneAtr
    bot = ph - atrVal * zoneAtr * 0.35
    b = box.new(bar_index - rightBars, top, bar_index + 10, bot, border_color=color.new(bearCol, 55), bgcolor=color.new(bearCol, 82))
    array.push(hiBoxes, b)
    if array.size(hiBoxes) > maxZones
        old = array.shift(hiBoxes)
        box.delete(old)

if not na(pl)
    top = pl + atrVal * zoneAtr * 0.35
    bot = pl - atrVal * zoneAtr
    b = box.new(bar_index - rightBars, top, bar_index + 10, bot, border_color=color.new(bullCol, 55), bgcolor=color.new(bullCol, 82))
    array.push(loBoxes, b)
    if array.size(loBoxes) > maxZones
        old = array.shift(loBoxes)
        box.delete(old)

if array.size(hiBoxes) > 0
    for i = array.size(hiBoxes) - 1 to 0
        b = array.get(hiBoxes, i)
        if high >= box.get_bottom(b)
            box.set_right(b, bar_index)
            array.remove(hiBoxes, i)
        else
            box.set_right(b, bar_index + 8)

if array.size(loBoxes) > 0
    for i = array.size(loBoxes) - 1 to 0
        b = array.get(loBoxes, i)
        if low <= box.get_top(b)
            box.set_right(b, bar_index)
            array.remove(loBoxes, i)
        else
            box.set_right(b, bar_index + 8)`,

  stoch_rsi: `//@version=5
indicator("Stochastic RSI", shorttitle="Stoch RSI", overlay=false)
smoothK = input.int(3, "K", minval=1)
smoothD = input.int(3, "D", minval=1)
lenRSI = input.int(14, "RSI Length", minval=1)
lenStoch = input.int(14, "Stoch Length", minval=1)
src = input.source(close, "Source")

rsi1 = ta.rsi(src, lenRSI)
k = ta.sma(ta.stoch(rsi1, rsi1, rsi1, lenStoch), smoothK)
d = ta.sma(k, smoothD)

plot(k, title="K", color=#2962ff, linewidth=1.5)
plot(d, title="D", color=#ff6d00, linewidth=1.5)
h0 = hline(80, title="Upper Band", color=#787b86)
hline(50, title="Middle", color=#787b86, linestyle=hline.style_dotted)
h1 = hline(20, title="Lower Band", color=#787b86)
fill(h0, h1, color=color.new(#7c5cff, 88))`,

  cci: `//@version=5
indicator("Commodity Channel Index", shorttitle="CCI", overlay=false)
len = input.int(20, "Length", minval=1)
src = input.source(hlc3, "Source")
cciVal = ta.cci(src, len)
plot(cciVal, title="CCI", color=#2962ff, linewidth=1.5)
h1 = hline(100, title="Upper", color=#787b86)
hline(0, title="Zero", color=#787b86, linestyle=hline.style_dotted)
h2 = hline(-100, title="Lower", color=#787b86)
fill(h1, h2, color=color.new(#2962ff, 90))`
};

