  const shape=pineNs({triangleup:'triangleup',triangledown:'triangledown',arrowup:'arrowup',arrowdown:'arrowdown',circle:'circle',cross:'cross',xcross:'xcross',diamond:'diamond',flag:'flag',labelup:'labelup',labeldown:'labeldown',square:'square'});
