// --- Pine Script Editor Modal (#psm) Controls, Libraries & Pack Management ---
let PSM_EDIT_ID = null, PSM_IS_LIB = false;

// Dynamically upgrade #psm with Library mode, Import Path field, Export .pine button & Drag/Drop
(function psmEnhanceDOM(){
  const modeSel=$('#psmode');
  if(modeSel&&!modeSel.querySelector('option[value="lib"]')){
    const opt=document.createElement('option');
    opt.value='lib'; opt.textContent='Library (importable module)';
    modeSel.appendChild(opt);
  }
  const bar=$('#psb .ps-bar');
  if(bar&&!$('#pslibpath')){
    const lp=document.createElement('input');
    lp.id='pslibpath'; lp.type='text'; lp.autocomplete='off';
    lp.placeholder='Import path (e.g. Author/LibName/1)';
    lp.style.cssText='display:none;flex:1.1;min-width:190px';
    bar.insertBefore(lp, $('#psmode'));
  }
  const foot=$('#psb .psfoot');
  if(foot&&!$('#psexp')){
    const eb=document.createElement('button');
    eb.type='button'; eb.id='psexp'; eb.title='Download current code as .pine file';
    eb.textContent='⬇ Export .pine';
    foot.insertBefore(eb, foot.firstChild);
  }
  // Drag & Drop .pine / .json files directly onto the Indicators modal (#bx)
  const bx=$('#bx');
  if(bx&&!bx.dataset.ddBound){
    bx.dataset.ddBound='1';
    bx.addEventListener('dragover',e=>{e.preventDefault();bx.classList.add('dd-over')});
    bx.addEventListener('dragleave',e=>{if(!bx.contains(e.relatedTarget))bx.classList.remove('dd-over')});
    bx.addEventListener('drop',e=>{
      e.preventDefault(); bx.classList.remove('dd-over');
      if(e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files.length){
        pineHandleFileList(e.dataTransfer.files, IND_TAB==='libs');
      }
    });
  }
})();

function psmSyncLibUi(){
  const isL=($('#psmode').value==='lib');
  PSM_IS_LIB=isL;
  const lp=$('#pslibpath');
  if(lp)lp.style.display=isL?'':'none';
  $('#psname').placeholder=isL?'Library name (auto from library())':'Script name (auto from indicator())';
  const addB=$('#psadd');
  if(addB)addB.style.display=isL?'none':'';
  const savB=$('#pssave');
  if(savB)savB.textContent=isL?'Save Library':'Save to My Scripts';
}

function psmSetStatus(msg, cls, htmlMode){
  const el=$('#psst');if(!el)return;
  el.className=cls||'';
  if(htmlMode)el.innerHTML=msg;
  else el.textContent=msg;
}

function psmOpen(editId, forceMode, prefillLibPath){
  const isLibEdit=forceMode==='lib'||(editId&&isPineLibId(editId));
  const libObj=(isLibEdit&&editId)?pineLibGet(editId):null;
  const ps=(!isLibEdit&&editId)?pineGet(editId):null;
  const isClone=!!(!isLibEdit&&editId&&isTvPackId(editId));
  PSM_EDIT_ID=isClone?null:(editId||null);
  if(isLibEdit){
    $('#pstit').textContent=libObj?('Edit Pine Library — '+libObj.name):'Pine Script Editor — Add Importable Library';
    $('#psname').value=libObj?libObj.name:(prefillLibPath?(prefillLibPath.split('/')[1]||prefillLibPath):'');
    $('#psmode').value='lib';
    const lp=$('#pslibpath');
    if(lp)lp.value=libObj?libObj.path:(prefillLibPath||'');
    $('#pstpl').value='';
    $('#pscode').value=libObj?libObj.code:(prefillLibPath?`//@version=5\nlibrary("${prefillLibPath.split('/')[1]||'MyLib'}", overlay=true)\n\n// Paste exported library functions below\n`:'');
    psmSyncLibUi();
    psmSetStatus(libObj?'Editing Pine Library. Save to update all scripts importing '+libObj.path+'.':'Paste any TradingView open-source library(...) script and set its Import path (e.g. Author/LibName/1).','');
  }else{
    $('#pstit').textContent=isClone?('Clone & Edit Source — '+ps.name):(ps?('Edit Pine Script — '+ps.name):'Pine Script Editor — Add Custom Indicator');
    $('#psname').value=ps?(isClone?(ps.name+' (Custom)'):ps.name):'';
    $('#psmode').value=ps?(ps.modeOverride||'auto'):'auto';
    const lp=$('#pslibpath'); if(lp)lp.value='';
    $('#pstpl').value='';
    $('#pscode').value=ps?ps.code:'';
    psmSyncLibUi();
    psmSetStatus(isClone?'Viewing built-in pack source code. Edit freely and click Save to save your custom copy to My Scripts.':(ps?'Editing saved script from My Scripts. Click Compile / Test or Save.':'Paste any TradingView Pine Script (v3 / v4 / v5 / v6) or pick a template above.'),'');
  }
  $('#psm').style.display='flex';
  $('#pscode').focus();
}

function psmClose(){
  $('#psm').style.display='none';
  PSM_EDIT_ID=null;
  PSM_IS_LIB=false;
}

function psmValidate(){
  const code=$('#pscode').value.trim();
  if(!code){psmSetStatus('Please paste or write Pine Script code first.','err');return null}
  let meta;
  try{meta=pineExtractMeta(code)}
  catch(e){psmSetStatus('Syntax error: '+(e&&e.message?e.message:String(e)),'err');return null}
  if(meta.isLibrary&&$('#psmode').value==='auto'){
    $('#psmode').value='lib';
    psmSyncLibUi();
  }
  const isL=($('#psmode').value==='lib');
  if(isL){
    let comp;
    try{comp=pineCompile(code,true)}
    catch(e){psmSetStatus('Library syntax error: '+(e&&e.message?e.message:String(e)),'err');return null}
    const name=($('#psname').value.trim()||meta.name||'CustomLib');
    const lpEl=$('#pslibpath');
    const safeSeg=name.replace(/[^a-zA-Z0-9_]+/g,'_').replace(/^_+|_+$/g,'')||'CustomLib';
    const path=pineLibNormPath((lpEl&&lpEl.value.trim())||('Custom/'+safeSeg+'/1'));
    if(lpEl&&!lpEl.value.trim())lpEl.value=path;
    const exps=comp.exports||[];
    psmSetStatus(`✓ Library OK · ${path} · ${exps.length} export${exps.length===1?'':'s'}${exps.length?' ('+exps.slice(0,6).join(', ')+')':''}`,'ok');
    return {isLib:true,name,path,code};
  }
  try{pineCompile(code,false)}
  catch(e){psmSetStatus('Syntax error: '+(e&&e.message?e.message:String(e)),'err');return null}
  const modeVal=$('#psmode').value;
  const overlay=modeVal==='auto'?meta.overlay:(modeVal==='o');
  const name=($('#psname').value.trim()||meta.name||'Custom Pine Script');
  const testPs={id:PSM_EDIT_ID||'pine_test',name,shorttitle:meta.shorttitle||name,overlay,modeOverride:modeVal,code};
  const testBars=D.length?D.slice(-Math.min(D.length,300)):simBuild('BTCUSDT','1h',120);
  const res=pineRun(testPs,testBars);
  if(res.err){psmSetStatus(res.err,'err');return null}
  const parts=[
    overlay?'Overlay':'Sub-pane',
    `${res.plots.length} plot${res.plots.length===1?'':'s'}`,
    `${res.inputs.length} input${res.inputs.length===1?'':'s'}`
  ];
  if(res.boxes&&res.boxes.length)parts.push(`${res.boxes.length} box${res.boxes.length===1?'':'es'}`);
  if(res.lines&&res.lines.length)parts.push(`${res.lines.length} line${res.lines.length===1?'':'s'}`);
  if(res.shapes&&res.shapes.length)parts.push(`${res.shapes.length} signal${res.shapes.length===1?'':'s'}`);
  if(res.usedLibs&&res.usedLibs.length)parts.push(`Linked libs: ${res.usedLibs.join(', ')}`);
  if(res.missingLibs&&res.missingLibs.length){
    const miss=res.missingLibs[0];
    psmSetStatus(`✓ Compiled OK · ${esc(parts.join(' · '))} &nbsp;<span style="color:#f5a623">⚠ Missing library: <code>${esc(res.missingLibs.join(', '))}</code> (running fallback)</span> <button type="button" class="ps-mbtn" data-addmiss="${esc(miss)}">+ Add Library</button>`,'warn',true);
    const mb=$('#psst [data-addmiss]');
    if(mb)mb.onclick=()=>psmOpen(null,'lib',mb.dataset.addmiss);
  }else{
    psmSetStatus('✓ Compiled OK · '+parts.join(' · '),'ok');
  }
  return {isLib:false,name,shorttitle:meta.shorttitle||name,overlay,modeOverride:modeVal,code};
}

function psmSave(addToChart){
  const info=psmValidate();
  if(!info)return;
  if(info.isLib){
    let id=PSM_EDIT_ID;
    if(id&&isPineLibId(id)){
      const lib=pineLibGet(id);
      if(lib){lib.name=info.name;lib.path=info.path;lib.code=info.code}
    }else{
      const existing=PINE_LIBS.find(l=>pineLibNormPath(l.path).toLowerCase()===info.path.toLowerCase());
      if(existing){existing.name=info.name;existing.path=info.path;existing.code=info.code}
      else PINE_LIBS.push({id:'plib_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,6),name:info.name,path:info.path,desc:'Custom Pine Library',code:info.code});
    }
    svPineLibs();
    PINE_COMPILE_CACHE.clear();
    IND_TAB='libs';
    psmClose();
    ismRecalcRedraw();
    toast('Saved Pine Library: '+info.path);
    return;
  }
  let id=PSM_EDIT_ID;
  if(id){
    const ps=pineGet(id);
    if(ps)Object.assign(ps,info);
  }else{
    id='pine_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,6);
    PINE_SCRIPTS.push(Object.assign({id},info));
  }
  svPines();
  IND_TAB='my';
  if(addToChart){
    if(typeof LYT!=='undefined'&&LYT.id!=='1_1'){
      const p=lytCur();p.ind[id]=1;ind=Object.assign({},p.ind);sI();lytSave();
    }else{
      ind[id]=1;sI();
    }
  }
  psmClose();
  ismRecalcRedraw();
  toast((addToChart?'Added to chart & saved to My Scripts: ':'Saved to My Scripts: ')+info.name);
}

function pineDelete(id){
  const ps=pineGet(id);if(!ps)return;
  if(!confirm('Delete "'+ps.name+'" from My Scripts?'))return;
  PINE_SCRIPTS=PINE_SCRIPTS.filter(p=>p.id!==id);
  svPines();
  delete ind[id]; sI();
  delete IND_CFG[id]; svICfg();
  if(typeof LYT!=='undefined'&&LYT.panes.length)LYT.panes.forEach(p=>{delete p.ind[id]});
  slc=''; pnc=null;
  rl(); ismRecalcRedraw();
  toast('Deleted "'+ps.name+'"');
}

