// =========================================================================
// GLOBAL TRADINGVIEW COLOR PICKER (#tvcp) — EXACT 10x8 PALETTE + CUSTOM '+' + OPACITY
// =========================================================================
let TVCP_ST = null;

function tvcpEnsureDom() {
  let el = $('#tvcp');
  if (el) return el;
  el = document.createElement('div');
  el.id = 'tvcp';
  el.setAttribute('role', 'dialog');
  document.body.appendChild(el);
  return el;
}

function tvcpClose() {
  const el = $('#tvcp');
  if (el) el.style.display = 'none';
  TVCP_ST = null;
}

function tvcpFindOpacityRange(inp) {
  if (!inp) return null;
  const colw = inp.closest('.is-colw');
  if (colw) {
    const r = colw.querySelector('input[type="range"]');
    if (r) return r;
  }
  const dp = inp.dataset.p;
  if (dp) {
    const scope = inp.closest('#sp') || document;
    const cands = [];
    if (dp.endsWith('.c')) cands.push(dp.slice(0, -2) + '.o', dp.slice(0, -2) + '.fo');
    else if (dp.endsWith('.lc')) cands.push(dp.slice(0, -3) + '.lo');
    else if (dp.endsWith('.bc')) cands.push(dp.slice(0, -3) + '.bo');
    else if (dp.endsWith('.t')) cands.push(dp + 'o');
    else if (dp.endsWith('.b')) cands.push(dp + 'o');
    else if (dp.endsWith('.hcf')) cands.push(dp.slice(0, -1) + 'o');
    else if (dp.endsWith('.clf')) cands.push(dp.slice(0, -1) + 'o');
    else if (/\.(tf1|tf2|bf1|bf2)$/.test(dp)) cands.push(dp + 'o');
    else if (dp.endsWith('.vac')) cands.push(dp.slice(0, -1) + 'o');
    else if (dp.endsWith('.outc')) cands.push(dp.slice(0, -1) + 'o');
    else if (dp.endsWith('.spc')) cands.push(dp.slice(0, -1) + 'o');
    for (const cp of cands) {
      const hit = scope.querySelector(`input[type="range"][data-p="${cp}"]`);
      if (hit) return hit;
    }
  }
  const row = inp.closest('.lr,.is-line,.ds-row,.is-row');
  if (row) {
    const cols = row.querySelectorAll('input[type="color"]:not([data-tvcp-native])');
    const rngs = row.querySelectorAll('input[type="range"]');
    if (cols.length === 1 && rngs.length === 1 && !rngs[0].disabled) {
      const mx = parseFloat(rngs[0].max);
      if (mx <= 1.05 || mx === 100) return rngs[0];
    }
  }
  return null;
}

function tvcpReacquire(meta) {
  if (meta.el && meta.el.isConnected) return meta.el;
  const root = meta.rootSel ? document.querySelector(meta.rootSel) : document;
  if (!root) return null;
  if (meta.id) { const hit = root.querySelector('#' + CSS.escape(meta.id)); if (hit) { meta.el = hit; return hit; } }
  if (meta.dp) { const hit = root.querySelector(`input[type="color"][data-p="${CSS.escape(meta.dp)}"]`); if (hit) { meta.el = hit; return hit; } }
  if (meta.dip) { const hit = root.querySelector(`input[type="color"][data-ip="${CSS.escape(meta.dip)}"]`); if (hit) { meta.el = hit; return hit; } }
  if (meta.dipcol) { const hit = root.querySelector(`input[type="color"][data-ipcol="${CSS.escape(meta.dipcol)}"]`); if (hit) { meta.el = hit; return hit; } }
  return null;
}

function tvcpOpenForInput(inp) {
  const opEl = tvcpFindOpacityRange(inp);
  const meta = {
    el: inp,
    id: inp.id || '',
    dp: inp.dataset.p || '',
    dip: inp.dataset.ip || '',
    dipcol: inp.dataset.ipcol || '',
    rootSel: inp.closest('#sp') ? '#sp' : inp.closest('#dsp') ? '#dsp' : inp.closest('#isp') ? '#isp' : ''
  };
  let hasOp = false, opVal = 1, opMin = 0, opMax = 1, opScale = 1;
  if (opEl) {
    hasOp = true;
    const rMax = parseFloat(opEl.max);
    const rMin = parseFloat(opEl.min);
    opScale = (rMax > 1.5) ? 100 : 1;
    opMax = isNaN(rMax) ? 1 : (rMax / opScale);
    opMin = isNaN(rMin) ? 0 : (rMin / opScale);
    opVal = Math.max(0, Math.min(1, (parseFloat(opEl.value) || 0) / opScale));
  }
  const anchor = inp.closest('.ds-swbox') || inp;
  tvcpOpen({
    anchor,
    color: tvcpNormHex(inp.value),
    hasOpacity: hasOp,
    opacity: opVal,
    opMin,
    opMax,
    onColor: hex => {
      const cur = tvcpReacquire(meta);
      if (!cur) return;
      cur.value = hex;
      const sw = cur.closest('.ds-swbox');
      if (sw && !cur.dataset.ipcol) sw.style.background = hex;
      cur.dispatchEvent(new Event('input', { bubbles: true }));
      cur.dispatchEvent(new Event('change', { bubbles: true }));
    },
    onOpacity: hasOp ? (op => {
      const cur = tvcpReacquire(meta);
      const r = (opEl && opEl.isConnected) ? opEl : tvcpFindOpacityRange(cur);
      if (!r) return;
      const rawV = opScale === 100 ? Math.round(op * 100) : Math.round(op * 100) / 100;
      r.value = String(rawV);
      r.dispatchEvent(new Event('input', { bubbles: true }));
      r.dispatchEvent(new Event('change', { bubbles: true }));
    }) : null
  });
}

function tvcpOpen(opts) {
  const el = tvcpEnsureDom();
  const st = {
    color: tvcpNormHex(opts.color || '#2962ff'),
    hasOpacity: !!opts.hasOpacity,
    opacity: opts.opacity == null ? 1 : Math.max(0, Math.min(1, +opts.opacity)),
    opMin: opts.opMin == null ? 0 : +opts.opMin,
    opMax: opts.opMax == null ? 1 : +opts.opMax,
    onColor: opts.onColor || (() => {}),
    onOpacity: opts.onOpacity || null,
    topHtml: opts.topHtml || '',
    bindTop: opts.bindTop || null
  };
  TVCP_ST = st;

  const swHtml = (hex, isCust) => {
    const act = hex.toLowerCase() === st.color.toLowerCase() ? ' sel' : '';
    const darkBorder = (hex === '#000000' || hex === '#131722' || hex === '#ffffff') ? ' tvcp-sw-b' : '';
    return `<button type="button" class="tvcp-sw${act}${darkBorder}" data-tvsw="${hex}"${isCust ? ' data-tvcust="1" title="Custom color (right-click to remove)"' : ` title="${hex.toUpperCase()}"`} style="background:${hex}"></button>`;
  };

  const renderBody = () => {
    const [r, g, b] = tvcpRgb(st.color);
    const pct = Math.round(st.opacity * 100);
    const grad = `linear-gradient(90deg, rgba(${r},${g},${b},0) 0%, rgb(${r},${g},${b}) 100%)`;
    el.innerHTML = `
      ${st.topHtml ? `<div class="tvcp-top">${st.topHtml}</div>` : ''}
      <div class="tvcp-grid tvcp-g1">${TVCP_ROW1.map(c => swHtml(c)).join('')}${TVCP_ROW2.map(c => swHtml(c)).join('')}</div>
      <div class="tvcp-grid tvcp-g2">${TVCP_SHADES.map(c => swHtml(c)).join('')}</div>
      <div class="tvcp-sep"></div>
      <div class="tvcp-cust">
        ${TVCP_CUST.map(c => swHtml(c, true)).join('')}
        <label class="tvcp-add" title="Custom color…">
          <svg viewBox="0 0 18 18" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M9 3.5v11M3.5 9h11"/></svg>
          <input type="color" class="tvcp-nat-in" data-tvcp-native="1" value="${st.color}">
        </label>
      </div>
      <div class="tvcp-op ${st.hasOpacity ? '' : 'tvcp-op-na'}" title="${st.hasOpacity ? 'Drag to adjust opacity' : 'Solid color (100%)'}">
        <div class="tvcp-oplb">Opacity</div>
        <div class="tvcp-oprow">
          <div class="tvcp-track">
            <div class="tvcp-grad" style="background:${grad}"></div>
            <input type="range" class="tvcp-rng" min="${Math.round(st.opMin * 100)}" max="${Math.round(st.opMax * 100)}" step="1" value="${pct}" ${st.hasOpacity ? '' : 'disabled'}>
          </div>
          <div class="tvcp-pctbox">
            <input type="number" class="tvcp-pctin" min="${Math.round(st.opMin * 100)}" max="${Math.round(st.opMax * 100)}" value="${pct}" ${st.hasOpacity ? '' : 'disabled'}><span>%</span>
          </div>
        </div>
      </div>
    `;

    if (st.bindTop) st.bindTop(el);

    const syncVisual = () => {
      const [rr, gg, bb] = tvcpRgb(st.color);
      const gr = el.querySelector('.tvcp-grad');
      if (gr) gr.style.background = `linear-gradient(90deg, rgba(${rr},${gg},${bb},0) 0%, rgb(${rr},${gg},${bb}) 100%)`;
      el.querySelectorAll('.tvcp-sw').forEach(btn => {
        btn.classList.toggle('sel', btn.dataset.tvsw.toLowerCase() === st.color.toLowerCase());
      });
      const nat = el.querySelector('.tvcp-nat-in');
      if (nat && document.activeElement !== nat) nat.value = st.color;
    };

    el.querySelectorAll('.tvcp-sw').forEach(btn => {
      btn.onclick = () => {
        st.color = btn.dataset.tvsw.toLowerCase();
        syncVisual();
        st.onColor(st.color);
      };
      if (btn.dataset.tvcust === '1') {
        btn.oncontextmenu = ev => {
          ev.preventDefault();
          const rm = btn.dataset.tvsw.toLowerCase();
          TVCP_CUST = TVCP_CUST.filter(x => x !== rm);
          try { localStorage['dx:tvcp_cust'] = JSON.stringify(TVCP_CUST); } catch (e) {}
          renderBody();
        };
      }
    });

    const nat = el.querySelector('.tvcp-nat-in');
    if (nat) {
      nat.oninput = ev => {
        st.color = tvcpNormHex(ev.target.value);
        syncVisual();
        st.onColor(st.color);
      };
      nat.onchange = ev => {
        st.color = tvcpNormHex(ev.target.value);
        tvcpSaveCust(st.color);
        st.onColor(st.color);
        renderBody();
      };
    }

    const rng = el.querySelector('.tvcp-rng');
    const pin = el.querySelector('.tvcp-pctin');
    const applyOp = pctVal => {
      if (!st.hasOpacity || !st.onOpacity) return;
      const loP = Math.round(st.opMin * 100), hiP = Math.round(st.opMax * 100);
      const cl = Math.max(loP, Math.min(hiP, Math.round(+pctVal || 0)));
      st.opacity = cl / 100;
      if (rng && +rng.value !== cl) rng.value = cl;
      if (pin && +pin.value !== cl) pin.value = cl;
      st.onOpacity(st.opacity);
    };
    if (rng) rng.oninput = ev => applyOp(ev.target.value);
    if (pin) pin.oninput = ev => { if (ev.target.value !== '') applyOp(ev.target.value); };
  };

  renderBody();
  el.style.display = 'block';
  const r = opts.anchor ? opts.anchor.getBoundingClientRect() : { left: innerWidth / 2 - 128, top: innerHeight / 2 - 140, right: innerWidth / 2, bottom: innerHeight / 2 };
  const pw = el.offsetWidth || 256, ph = el.offsetHeight || 300;
  let left = r.left, top = r.bottom + 6;
  if (left + pw > innerWidth - 8) left = Math.max(8, r.right - pw);
  if (left + pw > innerWidth - 8) left = Math.max(8, innerWidth - pw - 8);
  if (top + ph > innerHeight - 8) top = Math.max(8, r.top - ph - 6);
  el.style.left = Math.max(8, Math.round(left)) + 'px';
  el.style.top  = Math.max(8, Math.round(top)) + 'px';
}

document.addEventListener('click', e => {
  const inp = e.target;
  if (inp && inp.tagName === 'INPUT' && inp.type === 'color' && inp.dataset.tvcpNative !== '1') {
    if (inp.disabled) return;
    e.preventDefault();
    e.stopPropagation();
    tvcpOpenForInput(inp);
    return;
  }
  const cp = $('#tvcp');
  if (cp && cp.style.display === 'block' && !e.target.closest('#tvcp')) {
    tvcpClose();
  }
}, true);

document.addEventListener('keydown', e => {
  const cp = $('#tvcp');
  if (e.key === 'Escape' && cp && cp.style.display === 'block') {
    e.stopPropagation();
    tvcpClose();
  }
}, true);


// =========================================================================
// TRADINGVIEW-STYLE CUSTOM SAVED CHART LAYOUTS MANAGER (#layb, #layp, #laym)
// =========================================================================
let LAY_STORE = { activeId: '', autosave: true, list: [] };
let LAY_DIRTY = false, LAY_AUTO_TMR = null, LAY_LOADING = false;

function layLoadStore() {
  try {
    const raw = JSON.parse(localStorage['dx:saved_layouts'] || 'null');
    if (raw && Array.isArray(raw.list) && raw.list.length) {
      LAY_STORE = {
        activeId: raw.activeId || raw.list[0].id,
        autosave: raw.autosave !== false,
        list: raw.list
      };
      if (!LAY_STORE.list.some(x => x.id === LAY_STORE.activeId)) {
        LAY_STORE.activeId = LAY_STORE.list[0].id;
      }
      return;
    }
  } catch (e) {}
  const id0 = 'lay_' + Date.now().toString(36);
  LAY_STORE = {
    activeId: id0,
    autosave: true,
    list: [layBuildSnapshot(id0, 'Unnamed', false)]
  };
  layPersistStore();
}

function layPersistStore() {
  try { localStorage['dx:saved_layouts'] = JSON.stringify(LAY_STORE); } catch (e) {
    try {
      LAY_STORE.list.forEach(item => { if (item.id !== LAY_STORE.activeId && item.dr && item.dr.length > 60) item.dr = item.dr.slice(-60); });
      localStorage['dx:saved_layouts'] = JSON.stringify(LAY_STORE);
    } catch (e2) {}
  }
}

function layActive() {
  return LAY_STORE.list.find(x => x.id === LAY_STORE.activeId) || LAY_STORE.list[0] || null;
}

function laySubLabel(item) {
  const s = item.sym || 'BTCUSDT';
  const inf = typeof symInfo === 'function' ? symInfo(s) : null;
  let disp = s.replace(/^[A-Z]+:/, '');
  if (inf && (inf[3] === 'S' || inf[3] === 'F') && s.endsWith('.P') && !disp.endsWith('.P')) disp += '.P';
  const I = ti(item.tf || '3m');
  const tfDisp = I ? (I.u === 'm' ? String(I.n) : tfS(item.tf)) : (item.tf || '3m');
  const cnt = (item.lytId && item.lytId !== '1_1' && LYT_MAP[item.lytId]) ? (' · ' + LYT_MAP[item.lytId].c.length + ' charts') : '';
  return `${disp}, ${tfDisp}${cnt}`;
}

function layBuildSnapshot(id, name, shared) {
  const isMulti = (typeof LYT !== 'undefined' && LYT.id !== '1_1' && LYT.panes.length);
  const panesSnap = isMulti
    ? LYT.panes.map(p => ({
        sym: p.sym, tf: p.tf, ind: Object.assign({}, p.ind),
        bw: p.bw, off: p.off, LG: !!p.LG,
        CFG: JSON.parse(JSON.stringify(p.CFG || CFG))
      }))
    : [];
  const stripKeys = o => { if (o) { delete o.tdk; delete o.oandaKey; delete o.fhk; } return o; };
  panesSnap.forEach(p => stripKeys(p.CFG));
  const cfgCopy = stripKeys(JSON.parse(JSON.stringify(CFG)));
  return {
    id: id || ('lay_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 5)),
    name: String(name || 'Unnamed').trim() || 'Unnamed',
    shared: !!shared,
    updatedAt: Date.now(),
    sym,
    tf,
    LG: !!LG,
    bw,
    off,
    CFG: cfgCopy,
    ind: Object.assign({}, ind),
    IND_CFG: JSON.parse(JSON.stringify(IND_CFG || {})),
    lytId: (typeof LYT !== 'undefined' ? LYT.id : '1_1'),
    lytSync: (typeof LYT !== 'undefined' ? Object.assign({}, LYT.sync) : { sym:0, tf:0, ch:1, tm:0, dr:0 }),
    lytPanes: panesSnap,
    dark: typeof DARK_ON !== 'undefined' ? !!DARK_ON : true,
    dpanel: typeof DPANEL_ON !== 'undefined' ? !!DPANEL_ON : true,
    tbw: typeof TB_W !== 'undefined' ? TB_W : 48,
    dr: Array.isArray(DR) ? JSON.parse(JSON.stringify(DR)) : []
  };
}

function layUpdateBtn() {
  const act = layActive();
  const nmEl = $('#laynm'), dotEl = $('#laydot');
  if (nmEl && act) nmEl.textContent = act.name;
  if (dotEl) dotEl.classList.toggle('show', !!LAY_DIRTY && !LAY_STORE.autosave);
}

function layMarkDirty() {
  if (LAY_LOADING || !LAY_STORE.list.length) return;
  LAY_DIRTY = true;
  layUpdateBtn();
  if (LAY_STORE.autosave) {
    clearTimeout(LAY_AUTO_TMR);
    LAY_AUTO_TMR = setTimeout(() => laySaveActive(true), 550);
  }
}

function laySaveActive(silent) {
  const act = layActive();
  if (!act) return;
  const idx = LAY_STORE.list.findIndex(x => x.id === act.id);
  const snap = layBuildSnapshot(act.id, act.name, act.shared);
  if (idx >= 0) LAY_STORE.list[idx] = snap;
  else LAY_STORE.list.unshift(snap);
  LAY_DIRTY = false;
  layPersistStore();
  layUpdateBtn();
  if ($('#layp') && $('#layp').style.display === 'block') layRenderMenu();
  if (!silent) toast('Layout saved: ' + snap.name);
}

function layApply(item, silent) {
  if (!item) return;
  LAY_LOADING = true;
  clearTimeout(LAY_AUTO_TMR);
  try {
    LAY_STORE.activeId = item.id;
    item.updatedAt = Date.now();
    layPersistStore();

    if (typeof setDarkTheme === 'function' && item.dark !== undefined) {
      setDarkTheme(!!item.dark, true);
      try { localStorage['dx:theme'] = item.dark ? 'dark' : 'light'; } catch (e) {}
    }
    if (typeof setDrawPanel === 'function' && item.dpanel !== undefined) {
      setDrawPanel(!!item.dpanel, true);
      try { localStorage['dx:dpanel'] = item.dpanel ? '1' : '0'; } catch (e) {}
    }
    if (typeof applyTbWidth === 'function' && item.tbw) {
      applyTbWidth(item.tbw, true);
    }

    if (item.CFG) {
      const keepKeys = { tdk: CFG.tdk || '', oandaKey: CFG.oandaKey || '', oandaEnv: CFG.oandaEnv || 'practice', fhk: CFG.fhk || '' };
      CFG = deepM(JSON.parse(JSON.stringify(DEF)), JSON.parse(JSON.stringify(item.CFG)));
      if (!CFG.tdk && keepKeys.tdk) CFG.tdk = keepKeys.tdk;
      if (!CFG.oandaKey && keepKeys.oandaKey) { CFG.oandaKey = keepKeys.oandaKey; CFG.oandaEnv = keepKeys.oandaEnv; }
      if (!CFG.fhk && keepKeys.fhk) CFG.fhk = keepKeys.fhk;
      try { localStorage['dx:cfg'] = JSON.stringify(CFG); } catch (e) {}
      if (typeof aFz === 'function') aFz();
      if (typeof ctInvalidate === 'function') ctInvalidate();
    }

    if (item.ind) {
      ind = Object.assign({}, item.ind);
      try { localStorage['dx:ind'] = JSON.stringify(ind); } catch (e) {}
    }
    if (item.IND_CFG) {
      IND_CFG = JSON.parse(JSON.stringify(item.IND_CFG));
      IND.forEach(i => { const k = i[0]; IND_CFG[k] = deepM(indDefOne(k), IND_CFG[k] || {}); if (!IND_CFG[k].vis) IND_CFG[k].vis = IND_VIS_DEF(); });
      try { localStorage['dx:indcfg'] = JSON.stringify(IND_CFG); } catch (e) {}
    }

    const targetSym = item.sym || sym;
    const targetTf = (item.tf && ti(item.tf)) ? item.tf : tf;
    sym = targetSym;
    tf = targetTf;
    LG = !!item.LG;
    if (item.bw) bw = item.bw;
    if (item.off != null) off = item.off;
    try { localStorage['dx:sym'] = sym; localStorage['dx:tf'] = tf; } catch (e) {}
    if (Array.isArray(item.dr)) {
      DR = JSON.parse(JSON.stringify(item.dr));
      try { localStorage['dx:' + sym] = JSON.stringify(DR); } catch (e) {}
    }

    const targetLytId = (item.lytId && LYT_MAP[item.lytId]) ? item.lytId : '1_1';
    if (typeof LYT !== 'undefined') {
      if (item.lytSync) Object.assign(LYT.sync, item.lytSync);
      if (targetLytId !== '1_1' && Array.isArray(item.lytPanes) && item.lytPanes.length) {
        LYT.saved = JSON.parse(JSON.stringify(item.lytPanes));
        LYT.panes = [];
        LYT.id = '1_1';
        lytSelect(targetLytId);
      } else if (LYT.id !== '1_1') {
        LYT.panes = [];
        lytSelect('1_1');
      } else {
        rtb();
        go();
      }
    } else {
      rtb();
      go();
    }
    LAY_DIRTY = false;
    layUpdateBtn();
    if (!silent) toast('Loaded layout: ' + item.name);
  } finally {
    setTimeout(() => { LAY_LOADING = false; }, 120);
  }
}

function layCreateNew() {
  const nm0 = prompt('Create new layout — enter layout name:', 'Layout ' + (LAY_STORE.list.length + 1));
  if (!nm0 || !nm0.trim()) return;
  if (LAY_STORE.autosave) laySaveActive(true);
  const id = 'lay_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 5);
  const snap = layBuildSnapshot(id, nm0.trim(), false);
  LAY_STORE.list.unshift(snap);
  LAY_STORE.activeId = id;
  LAY_DIRTY = false;
  layPersistStore();
  layUpdateBtn();
  if ($('#layp')) $('#layp').style.display = 'none';
  if ($('#laym') && $('#laym').style.display === 'flex') layRenderModal();
  toast('Created layout: ' + snap.name);
}

function layMakeCopy() {
  const act = layActive();
  const defNm = (act ? act.name : 'Layout') + ' (Copy)';
  const nm0 = prompt('Make a copy — enter new layout name:', defNm);
  if (!nm0 || !nm0.trim()) return;
  const id = 'lay_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 5);
  const snap = layBuildSnapshot(id, nm0.trim(), false);
  LAY_STORE.list.unshift(snap);
  LAY_STORE.activeId = id;
  LAY_DIRTY = false;
  layPersistStore();
  layUpdateBtn();
  if ($('#layp')) $('#layp').style.display = 'none';
  toast('Copied to layout: ' + snap.name);
}

function layRename(idOpt) {
  const tgt = idOpt ? LAY_STORE.list.find(x => x.id === idOpt) : layActive();
  if (!tgt) return;
  const nm0 = prompt('Rename layout:', tgt.name);
  if (!nm0 || !nm0.trim()) return;
  tgt.name = nm0.trim();
  tgt.updatedAt = Date.now();
  layPersistStore();
  layUpdateBtn();
  if ($('#layp') && $('#layp').style.display === 'block') layRenderMenu();
  if ($('#laym') && $('#laym').style.display === 'flex') layRenderModal();
  toast('Renamed layout to: ' + tgt.name);
}

function layDelete(id) {
  if (LAY_STORE.list.length <= 1) { toast('At least one layout must remain'); return; }
  const tgt = LAY_STORE.list.find(x => x.id === id);
  if (!tgt) return;
  if (!confirm(`Delete layout "${tgt.name}"?`)) return;
  LAY_STORE.list = LAY_STORE.list.filter(x => x.id !== id);
  if (LAY_STORE.activeId === id) {
    LAY_STORE.activeId = LAY_STORE.list[0].id;
    layApply(LAY_STORE.list[0], true);
  } else {
    layPersistStore();
    layUpdateBtn();
  }
  if ($('#layp') && $('#layp').style.display === 'block') layRenderMenu();
  if ($('#laym') && $('#laym').style.display === 'flex') layRenderModal();
  toast('Deleted layout: ' + tgt.name);
}

function layExportJson(idOpt) {
  const tgt = idOpt ? LAY_STORE.list.find(x => x.id === idOpt) : layActive();
  if (!tgt) return;
  const snap = (tgt.id === LAY_STORE.activeId) ? layBuildSnapshot(tgt.id, tgt.name, tgt.shared) : tgt;
  const payload = Object.assign({ type: 'dreamx_chart_layout', version: 1 }, snap);
  const safeNm = snap.name.replace(/[^a-zA-Z0-9_\-]+/g, '_').replace(/^_+|_+$/g, '') || 'layout';
  pineDownloadFile(`DreamX-Layout-${safeNm}.json`, JSON.stringify(payload, null, 2), 'application/json;charset=utf-8');
  toast('Exported layout: ' + snap.name);
}

function layImportJson() {
  const inp = document.createElement('input');
  inp.type = 'file'; inp.accept = '.json,application/json';
  inp.onchange = () => {
    const fl = inp.files && inp.files[0]; if (!fl) return;
    const r = new FileReader();
    r.onload = () => {
      try {
        const j = JSON.parse(String(r.result || ''));
        if (!j || typeof j !== 'object' || (!j.CFG && !j.sym)) { toast('Invalid layout JSON file'); return; }
        j.id = 'lay_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 5);
        j.name = String(j.name || fl.name.replace(/\.json$/i, '') || 'Imported Layout').trim();
        j.updatedAt = Date.now();
        LAY_STORE.list.unshift(j);
        layPersistStore();
        layApply(j, false);
        if ($('#laym') && $('#laym').style.display === 'flex') layRenderModal();
      } catch (e) { toast('Failed to parse layout JSON'); }
    };
    r.readAsText(fl);
  };
  inp.click();
}

function layDownloadCsv() {
  const arr = (typeof LYT !== 'undefined' && LYT.id !== '1_1' && lytCur()) ? lytCur().D : D;
  const curS = (typeof LYT !== 'undefined' && LYT.id !== '1_1' && lytCur()) ? lytCur().sym : sym;
  const curT = (typeof LYT !== 'undefined' && LYT.id !== '1_1' && lytCur()) ? lytCur().tf : tf;
  if (!arr || !arr.length) { toast('No chart data to download'); return; }
  const lines = ['time,datetime_utc,open,high,low,close,volume'];
  for (let i = 0; i < arr.length; i++) {
    const b = arr[i];
    lines.push(`${Math.floor(b.t / 1000)},${new Date(b.t).toISOString()},${b.o},${b.h},${b.l},${b.c},${b.v || 0}`);
  }
  const safeS = String(curS).replace(/[^a-zA-Z0-9._-]+/g, '_');
  pineDownloadFile(`${safeS}_${curT}.csv`, lines.join('\n'), 'text/csv;charset=utf-8');
  toast(`Downloaded ${arr.length.toLocaleString()} bars (${safeS}_${curT}.csv)`);
}

const LAY_IC = {
  copy: '<svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="6.5" y="6.5" width="9.5" height="9.5" rx="1.5"/><path d="M4 13.5V5a1.5 1.5 0 0 1 1.5-1.5H14"/></svg>',
  edit: '<svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M13.8 3.6l2.6 2.6-8.8 8.8H5v-2.6z"/></svg>',
  dl:   '<svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M10 3.5v9m0 0l-3.2-3.2M10 12.5l3.2-3.2M4 15.8h12"/></svg>',
  plus: '<svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M10 4v12M4 10h12"/></svg>',
  fold: '<svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"><path d="M2.8 5.5A1.5 1.5 0 0 1 4.3 4h3.5l1.6 1.8h6.3a1.5 1.5 0 0 1 1.5 1.5v7.2a1.5 1.5 0 0 1-1.5 1.5H4.3a1.5 1.5 0 0 1-1.5-1.5z"/></svg>'
};

function layRenderMenu() {
  const p = $('#layp'); if (!p) return;
  const act = layActive();
  const recent = LAY_STORE.list.slice().sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0)).slice(0, 6);
  const saveDis = !LAY_DIRTY && LAY_STORE.autosave;
  p.innerHTML = `
    <div class="lay-it ${saveDis ? 'mu-it' : ''}" data-la="save"><span class="lay-lb">Save layout</span><span class="lay-hk">Ctrl + S</span></div>
    <div class="lay-it" data-la="auto"><span class="lay-lb">Autosave</span><span class="lay-sw ${LAY_STORE.autosave ? 'on' : ''}"></span></div>
    <div class="lay-it" data-la="copy"><span class="lay-ic">${LAY_IC.copy}</span><span class="lay-lb">Make a copy…</span></div>
    <div class="lay-it" data-la="ren"><span class="lay-ic">${LAY_IC.edit}</span><span class="lay-lb">Rename…</span></div>
    <div class="lay-it" data-la="dl"><span class="lay-ic">${LAY_IC.dl}</span><span class="lay-lb">Download chart data…</span></div>
    <div class="lay-sep"></div>
    <div class="lay-it" data-la="new"><span class="lay-ic">${LAY_IC.plus}</span><span class="lay-lb">Create new layout…</span></div>
    <div class="lay-sep"></div>
    <div class="lay-sec">RECENTLY USED</div>
    <div class="lay-cards">${recent.map(it => {
      const isAct = act && it.id === act.id;
      return `<div class="lay-card ${isAct ? 'act' : ''}" data-lpick="${it.id}"><div class="lay-ct"><b>${esc(it.name)}</b><small>${esc(laySubLabel(it))}</small></div>${LAY_STORE.list.length > 1 ? `<button type="button" class="lay-cdel" data-ldel="${it.id}" title="Delete layout">✕</button>` : ''}</div>`;
    }).join('')}</div>
    <div class="lay-sep"></div>
    <div class="lay-it" data-la="open"><span class="lay-ic">${LAY_IC.fold}</span><span class="lay-lb">Open layout…</span><span class="lay-hk">Dot</span></div>
  `;
}

function layOpenMenu() {
  const p = $('#layp'), b = $('#layb');
  if (!p || !b) return;
  if (p.style.display === 'block') { p.style.display = 'none'; return; }
  if ($('#lytp')) $('#lytp').style.display = 'none';
  layRenderMenu();
  p.style.display = 'block';
  const r = b.getBoundingClientRect();
  const pw = p.offsetWidth || 238;
  p.style.left = Math.max(6, Math.min(innerWidth - pw - 6, r.right - pw)) + 'px';
  p.style.top = (r.bottom + 4) + 'px';
}

function layRenderModal() {
  const ls = $('#layls'); if (!ls) return;
  const q = ($('#layq') ? $('#layq').value : '').toLowerCase().trim();
  const act = layActive();
  const items = LAY_STORE.list
    .slice()
    .sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0))
    .filter(x => !q || (x.name + ' ' + (x.sym || '') + ' ' + (x.tf || '')).toLowerCase().includes(q));
  ls.innerHTML = items.map(it => {
    const isAct = act && it.id === act.id;
    const dtStr = it.updatedAt ? new Date(it.updatedAt).toLocaleString() : '';
    const indCnt = it.ind ? Object.values(it.ind).filter(Boolean).length : 0;
    return `<div class="it ${isAct ? 'it-on' : ''}" data-lmopen="${it.id}">
      <div class="it-l"><div class="it-txt"><b>${esc(it.name)} ${isAct ? '<span class="ps-tag">ACTIVE</span>' : ''}</b><br><small>${esc(laySubLabel(it))} · ${indCnt} indicator${indCnt === 1 ? '' : 's'} · ${esc(dtStr)}</small></div></div>
      <span class="it-r">
        <button type="button" class="it-act" data-lmren="${it.id}" title="Rename">✎</button>
        <button type="button" class="it-act" data-lmexp="${it.id}" title="Export JSON">⬇</button>
        ${LAY_STORE.list.length > 1 ? `<button type="button" class="it-act del" data-lmdel="${it.id}" title="Delete">🗑</button>` : ''}
      </span>
    </div>`;
  }).join('') || '<div class="it" style="cursor:default">No saved layouts match your search</div>';
}

function layModalOpen() {
  if ($('#layp')) $('#layp').style.display = 'none';
  if (!$('#laym')) return;
  $('#laym').style.display = 'flex';
  if ($('#layq')) { $('#layq').value = ''; $('#layq').focus(); }
  layRenderModal();
}

(function initSavedLayouts() {
  layLoadStore();
  layUpdateBtn();
  const lb = $('#layb'), lp = $('#layp'), lm = $('#laym');
  if (lb) lb.onclick = layOpenMenu;
  if (lp) lp.addEventListener('click', e => {
    const del = e.target.closest('[data-ldel]');
    if (del) { e.stopPropagation(); layDelete(del.dataset.ldel); return; }
    const pk = e.target.closest('[data-lpick]');
    if (pk) {
      lp.style.display = 'none';
      const item = LAY_STORE.list.find(x => x.id === pk.dataset.lpick);
      if (item && item.id !== LAY_STORE.activeId) {
        if (LAY_STORE.autosave) laySaveActive(true);
        layApply(item, false);
      }
      return;
    }
    const la = e.target.closest('[data-la]');
    if (!la) return;
    const act0 = la.dataset.la;
    if (act0 === 'save') { laySaveActive(false); lp.style.display = 'none'; }
    else if (act0 === 'auto') {
      LAY_STORE.autosave = !LAY_STORE.autosave;
      if (LAY_STORE.autosave && LAY_DIRTY) laySaveActive(true);
      layPersistStore(); layUpdateBtn(); layRenderMenu();
      toast('Layout autosave ' + (LAY_STORE.autosave ? 'ON' : 'OFF'));
    }
    else if (act0 === 'copy') layMakeCopy();
    else if (act0 === 'ren') layRename();
    else if (act0 === 'dl') { lp.style.display = 'none'; layDownloadCsv(); }
    else if (act0 === 'new') layCreateNew();
    else if (act0 === 'open') layModalOpen();
  });
  if (lm) {
    lm.onclick = e => { if (e.target.id === 'laym') lm.style.display = 'none'; };
    if ($('#layx')) $('#layx').onclick = () => { lm.style.display = 'none'; };
    if ($('#layq')) $('#layq').oninput = layRenderModal;
    if ($('#laynewm')) $('#laynewm').onclick = layCreateNew;
    if ($('#layimpm')) $('#layimpm').onclick = layImportJson;
    if ($('#layls')) $('#layls').addEventListener('click', e => {
      const rn = e.target.closest('[data-lmren]');
      if (rn) { e.stopPropagation(); layRename(rn.dataset.lmren); return; }
      const ex = e.target.closest('[data-lmexp]');
      if (ex) { e.stopPropagation(); layExportJson(ex.dataset.lmexp); return; }
      const dl = e.target.closest('[data-lmdel]');
      if (dl) { e.stopPropagation(); layDelete(dl.dataset.lmdel); return; }
      const op = e.target.closest('[data-lmopen]');
      if (op) {
        const item = LAY_STORE.list.find(x => x.id === op.dataset.lmopen);
        lm.style.display = 'none';
        if (item) {
          if (item.id !== LAY_STORE.activeId && LAY_STORE.autosave) laySaveActive(true);
          layApply(item, false);
        }
      }
    });
  }
  document.addEventListener('click', e => {
    if (lp && lp.style.display === 'block' && !e.target.closest('#layp,#layb')) lp.style.display = 'none';
  }, true);
  document.addEventListener('keydown', e => {
    if ((e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey && e.code === 'KeyS') {
      if (typeof HOME_OPEN !== 'undefined' && HOME_OPEN) return;
      e.preventDefault();
      laySaveActive(false);
    }
  });
})();


