// Optional: If you use a custom domain (e.g. dreamx.com), put 'YourGitHubUsername/YourRepoName' below.
// When hosted on GitHub Pages (https://<user>.github.io/<repo>/), it auto-detects automatically!
const DX_GITHUB_REPO = 'DreamX-dev-ND/dreamx-downloads';
const DX_DESKTOP_ASSET = 'DreamX-Desktop-Setup.exe';
const DX_MOBILE_ASSET  = 'DreamX-Mobile.apk';

let DX_PWA_PROMPT = null;
window.addEventListener('beforeinstallprompt', e => {
  e.preventDefault();
  DX_PWA_PROMPT = e;
});

function dxDetectRepo() {
  if (DX_GITHUB_REPO && DX_GITHUB_REPO.includes('/')) return DX_GITHUB_REPO.trim().replace(/^\/+|\/+$/g, '');
  try {
    const h = location.hostname || '';
    if (h.endsWith('.github.io')) {
      const owner = h.replace(/\.github\.io$/i, '');
      const segs = (location.pathname || '/').split('/').filter(Boolean);
      const repo = segs.length ? segs[0] : (owner + '.github.io');
      if (owner && repo) return owner + '/' + repo;
    }
  } catch (e) {}
  return '';
}

function dxAppUrls() {
  const cfg = (window.DX_APP_LINKS && typeof window.DX_APP_LINKS === 'object') ? window.DX_APP_LINKS : {};
  const repo = (cfg.superchartsRepo && cfg.superchartsRepo.includes('/'))
    ? cfg.superchartsRepo.trim().replace(/^\/+|\/+$/g, '')
    : dxDetectRepo();
  const base = repo ? `https://github.com/${repo}/releases/latest/download/` : '';
  return {
    repo,
    desktop: (cfg.superchartsDesktopUrl || '').trim() || (base ? base + DX_DESKTOP_ASSET : ''),
    mobile: (cfg.superchartsMobileUrl || '').trim() || (base ? base + DX_MOBILE_ASSET : ''),
    releases: repo ? `https://github.com/${repo}/releases/latest` : ''
  };
}

function dxDownloadToolsApp(kind) {
  const cfg = (window.DX_APP_LINKS && typeof window.DX_APP_LINKS === 'object') ? window.DX_APP_LINKS : {};
  const isPc = kind === 'pc';
  const url = String(isPc ? (cfg.toolsDesktopUrl || '') : (cfg.toolsMobileUrl || '')).trim();
  const fname = String(isPc ? (cfg.toolsDesktopFile || 'DreamX-Trading-Tools-Setup.exe') : (cfg.toolsMobileFile || 'DreamX-Trading-Tools.apk')).trim();

  if (url) {
    dxTriggerFileDownload(url, fname);
    toast('Downloading DreamX Trading Tools (' + (isPc ? 'PC' : 'Mobile') + ')…');
    infoOpen('Downloading DreamX Trading Tools (' + (isPc ? 'Windows PC' : 'Android Mobile') + ')', `
      <p>Your download of <b>${esc(fname)}</b> has started automatically.</p>
      <ul>
        ${isPc
          ? '<li><b>Windows SmartScreen Tip:</b> If Windows shows <i>"Windows protected your PC"</i>, click <b>More info → Run anyway</b> once to install safely.</li>'
          : '<li><b>Android Install Tip:</b> Tap the downloaded <code>.apk</code> file and enable <b>Install unknown apps</b> for your browser once to finish installation.</li>'}
        <li><b>Download didn't start?</b> <a href="${esc(url)}" download="${esc(fname)}" target="_blank" rel="noopener noreferrer" style="color:#5c8aff;font-weight:700">Click here to download ${esc(fname)} ↓</a></li>
      </ul>
    `);
    return;
  }

  infoOpen('DreamX Trading Tools — ' + (isPc ? 'PC Download' : 'Mobile Download'), `
    <p>The direct download link for <b>DreamX Advanced Trading Tools (${isPc ? 'Windows PC' : 'Android Mobile'})</b> hasn't been linked yet.</p>
    <h4>Connect Your Installer in 30 Seconds</h4>
    <ul>
      <li>Upload your <b>${esc(fname)}</b> file to a free Public GitHub Repository under <b>Releases → Create a new release</b>.</li>
      <li>Right-click the uploaded file → <b>Copy link address</b>.</li>
      <li>Open <code>app-links.js</code> in your website repo and paste the URL into <code>${isPc ? 'toolsDesktopUrl' : 'toolsMobileUrl'}</code>, then commit!</li>
    </ul>
  `);
}

function dxIsIOS() {
  const ua = navigator.userAgent || '';
  return /iPhone|iPad|iPod/i.test(ua) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
}

function dxTriggerFileDownload(url, filename) {
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.rel = 'noopener noreferrer';
  document.body.appendChild(a);
  a.click();
  setTimeout(() => a.remove(), 400);
}

function dxTriggerPwaInstall() {
  if (!DX_PWA_PROMPT) return false;
  try {
    DX_PWA_PROMPT.prompt();
    DX_PWA_PROMPT.userChoice.then(ch => {
      if (ch && ch.outcome === 'accepted') toast('DreamX App installed!');
      DX_PWA_PROMPT = null;
    });
    return true;
  } catch (e) { return false; }
}

