// --- MOBILE DRAWING TOOLBAR DRAWER TOGGLE ---
(function initMobileToolsDrawer() {
  const btn = $('#mob-tbtn'), tb = $('#tools');
  if (!btn || !tb) return;
  const setOpen = v => {
    tb.classList.toggle('mob-open', !!v);
    btn.classList.toggle('on', !!v);
  };
  btn.onclick = e => {
    e.stopPropagation();
    setOpen(!tb.classList.contains('mob-open'));
  };
  document.addEventListener('click', e => {
    if (window.innerWidth <= 768 && tb.classList.contains('mob-open') && !e.target.closest('#tools,#fly,#mob-tbtn')) {
      setOpen(false);
    }
  }, true);
  // Auto-close mobile drawer right after picking a tool from flyout
  $('#fly').addEventListener('click', e => {
    if (window.innerWidth <= 768 && e.target.closest('[data-ft],[data-emo]')) setOpen(false);
  });
})();

// --- FULL MOBILE TOUCH GESTURE ENGINE FOR CHART CANVAS (#c) ---
(function initChartTouchEngine() {
  if (!cv) return;
  const TCH = {
    mode: '', // 'pan' | 'pinch' | 'ax' | 'tz' | 'draw' | 'lp'
    x0: 0, y0: 0, off0: 0, lo0: 0, hi0: 0, vy: 0,
    pDist: 0, pBw: 8, pOff: 5, pMidI: 0, pMidX: 0,
    lastTapT: 0, lastTapX: 0, lastTapY: 0,
    moved: false, lpTmr: null
  };

  const tPos = touch => {
    const r = cv.getBoundingClientRect();
    return [touch.clientX - r.left, touch.clientY - r.top];
  };
  const clearLp = () => {
    clearTimeout(TCH.lpTmr); TCH.lpTmr = null;
    if (TCH.mode === 'lp') { LPD = 0; $('#lpt').style.display = 'none'; }
  };

  cv.addEventListener('touchstart', e => {
    if (!D.length) return;
    ctxClose();
    clearLp();

    // 2-Finger Pinch-to-Zoom!
    if (e.touches.length === 2) {
      e.preventDefault();
      pan = null; ax = null; tz0 = null; drg = null;
      const [x1, y1] = tPos(e.touches[0]), [x2, y2] = tPos(e.touches[1]);
      TCH.mode = 'pinch';
      TCH.moved = true;
      TCH.pDist = Math.max(12, Math.hypot(x2 - x1, y2 - y1));
      TCH.pBw = bw;
      TCH.pOff = off;
      TCH.pMidX = (x1 + x2) / 2;
      TCH.pMidI = ix(TCH.pMidX);
      return;
    }

    if (e.touches.length !== 1) return;
    e.preventDefault();
    const t0 = e.touches[0];
    const [x, y] = tPos(t0);
    mx = x; my = y;
    TCH.x0 = x; TCH.y0 = y;
    TCH.moved = false;

    // Tap on Event icon
    const he = evAt(x, y);
    if (he) { showEv(he); TCH.mode = 'tap'; return; }

    // Tap on Plus button
    const px0 = PLL ? X0 + 2 : X1 - 20;
    if (CFG.plus && y >= 0 && y < PH && x >= px0 - 6 && x <= px0 + 24) {
      plusOpenAt(t0.clientX, t0.clientY, Math.max(1e-8, yp(y)), D.length ? D[D.length - 1].t : Date.now(), null);
      TCH.mode = 'tap';
      return;
    }

    // Touch drag on Time Axis -> zoom time
    if (y > H - BX) {
      TCH.mode = 'tz';
      tz0 = { x, bw };
      return;
    }

    // Touch drag on Sub-Pane Divider -> resize sub-pane vertically
    const hitTb = pnBorderAt(x, y, 11);
    if (hitTb) { pnStartResize(hitTb, y, false); TCH.mode = 'pnersz'; return; }
    const hitTrg = pnRightGripAt(x, y, 6);
    if (hitTrg) { pnStartResize(hitTrg, y, true); TCH.mode = 'pnersz'; return; }

    // Touch drag on Price Axis -> zoom price
    if (inAx(x, y)) {
      TCH.mode = 'ax';
      ax = { y, lo: LO, hi: HI };
      return;
    }

    if (y >= PH && y < H - BX) {
      const hitPn = pnHitId(x, y);
      if (hitPn) {
        PN_TCH_ID = hitPn;
        pnSyncVis();
        const nowP = performance.now();
        const isDblP = (nowP - TCH.lastTapT < 340) && Math.hypot(x - TCH.lastTapX, y - TCH.lastTapY) < 28;
        TCH.lastTapT = isDblP ? 0 : nowP;
        TCH.lastTapX = x; TCH.lastTapY = y;
        if (isDblP) ismOpen(hitPn, 'inputs');
      }
      TCH.mode = 'tap';
      return;
    }
    if (PN_TCH_ID) { PN_TCH_ID = ''; pnSyncVis(); }
    if (x < X0 || x > X1 || y > PH) { TCH.mode = ''; return; }

    // Bar Replay pick mode
    if (typeof RPL !== 'undefined' && RPL.active && RPL.mode === 'pick') {
      rplCutAt(Math.max(0, Math.min(D.length - 1, Math.round(ix(x)))));
      TCH.mode = 'tap';
      return;
    }

    // Active drawing tool or hitting a drawing handle/body
    if (tool !== 'cur') {
      TCH.mode = 'draw';
      mdTool(x, y);
      draw();
      return;
    }

    // Check TP/SL or limit order drag
    if (CFG.tr.po) {
      if (TRD.pos) for (const k of ['tp', 'sl']) if (TRD.pos[k] && Math.abs(y - py(TRD.pos[k])) < 14) { brd = { k }; TCH.mode = 'draw'; return; }
      if (Array.isArray(TRD.ord)) for (const o of TRD.ord) if (Math.abs(y - py(o.p)) < 14) { brd = { ord: o }; TCH.mode = 'draw'; return; }
    }

    // Check drawing selection / handle drag
    if (!LOCKD && sel >= 0 && DR[sel] && !DR[sel].lk && !DR[sel].hid && drVis(DR[sel])) {
      const hi = hitAnchor(DR[sel], x, y);
      if (hi >= 0) { drg = { i: sel, pt: hi, rectOrig: rectOrigOf(DR[sel]) }; TCH.mode = 'draw'; return; }
    }
    const hiDr = hit(x, y);
    if (hiDr >= 0) {
      selSet(hiDr);
      if (typeof dtUpd === 'function') dtUpd();
      if (!LOCKD && !DR[hiDr].lk && !(typeof isVpTool === 'function' && isVpTool(DR[hiDr].k))) {
        const ha = hitAnchor(DR[hiDr], x, y);
        drg = ha >= 0 ? { i: hiDr, pt: ha, rectOrig: rectOrigOf(DR[hiDr]) } : { i: hiDr, pt: -1, x0: x, y0: y, t0: xt(x), p0: yp(y), orig: DR[hiDr].pts.map(q => ({ t: q.t, p: q.p })) };
        TCH.mode = 'draw';
        draw();
        return;
      }
    } else if (selList().length) {
      selClear();
      if (typeof dtUpd === 'function') dtUpd();
    }

    // Default: 1-finger chart pan + long-press crosshair tooltip
    TCH.mode = 'pan';
    TCH.off0 = off; TCH.lo0 = LO; TCH.hi0 = HI; TCH.vy = 0;
    if (CFG.ltt) {
      TCH.lpTmr = setTimeout(() => {
        if (!TCH.moved && TCH.mode === 'pan') {
          TCH.mode = 'lp';
          LPD = 1;
          lpShow();
          draw();
        }
      }, 420);
    }
    draw();
  }, { passive: false });

  cv.addEventListener('touchmove', e => {
    if (!D.length) return;
    if (e.touches.length === 2) {
      e.preventDefault();
      clearLp();
      const [x1, y1] = tPos(e.touches[0]), [x2, y2] = tPos(e.touches[1]);
      const dNow = Math.max(12, Math.hypot(x2 - x1, y2 - y1));
      if (TCH.mode !== 'pinch') {
        TCH.mode = 'pinch';
        TCH.pDist = dNow; TCH.pBw = bw; TCH.pOff = off;
        TCH.pMidX = (x1 + x2) / 2; TCH.pMidI = ix(TCH.pMidX);
      }
      const ratio = dNow / TCH.pDist;
      const nb = Math.max(CFG.tm.xz ? 0.05 : 0.15, Math.min(60, TCH.pBw * ratio));
      bw = nb;
      // Anchor zoom around pinch midpoint
      const midX = (x1 + x2) / 2;
      const nLen = D.length;
      const newOff = TCH.pMidI - (nLen - 1) + (X1 - 30 - midX) / bw;
      off = Math.max(minLeftOff(CT_LAST_LEN || nLen), Math.min(maxRightOff(X1 - X0, bw), newOff));
      maybeBackfill();
      ui();
      draw();
      return;
    }

    if (e.touches.length !== 1) return;
    e.preventDefault();
    const [x, y] = tPos(e.touches[0]);
    mx = x; my = y;
    if (Math.hypot(x - TCH.x0, y - TCH.y0) > 7) {
      TCH.moved = true;
      clearTimeout(TCH.lpTmr); TCH.lpTmr = null;
    }

    if (TCH.mode === 'lp') {
      lpShow();
      draw();
      return;
    }
    if (TCH.mode === 'tz' && tz0) {
      zoomTo(tz0.bw * Math.exp((CFG.zdt == 'r' ? 1 : -1) * (x - tz0.x) / 140));
      draw();
      return;
    }
    if (TCH.mode === 'pnersz' && PN_RSZ) {
      pnApplyDrag(y);
      draw();
      return;
    }
    if (TCH.mode === 'ax' && ax) {
      const c = (ax.lo + ax.hi) / 2, hf = (ax.hi - ax.lo) / 2 * Math.exp((CFG.zdp == 'd' ? -1 : 1) * (y - ax.y) / 180);
      man = { lo: c - hf, hi: c + hf };
      ui(); draw();
      return;
    }
    if (TCH.mode === 'draw') {
      if (brd) {
        if (brd.ord) brd.ord.p = yp(y);
        else if (TRD.pos) {
          const p = TRD.pos, sg = Math.sign(p.q), np = yp(y);
          if (brd.k === 'tp' ? (np - p.e) * sg > 0 : (np - p.e) * sg < 0) p[brd.k] = np;
        }
      } else if (typeof drg !== 'undefined' && drg && DR[drg.i]) {
        const d0 = DR[drg.i];
        if (drg.pt >= 0) drMovePosHandle(d0, drg.pt, pt(x, y), drg);
        else {
          const dt = xt(x) - drg.t0, dp = yp(y) - drg.p0;
          d0.pts = drg.orig.map(q => ({ t: q.t + dt, p: Math.max(1e-8, q.p + dp) }));
        }
      } else if (tmp) {
        if (tmp.free) {
          const q = { t: xt(x), p: yp(y) }, l = tmp.pts[tmp.pts.length - 1];
          if (Math.hypot(tx(q.t) - tx(l.t), py(q.p) - py(l.p)) > 2) tmp.pts.push(q);
        } else {
          tmp.pts[tmp.pts.length - 1] = pt(x, y);
        }
      }
      draw();
      return;
    }
    if (TCH.mode === 'pan') {
      off = TCH.off0 - (x - TCH.x0) / bw;
      off = Math.max(minLeftOff(CT_LAST_LEN || D.length), Math.min(maxRightOff(X1 - X0, bw), off));
      if (TCH.vy || Math.abs(y - TCH.y0) > 10) {
        TCH.vy = 1;
        const sh = (y - TCH.y0) / (PH - 2 * PT) * (TCH.hi0 - TCH.lo0);
        man = { lo: TCH.lo0 + sh, hi: TCH.hi0 + sh };
        ui();
      }
      maybeBackfill();
      draw();
    }
  }, { passive: false });

  cv.addEventListener('touchend', e => {
    clearLp();
    if (e.touches.length === 1 && TCH.mode === 'pinch') {
      // Transition smoothly from 2 fingers back to 1-finger pan
      const [x, y] = tPos(e.touches[0]);
      TCH.mode = 'pan'; TCH.x0 = x; TCH.y0 = y;
      TCH.off0 = off; TCH.lo0 = LO; TCH.hi0 = HI; TCH.vy = 0;
      return;
    }
    if (e.touches.length > 0) return;

    // Finish active drag/drawing
    if (brd) { brd = null; svT(); }
    if (typeof drg !== 'undefined' && drg) { drg = null; sv(); if (typeof dtUpd === 'function') dtUpd(); if (typeof objRender === 'function') objRender(); }
    if (tmp) muTool();
    if (PN_RSZ) { PN_RSZ = null; svC(); } tz0 = null; ax = null;

    // Double-tap detection on quick tap
    if (!TCH.moved && (TCH.mode === 'pan' || TCH.mode === 'ax' || TCH.mode === 'tz' || TCH.mode === 'draw')) {
      const now = performance.now();
      const isDbl = (now - TCH.lastTapT < 340) && Math.hypot(TCH.x0 - TCH.lastTapX, TCH.y0 - TCH.lastTapY) < 26;
      TCH.lastTapT = isDbl ? 0 : now;
      TCH.lastTapX = TCH.x0; TCH.lastTapY = TCH.y0;
      if (isDbl) {
        if (inAx(TCH.x0, TCH.y0)) { man = null; ui(); }
        else if (TCH.y0 > H - BX) { bw = 8; off = 5; }
        else {
          const i = hit(TCH.x0, TCH.y0);
          if (i >= 0) {
            selSet(i);
            if (TX_AUTO_OPEN[DR[i].k]) { txiOpen(i, false); }
            else if (typeof dsmOpen === 'function' && typeof isCfgTool === 'function' && isCfgTool(DR[i].k)) {
              dsmOpen(i, 'style');
            }
          } else if (tool === 'cur' && typeof ctHitTest === 'function' && ctHitTest(TCH.x0, TCH.y0, CT_LAST_G)) {
            openChartSettings('s');
          }
        }
      }
    }
    TCH.mode = '';
    mx = my = -1;
    draw();
  }, { passive: false });

  cv.addEventListener('touchcancel', () => {
    clearLp(); brd = null; drg = null; tz0 = null; ax = null; TCH.mode = ''; mx = my = -1; draw();
  });
})();


// =========================================================================
// v46: GOOGLE + EMAIL/PASSWORD SIGN UP & SIGN IN + OPTIONAL CLOUD SYNC
// Powered by Firebase Auth & Firestore (configured in firebase-config.js)
// =========================================================================
const DX_AUTH = {
  ready: false,
  configured: false,
  loading: null,
  mode: 'in', // 'in' | 'up'
  app: null,
  auth: null,
  db: null,
  mod: null,
  syncTmr: null
};

function authCfgValid() {
  const c = window.DX_FIREBASE_CONFIG;
  return !!(c && typeof c === 'object' && String(c.apiKey || '').trim().length > 10 && String(c.projectId || '').trim().length > 1);
}

function authSyncHomeBtn() {
  const b = $('#hm-auth-btn');
  if (!b) return;
  if (USER_PROF.signedIn) {
    const av = USER_PROF.photo
      ? `<img src="${esc(USER_PROF.photo)}" alt="" class="hm-au-img" referrerpolicy="no-referrer">`
      : `<span class="hm-au-ini">${esc(userInitial())}</span>`;
    const shortNm = String(USER_PROF.name || USER_PROF.email || 'Account').split('@')[0].slice(0, 14);
    b.innerHTML = `${av}<span>${esc(shortNm)}</span>`;
    b.classList.add('signed');
    b.title = (USER_PROF.name || '') + (USER_PROF.email ? ' (' + USER_PROF.email + ')' : '');
  } else {
    b.textContent = 'Sign In';
    b.classList.remove('signed');
    b.title = 'Sign In or Create Free Account';
  }
}

function authSetMsg(text, kind) {
  const el = $('#au-msg');
  if (!el) return;
  if (!text) { el.style.display = 'none'; el.textContent = ''; el.className = 'au-msg'; return; }
  el.textContent = text;
  el.className = 'au-msg ' + (kind || 'err');
  el.style.display = 'block';
}

function authSetBusy(busy) {
  ['#au-google', '#au-sub', '#au-forgot'].forEach(sel0 => {
    const el = $(sel0);
    if (el) el.disabled = !!busy;
  });
}

function authFriendlyErr(err) {
  const code = (err && err.code) || '';
  const map = {
    'auth/invalid-email': 'Please enter a valid email address.',
    'auth/user-not-found': 'No account found with this email. Switch to Create Account.',
    'auth/wrong-password': 'Incorrect password. Try again or click Forgot password.',
    'auth/invalid-credential': 'Invalid email or password.',
    'auth/email-already-in-use': 'This email already has an account. Switch to Sign In.',
    'auth/weak-password': 'Password must be at least 6 characters.',
    'auth/popup-closed-by-user': 'Google sign-in popup was closed.',
    'auth/cancelled-popup-request': 'Sign-in cancelled.',
    'auth/unauthorized-domain': 'This website domain is not added in Firebase Console → Authentication → Settings → Authorized domains.',
    'auth/operation-not-allowed': 'Enable Google & Email/Password in Firebase Console → Authentication → Sign-in method.',
    'auth/network-request-failed': 'Network error — check your internet connection.',
    'auth/too-many-requests': 'Too many attempts. Please wait a minute and try again.'
  };
  return map[code] || (err && err.message ? String(err.message).replace(/^Firebase:\s*/i, '') : 'Authentication failed.');
}

async function authInitFirebase() {
  DX_AUTH.configured = authCfgValid();
  if (!DX_AUTH.configured) return false;
  if (DX_AUTH.ready) return true;
  if (DX_AUTH.loading) return DX_AUTH.loading;

  DX_AUTH.loading = (async () => {
    try {
      const base = 'https://www.gstatic.com/firebasejs/11.0.2/';
      const [appMod, authMod, fsMod, rtdbMod] = await Promise.all([
        import(base + 'firebase-app.js'),
        import(base + 'firebase-auth.js'),
        import(base + 'firebase-firestore.js').catch(() => null),
        import(base + 'firebase-database.js').catch(() => null)
      ]);
      const app = appMod.getApps().length ? appMod.getApp() : appMod.initializeApp(window.DX_FIREBASE_CONFIG);
      const auth = authMod.getAuth(app);
      const db = fsMod ? fsMod.getFirestore(app) : null;
      let rtdb = null;
      if (rtdbMod) {
        try {
          const dUrl = String((window.DX_FIREBASE_CONFIG && window.DX_FIREBASE_CONFIG.databaseURL) || '').trim();
          rtdb = dUrl ? rtdbMod.getDatabase(app, dUrl) : rtdbMod.getDatabase(app);
        } catch (e) { rtdb = null; }
      }
      DX_AUTH.app = app;
      DX_AUTH.auth = auth;
      DX_AUTH.db = db;
      DX_AUTH.rtdb = rtdb;
      DX_AUTH.mod = { authMod, fsMod, rtdbMod };
      DX_AUTH.ready = true;
      if (typeof anInit === 'function') anInit();

      authMod.onAuthStateChanged(auth, user => {
        if (user) {
          const prov = (user.providerData && user.providerData[0] && user.providerData[0].providerId) || 'password';
          USER_PROF = {
            name: user.displayName || (user.email ? user.email.split('@')[0] : 'Trader'),
            email: user.email || '',
            photo: user.photoURL || '',
            uid: user.uid,
            provider: prov,
            signedIn: true
          };
          svUserProf();
          profUpdAvatar();
          if ($('#profm') && $('#profm').style.display === 'block') profRender();
          authCloudPull();
          if (typeof dxRunPendingAfterAuth === 'function') dxRunPendingAfterAuth();
          if (typeof anOnAuthChange === 'function') anOnAuthChange();
        } else if (USER_PROF.uid) {
          USER_PROF = { name: 'Guest', email: '', photo: '', uid: '', provider: '', signedIn: false };
          svUserProf();
          profUpdAvatar();
          if ($('#profm') && $('#profm').style.display === 'block') profRender();
          if (typeof anOnAuthChange === 'function') anOnAuthChange();
        } else {
          if (typeof anOnAuthChange === 'function') anOnAuthChange();
        }
      });
      return true;
    } catch (e) {
      DX_AUTH.loading = null;
      return false;
    }
  })();
  return DX_AUTH.loading;
}

function authCloudSnapshot() {
  // Never upload user's private API keys (tdk, oandaKey, fhk)
  const layCopy = (typeof LAY_STORE !== 'undefined' && LAY_STORE)
    ? JSON.parse(JSON.stringify(LAY_STORE))
    : null;
  if (layCopy && Array.isArray(layCopy.list)) {
    layCopy.list.forEach(item => {
      if (item && item.CFG) { delete item.CFG.tdk; delete item.CFG.oandaKey; delete item.CFG.fhk; }
    });
  }
  return {
    updatedAt: Date.now(),
    symfav: Array.isArray(SYMFAV) ? SYMFAV.slice(0, 100) : [],
    symhist: Array.isArray(SYM_HIST) ? SYM_HIST.slice(0, 60) : [],
    indfav: Array.isArray(IND_FAV) ? IND_FAV.slice(0, 80) : [],
    dark: typeof DARK_ON !== 'undefined' ? !!DARK_ON : true,
    lang: typeof CUR_LANG !== 'undefined' ? CUR_LANG : 'en',
    layouts: layCopy
  };
}

async function authCloudPush(notifyUser) {
  if (!DX_AUTH.ready || !DX_AUTH.db || !DX_AUTH.mod || !DX_AUTH.mod.fsMod || !USER_PROF.uid) return;
  try {
    const { doc, setDoc } = DX_AUTH.mod.fsMod;
    await setDoc(doc(DX_AUTH.db, 'users', USER_PROF.uid), authCloudSnapshot(), { merge: true });
    if (notifyUser) toast('Workspace synced to cloud ✓');
  } catch (e) {
    if (notifyUser) toast('Cloud sync skipped (enable Firestore in Firebase Console)');
  }
}

async function authCloudPull() {
  if (!DX_AUTH.ready || !DX_AUTH.db || !DX_AUTH.mod || !DX_AUTH.mod.fsMod || !USER_PROF.uid) return;
  try {
    const { doc, getDoc } = DX_AUTH.mod.fsMod;
    const snap = await getDoc(doc(DX_AUTH.db, 'users', USER_PROF.uid));
    if (!snap.exists()) { authCloudPush(false); return; }
    const d = snap.data() || {};
    if (Array.isArray(d.symfav) && d.symfav.length) { SYMFAV = d.symfav; svSymFav(); }
    if (Array.isArray(d.symhist) && d.symhist.length) { SYM_HIST = d.symhist; svSymHist(); }
    if (Array.isArray(d.indfav) && d.indfav.length) { IND_FAV = d.indfav; svIndFav(); }
    if (typeof d.dark === 'boolean' && typeof setDarkTheme === 'function' && d.dark !== DARK_ON) {
      setDarkTheme(d.dark, true);
    }
    if (d.layouts && Array.isArray(d.layouts.list) && d.layouts.list.length && typeof LAY_STORE !== 'undefined') {
      LAY_STORE.list = d.layouts.list;
      if (d.layouts.activeId) LAY_STORE.activeId = d.layouts.activeId;
      if (typeof layPersistStore === 'function') layPersistStore();
      if (typeof layUpdateBtn === 'function') layUpdateBtn();
    }
  } catch (e) {}
}

async function authUpdateName(newName) {
  if (!DX_AUTH.ready || !DX_AUTH.auth || !DX_AUTH.auth.currentUser) return;
  try {
    await DX_AUTH.mod.authMod.updateProfile(DX_AUTH.auth.currentUser, { displayName: newName });
  } catch (e) {}
}

async function authSignOut() {
  try {
    if (DX_AUTH.ready && DX_AUTH.auth && DX_AUTH.mod) {
      await DX_AUTH.mod.authMod.signOut(DX_AUTH.auth);
    }
  } catch (e) {}
  USER_PROF = { name: 'Guest', email: '', photo: '', uid: '', provider: '', signedIn: false };
  svUserProf();
  profUpdAvatar();
  if ($('#profm') && $('#profm').style.display === 'block') profRender();
  let switched = false;
  if (typeof isGatedCt === 'function' && isGatedCt(CFG.ct)) { CFG.ct = 'candles'; ctInvalidate(); svC(); ctBtnUpd(); switched = true; }
  if (typeof isGatedTf === 'function' && isGatedTf(tf)) { tf = '3m'; try { localStorage['dx:tf'] = tf; } catch (e) {} rtb(); go(); switched = false; }
  if (switched) draw();
  toast('Signed out');
}

function authSwitchMode(mode) {
  DX_AUTH.mode = mode === 'up' ? 'up' : 'in';
  const isUp = DX_AUTH.mode === 'up';
  document.querySelectorAll('#authm [data-autab]').forEach(b => b.classList.toggle('on', b.dataset.autab === DX_AUTH.mode));
  const nw = $('#au-name-wrap'), fw = $('#au-forgot-wrap'), sub = $('#au-sub'), swt = $('#au-sw-txt'), swb = $('#au-sw-btn'), pw = $('#au-pass');
  if (nw) nw.style.display = isUp ? 'block' : 'none';
  if (fw) fw.style.display = isUp ? 'none' : 'flex';
  if (sub) sub.textContent = isUp ? 'Create Account' : 'Sign In';
  if (swt) swt.textContent = isUp ? 'Already have an account?' : 'New to DreamX?';
  if (swb) swb.textContent = isUp ? 'Sign in' : 'Create free account';
  if (pw) pw.autocomplete = isUp ? 'new-password' : 'current-password';
  authSetMsg('');
}

function authOpen(mode) {
  cm();
  authSwitchMode(mode || 'in');
  const note = $('#au-setup-note');
  if (note) note.style.display = authCfgValid() ? 'none' : 'block';
  const m = $('#authm');
  if (m) m.style.display = 'flex';
  const em = $('#au-email');
  if (em) setTimeout(() => em.focus(), 40);
  authInitFirebase();
}

(function initAuthModal() {
  const m = $('#authm');
  if (!m) return;
  const close = () => { m.style.display = 'none'; authSetMsg(''); };
  $('#authx').onclick = close;
  m.onclick = e => { if (e.target === m) close(); };
  document.querySelectorAll('#authm [data-autab]').forEach(b => b.onclick = () => authSwitchMode(b.dataset.autab));
  $('#au-sw-btn').onclick = () => authSwitchMode(DX_AUTH.mode === 'in' ? 'up' : 'in');
  $('#au-eye').onclick = () => {
    const p = $('#au-pass');
    if (p) p.type = p.type === 'password' ? 'text' : 'password';
  };

  $('#au-google').onclick = async () => {
    if (!authCfgValid()) {
      authSetMsg('Paste your Firebase config into firebase-config.js first (see setup guide).', 'err');
      return;
    }
    authSetMsg('');
    authSetBusy(true);
    try {
      const ok = await authInitFirebase();
      if (!ok) throw new Error('Could not load Firebase Auth SDK.');
      const { GoogleAuthProvider, signInWithPopup, signInWithRedirect } = DX_AUTH.mod.authMod;
      const prov = new GoogleAuthProvider();
      prov.setCustomParameters({ prompt: 'select_account' });
      try {
        const res = await signInWithPopup(DX_AUTH.auth, prov);
        close();
        toast('Welcome, ' + (res.user.displayName || res.user.email || 'Trader') + '!');
      } catch (e) {
        if (e && (e.code === 'auth/popup-blocked' || e.code === 'auth/operation-not-supported-in-this-environment')) {
          await signInWithRedirect(DX_AUTH.auth, prov);
          return;
        }
        throw e;
      }
    } catch (e) {
      authSetMsg(authFriendlyErr(e), 'err');
    } finally {
      authSetBusy(false);
    }
  };

  $('#au-form').onsubmit = async e => {
    e.preventDefault();
    const email = ($('#au-email').value || '').trim();
    const pass = $('#au-pass').value || '';
    const name = ($('#au-name').value || '').trim();
    if (!email || !pass) { authSetMsg('Enter your email and password.', 'err'); return; }
    if (DX_AUTH.mode === 'up' && pass.length < 6) { authSetMsg('Password must be at least 6 characters.', 'err'); return; }

    if (!authCfgValid()) {
      authSetMsg('Paste your Firebase config into firebase-config.js first (see setup guide).', 'err');
      return;
    }
    authSetMsg('');
    authSetBusy(true);
    try {
      const ok = await authInitFirebase();
      if (!ok) throw new Error('Could not load Firebase Auth SDK.');
      const { createUserWithEmailAndPassword, signInWithEmailAndPassword, updateProfile } = DX_AUTH.mod.authMod;
      if (DX_AUTH.mode === 'up') {
        const cred = await createUserWithEmailAndPassword(DX_AUTH.auth, email, pass);
        if (name) {
          try { await updateProfile(cred.user, { displayName: name }); } catch (x) {}
          USER_PROF.name = name; svUserProf(); profUpdAvatar();
        }
        close();
        toast('Account created! Welcome to DreamX.');
      } else {
        const cred = await signInWithEmailAndPassword(DX_AUTH.auth, email, pass);
        close();
        toast('Signed in as ' + (cred.user.displayName || cred.user.email));
      }
    } catch (err) {
      authSetMsg(authFriendlyErr(err), 'err');
    } finally {
      authSetBusy(false);
    }
  };

  $('#au-forgot').onclick = async () => {
    const email = ($('#au-email').value || '').trim();
    if (!email) { authSetMsg('Enter your email above first, then click Forgot password.', 'err'); $('#au-email').focus(); return; }
    if (!authCfgValid()) { authSetMsg('Configure firebase-config.js first to send password resets.', 'err'); return; }
    authSetBusy(true);
    try {
      const ok = await authInitFirebase();
      if (!ok) throw new Error('Could not load Firebase Auth SDK.');
      await DX_AUTH.mod.authMod.sendPasswordResetEmail(DX_AUTH.auth, email);
      authSetMsg('Password reset link sent to ' + email + '. Check your inbox/spam.', 'ok');
    } catch (err) {
      authSetMsg(authFriendlyErr(err), 'err');
    } finally {
      authSetBusy(false);
    }
  };

  // Boot Firebase silently if configured
  authInitFirebase();
  authSyncHomeBtn();
})();


// =========================================================================
// v47: PRO FEATURE AUTH GATE (Seconds, Ticks, Ranges, SVP, Footprint, TPO)
// =========================================================================
let DX_PENDING_ACTION = null;

function isGatedTf(tfId) {
  const I = ti(tfId);
  return !!(I && (I.u === 's' || I.u === 't' || I.u === 'R'));
}

function isGatedCt(ctId) {
  return ctId === 'svp' || ctId === 'svp_only' || ctId === 'footprint' || ctId === 'tpo';
}

function dxOpenGateModal(title, desc, onSuccess) {
  DX_PENDING_ACTION = typeof onSuccess === 'function' ? onSuccess : null;
  cm();
  const tEl = $('#gt-title'), dEl = $('#gt-desc'), m = $('#gatem');
  if (tEl) tEl.textContent = title || 'Unlock Pro Feature';
  if (dEl) dEl.textContent = desc || 'Sign in or create a free DreamX account to unlock institutional orderflow tools & sub-minute timeframes — 100% free.';
  if (m) m.style.display = 'flex';
}

function dxCheckTfGate(tfId, onSuccess) {
  if (!isGatedTf(tfId)) return true;
  if (USER_PROF && USER_PROF.signedIn) return true;
  const I = ti(tfId);
  const kindNm = I.u === 's' ? 'Second Timeframes (' + tfS(tfId) + ')'
               : I.u === 't' ? 'Tick Timeframes (' + tfS(tfId) + ')'
               : 'Range Timeframes (' + tfS(tfId) + ')';
  dxOpenGateModal(
    'Unlock ' + kindNm,
    'Create a free DreamX account or continue with Google to unlock Seconds, Ticks & Range charts with deep tick history.',
    onSuccess
  );
  return false;
}

function dxCheckCtGate(ctId, onSuccess) {
  if (!isGatedCt(ctId)) return true;
  if (USER_PROF && USER_PROF.signedIn) return true;
  const labels = {
    svp: ['Unlock Session Volume Profile (SVP)', 'Sign in for free to view institutional Session Volume Profiles (POC, VAH, VAL) directly on your charts.'],
    svp_only: ['Unlock Session Volume Profile (SVP)', 'Sign in for free to view institutional Session Volume Profiles (POC, VAH, VAL) directly on your charts.'],
    footprint: ['Unlock Volume Footprint + Summary Table', 'Sign in for free to access Buy/Sell Volume Footprints, Stacked Imbalances, Unfinished Auctions & full Delta Tables.'],
    tpo: ['Unlock TPO Market Profile', 'Sign in for free to analyze TradingView-style TPO profiles (A–Z, a–z half-hour blocks) with Split/Expand view.']
  };
  const info = labels[ctId] || ['Unlock Pro Chart Mode', 'Create a free account or sign in with Google to use this advanced chart mode.'];
  dxOpenGateModal(info[0], info[1], onSuccess);
  return false;
}

function dxRunPendingAfterAuth() {
  if (typeof DX_PENDING_ACTION === 'function' && USER_PROF && USER_PROF.signedIn) {
    const fn = DX_PENDING_ACTION;
    DX_PENDING_ACTION = null;
    setTimeout(() => { try { fn(); } catch (e) {} }, 120);
  }
}

(function initGateModal() {
  const m = $('#gatem');
  if (!m) return;
  const close = () => { m.style.display = 'none'; };
  $('#gatex').onclick = close;
  m.onclick = e => { if (e.target === m) close(); };
  $('#gt-signup').onclick = () => { close(); authOpen('up'); };
  $('#gt-signin').onclick = () => { close(); authOpen('in'); };
  $('#gt-google').onclick = () => {
    close();
    authOpen('in');
    setTimeout(() => {
      const gb = $('#au-google');
      if (gb && authCfgValid()) gb.click();
    }, 60);
  };

  if (!(USER_PROF && USER_PROF.signedIn)) {
    if (isGatedTf(tf)) { tf = '3m'; try { localStorage['dx:tf'] = tf; } catch (e) {} }
    if (isGatedCt(CFG.ct)) { CFG.ct = 'candles'; try { localStorage['dx:cfg'] = JSON.stringify(CFG); } catch (e) {} }
  }
})();

// =========================================================================
// v61: REAL-TIME ACCURATE LIVE USERS + TOTAL USERS BADGE & ADMIN DASHBOARD
// Powered by Firebase Realtime Database (onDisconnect presence + transactions)
// =========================================================================
const DX_AN = {
  inited: false,
  connected: false,
  hasDbUrl: false,
  err: '',
  vid: '',
  tabId: '',
  userKey: '',
  joinedAt: Date.now(),
  liveCount: 1,
  totalUsers: 0,
  todayUsers: 0,
  regUsers: 0,
  peakToday: 0,
  liveMap: {},
  adminLiveMap: {},
  adminUsersMap: {},
  dailyCounts: {},
  unsubConn: null,
  unsubLive: null,
  unsubCnt: null,
  unsubAdmLive: null,
  unsubAdmUsers: null,
  hbTmr: null,
  pingTmr: null,
  modalOpen: false
};

function anGetVid() {
  if (DX_AN.vid) return DX_AN.vid;
  let v = '';
  try { v = localStorage['dx:vid'] || ''; } catch (e) {}
  if (!v || !/^[a-zA-Z0-9_-]{8,40}$/.test(v)) {
    v = 'v_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 10);
    try { localStorage['dx:vid'] = v; } catch (e) {}
  }
  DX_AN.vid = v;
  return v;
}

function anGetTabId() {
  if (DX_AN.tabId) return DX_AN.tabId;
  DX_AN.tabId = 't_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
  return DX_AN.tabId;
}

function anCurrentKey() {
  if (USER_PROF && USER_PROF.signedIn && USER_PROF.uid) {
    return 'u_' + String(USER_PROF.uid).replace(/[^a-zA-Z0-9_-]/g, '');
  }
  return 'g_' + anGetVid();
}

function anDayKey(tsOpt) {
  // Sri Lanka / UTC+5:30 consistent daily bucket so daily visitors match local day cleanly
  const d = new Date((tsOpt || Date.now()) + 19800000);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const da = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${da}`;
}

function anDevType() {
  const ua = navigator.userAgent || '';
  if (/Mobi|Android|iPhone|iPad|iPod/i.test(ua) || window.innerWidth <= 768) return 'mob';
  return 'pc';
}

function anAdminList() {
  const cfg = window.DX_FIREBASE_CONFIG || {};
  const list = [];
  if (Array.isArray(cfg.adminEmails)) cfg.adminEmails.forEach(e => { if (e) list.push(String(e).trim().toLowerCase()); });
  if (cfg.adminEmail) list.push(String(cfg.adminEmail).trim().toLowerCase());
  return list;
}

function anIsAdmin() {
  if (!(USER_PROF && USER_PROF.signedIn && USER_PROF.email)) return false;
  const em = String(USER_PROF.email).trim().toLowerCase();
  if (!em) return false;
  return anAdminList().includes(em);
}

function anFmtNum(n) {
  n = Math.max(0, Math.floor(+n || 0));
  return n.toLocaleString('en-US');
}

function anFmtCompact(n) {
  n = Math.max(0, Math.floor(+n || 0));
  if (n >= 1e6) return (n / 1e6).toFixed(1).replace(/\.0$/, '') + 'M';
  if (n >= 1e4) return (n / 1e3).toFixed(1).replace(/\.0$/, '') + 'K';
  return n.toLocaleString('en-US');
}

function anFmtDur(ms) {
  const s = Math.max(0, Math.floor((ms || 0) / 1000));
  if (s < 60) return s + 's';
  const m = Math.floor(s / 60);
  if (m < 60) return m + 'm ' + (s % 60) + 's';
  const h = Math.floor(m / 60);
  return h + 'h ' + (m % 60) + 'm';
}

function anFmtAgo(ts) {
  if (!ts) return '—';
  const s = Math.max(0, Math.floor((Date.now() - (+ts || 0)) / 1000));
  if (s < 15) return 'Just now';
  if (s < 60) return s + 's ago';
  if (s < 3600) return Math.floor(s / 60) + 'm ago';
  if (s < 86400) return Math.floor(s / 3600) + 'h ago';
  return Math.floor(s / 86400) + 'd ago';
}

function anEnsureTopBadge() {
  const top = $('#top');
  if (!top) return;
  if (!$('#dx-live-pill')) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.id = 'dx-live-pill';
    btn.className = 'dx-live-pill';
    btn.innerHTML = '<span class="dx-lp-dot"></span><span id="dx-lp-txt">1 Live</span>';
    btn.onclick = () => anBadgeClick();
    const pill = $('#pill');
    if (pill && pill.parentNode === top) top.insertBefore(btn, pill);
    else top.appendChild(btn);
  }
}

function anUpdateBadges() {
  anEnsureTopBadge();
  const lc = Math.max(1, DX_AN.liveCount || 1);
  const tu = Math.max(0, DX_AN.totalUsers || 0, DX_AN.todayUsers || 0, DX_AN.regUsers || 0, lc);
  const fullTxt = tu > 0 ? `${anFmtNum(lc)} Live · ${anFmtNum(tu)} Users` : `${anFmtNum(lc)} Live`;
  const compactTxt = tu > 0 ? `${anFmtNum(lc)} Live · ${anFmtCompact(tu)}` : `${anFmtNum(lc)} Live`;
  const isAdm = anIsAdmin();
  const ttl = isAdm
    ? `${fullTxt} — Click to open Admin Analytics Dashboard (Alt+Shift+A)`
    : `${fullTxt} — Real-time active traders on DreamX Trading Hub`;

  const topTxt = $('#dx-lp-txt'), topBtn = $('#dx-live-pill');
  if (topTxt) topTxt.textContent = (window.innerWidth <= 680 ? compactTxt : fullTxt);
  if (topBtn) {
    topBtn.title = ttl;
    topBtn.classList.toggle('is-adm', isAdm);
    topBtn.classList.toggle('conn', DX_AN.connected);
  }
  const hmTxt = $('#hm-lp-txt'), hmBtn = $('#hm-live-pill');
  if (hmTxt) hmTxt.textContent = fullTxt;
  if (hmBtn) {
    hmBtn.title = ttl;
    hmBtn.classList.toggle('is-adm', isAdm);
    hmBtn.classList.toggle('conn', DX_AN.connected);
  }
  if ($('#profm') && $('#profm').style.display === 'block') profRender();
  if (DX_AN.modalOpen) anRenderDashboard();
}

function anBadgeClick() {
  if (anIsAdmin()) {
    anOpenDashboard();
    return;
  }
  const lc = Math.max(1, DX_AN.liveCount || 1);
  const tu = Math.max(0, DX_AN.totalUsers || 0, DX_AN.todayUsers || 0, DX_AN.regUsers || 0, lc);
  toast(`● ${anFmtNum(lc)} trader${lc === 1 ? '' : 's'} online now` + (tu > 0 ? ` · ${anFmtNum(tu)} total users` : ''));
}

function anTabPayload(includePrivate) {
  const pg = (typeof HOME_OPEN !== 'undefined' && HOME_OPEN) ? 'home' : 'chart';
  const dev = anDevType();
  const isReg = !!(USER_PROF && USER_PROF.signedIn && USER_PROF.uid);
  const base = {
    ts: Date.now(),
    pg,
    sym: sym || 'BTCUSDT',
    dev,
    reg: isReg ? 1 : 0
  };
  if (!includePrivate) return base;
  return Object.assign({}, base, {
    tf: tf || '3m',
    joinedAt: DX_AN.joinedAt,
    name: isReg ? (USER_PROF.name || 'Trader') : 'Guest',
    email: isReg ? (USER_PROF.email || '') : '',
    uid: isReg ? (USER_PROF.uid || '') : ''
  });
}

function anCountValidLive(valObj) {
  const now = Date.now(), maxStale = 6 * 60 * 1000;
  const validUsers = {};
  if (!valObj || typeof valObj !== 'object') return { count: 0, users: {} };
  for (const uk of Object.keys(valObj)) {
    const tabs = valObj[uk];
    if (!tabs || typeof tabs !== 'object') continue;
    let best = null, tabCount = 0;
    for (const tk of Object.keys(tabs)) {
      const row = tabs[tk];
      if (!row || typeof row !== 'object') continue;
      const ts = +row.ts || 0;
      if (ts > 0 && Math.abs(now - ts) > maxStale) continue;
      tabCount++;
      if (!best || (+row.ts || 0) >= (+best.ts || 0)) best = row;
    }
    if (best && tabCount > 0) {
      validUsers[uk] = Object.assign({}, best, { tabs: tabCount, key: uk });
    }
  }
  return { count: Object.keys(validUsers).length, users: validUsers };
}

async function anWritePresence(isHeartbeat) {
  if (!DX_AUTH.ready || !DX_AUTH.rtdb || !DX_AUTH.mod || !DX_AUTH.mod.rtdbMod) return;
  const { ref, set, update, remove, onDisconnect, serverTimestamp } = DX_AUTH.mod.rtdbMod;
  const rtdb = DX_AUTH.rtdb;
  const newKey = anCurrentKey();
  const tabId = anGetTabId();

  // If user just signed in or signed out, clean up old presence key so never double-counted
  if (DX_AN.userKey && DX_AN.userKey !== newKey) {
    const oldK = DX_AN.userKey;
    try { await remove(ref(rtdb, `dx_stats/live/${oldK}/${tabId}`)); } catch (e) {}
    try { await remove(ref(rtdb, `dx_stats/admin_live/${oldK}/${tabId}`)); } catch (e) {}
  }
  DX_AN.userKey = newKey;

  const liveRef = ref(rtdb, `dx_stats/live/${newKey}/${tabId}`);
  const admRef  = ref(rtdb, `dx_stats/admin_live/${newKey}/${tabId}`);
  const pubPay  = anTabPayload(false); pubPay.ts = serverTimestamp();
  const admPay  = anTabPayload(true);  admPay.ts = serverTimestamp();

  try {
    if (!isHeartbeat) {
      await onDisconnect(liveRef).remove();
      await onDisconnect(admRef).remove();
      await set(liveRef, pubPay);
      await set(admRef, admPay);
    } else {
      await update(liveRef, pubPay);
      await update(admRef, admPay);
    }
    DX_AN.err = '';
  } catch (e) {
    DX_AN.err = (e && e.message) ? String(e.message) : 'Realtime Database write error';
  }
}

async function anIncCounter(path) {
  const { ref, set, runTransaction, increment } = DX_AUTH.mod.rtdbMod;
  const r = ref(DX_AUTH.rtdb, path);
  if (typeof increment === 'function') {
    await set(r, increment(1));
  } else {
    await runTransaction(r, cur => (+cur || 0) + 1);
  }
}

async function anRecordUniqueVisit() {
  if (!DX_AUTH.ready || !DX_AUTH.rtdb || !DX_AUTH.mod || !DX_AUTH.mod.rtdbMod) return;
  if (DX_AN._visBusy) return;
  DX_AN._visBusy = true;
  try {
    const { ref, get, set, runTransaction, serverTimestamp } = DX_AUTH.mod.rtdbMod;
    const rtdb = DX_AUTH.rtdb;
    const vidKey = 'g_' + anGetVid();
    const day = anDayKey();

    // 1. All-time unique visitor (atomic server-side increment, never skipped)
    let countedEver = false;
    try { countedEver = localStorage['dx:an_ever'] === '2'; } catch (e) {}
    if (!countedEver) {
      try {
        const seenRef = ref(rtdb, `dx_stats/seen/${vidKey}`);
        const snap = await get(seenRef);
        if (!snap.exists()) {
          await set(seenRef, { firstSeen: serverTimestamp(), dev: anDevType() });
          await anIncCounter('dx_stats/counters/totalUsers');
        } else {
          // Self-heal if v61 wrote seenRef while totalUsers transaction aborted at 0
          const tuSnap = await get(ref(rtdb, 'dx_stats/counters/totalUsers'));
          if (!(+tuSnap.val() > 0)) await anIncCounter('dx_stats/counters/totalUsers');
        }
        try { localStorage['dx:an_ever'] = '2'; } catch (e) {}
      } catch (e) {}
    }

    // 2. Daily unique visitor (once per calendar day per device)
    let seenDay = '';
    try { seenDay = localStorage['dx:an_day'] || ''; } catch (e) {}
    if (seenDay !== day) {
      try {
        const dRef = ref(rtdb, `dx_stats/daily/${day}/${vidKey}`);
        const snap = await get(dRef);
        if (!snap.exists()) {
          await set(dRef, { ts: serverTimestamp(), dev: anDevType() });
          await anIncCounter(`dx_stats/counters/today/${day}`);
        }
        try { localStorage['dx:an_day'] = day; } catch (e) {}
      } catch (e) {}
    }

    // 3. Registered account tracking (when signed in via Google / Email)
    if (USER_PROF && USER_PROF.signedIn && USER_PROF.uid) {
      const uid = String(USER_PROF.uid).replace(/[^a-zA-Z0-9_-]/g, '');
      try {
        const regSeenRef = ref(rtdb, `dx_stats/reg_seen/${uid}`);
        const snap = await get(regSeenRef);
        if (!snap.exists()) {
          await set(regSeenRef, { joinedAt: serverTimestamp() });
          await anIncCounter('dx_stats/counters/regUsers');
        }
        const uRef = ref(rtdb, `dx_stats/admin_users/${uid}`);
        await runTransaction(uRef, cur => {
          const o = (cur && typeof cur === 'object') ? cur : {};
          return {
            name: USER_PROF.name || o.name || 'Trader',
            email: USER_PROF.email || o.email || '',
            provider: USER_PROF.provider || o.provider || 'password',
            dev: anDevType(),
            lastSym: sym || o.lastSym || 'BTCUSDT',
            firstSeen: o.firstSeen || Date.now(),
            lastSeen: Date.now(),
            visits: (+o.visits || 0) + (DX_AN._countedUid === uid ? 0 : 1)
          };
        });
        DX_AN._countedUid = uid;
      } catch (e) {}
    }
  } finally {
    DX_AN._visBusy = false;
  }
}

function anMaybeUpdatePeak(count) {
  if (!DX_AUTH.rtdb || !DX_AUTH.mod || !DX_AUTH.mod.rtdbMod) return;
  if (!(count > DX_AN.peakToday)) return;
  const { ref, runTransaction } = DX_AUTH.mod.rtdbMod;
  const day = anDayKey();
  try {
    runTransaction(ref(DX_AUTH.rtdb, `dx_stats/counters/peak/${day}`), cur => Math.max(+cur || 0, count));
  } catch (e) {}
}

function anAttachAdminListeners() {
  if (!anIsAdmin() || !DX_AUTH.rtdb || !DX_AUTH.mod || !DX_AUTH.mod.rtdbMod) return;
  const { ref, onValue } = DX_AUTH.mod.rtdbMod;
  const rtdb = DX_AUTH.rtdb;
  if (!DX_AN.unsubAdmLive) {
    try {
      DX_AN.unsubAdmLive = onValue(ref(rtdb, 'dx_stats/admin_live'), snap => {
        const res = anCountValidLive(snap.val());
        DX_AN.adminLiveMap = res.users;
        if (DX_AN.modalOpen) anRenderDashboard();
      }, err => {
        DX_AN.err = 'Admin read denied — check Firebase Realtime Database Rules & admin email.';
        if (DX_AN.modalOpen) anRenderDashboard();
      });
    } catch (e) {}
  }
  if (!DX_AN.unsubAdmUsers) {
    try {
      DX_AN.unsubAdmUsers = onValue(ref(rtdb, 'dx_stats/admin_users'), snap => {
        DX_AN.adminUsersMap = snap.val() || {};
        if (DX_AN.modalOpen) anRenderDashboard();
      }, () => {});
    } catch (e) {}
  }
}

function anDetachAdminListeners() {
  if (DX_AN.unsubAdmLive) { try { DX_AN.unsubAdmLive(); } catch (e) {} DX_AN.unsubAdmLive = null; }
  if (DX_AN.unsubAdmUsers) { try { DX_AN.unsubAdmUsers(); } catch (e) {} DX_AN.unsubAdmUsers = null; }
  DX_AN.adminLiveMap = {};
  DX_AN.adminUsersMap = {};
}

function anInit() {
  anEnsureTopBadge();
  anUpdateBadges();
  if (DX_AN.inited) return;
  const cfg = window.DX_FIREBASE_CONFIG || {};
  DX_AN.hasDbUrl = !!String(cfg.databaseURL || '').trim();
  if (!DX_AUTH.ready || !DX_AUTH.rtdb || !DX_AUTH.mod || !DX_AUTH.mod.rtdbMod) return;
  DX_AN.inited = true;

  const { ref, onValue } = DX_AUTH.mod.rtdbMod;
  const rtdb = DX_AUTH.rtdb;

  // 1. Monitor real-time connection state (.info/connected) for 100% accurate onDisconnect
  try {
    DX_AN.unsubConn = onValue(ref(rtdb, '.info/connected'), snap => {
      const isConn = !!snap.val();
      DX_AN.connected = isConn;
      if (isConn) {
        anWritePresence(false);
        anRecordUniqueVisit();
      }
      anUpdateBadges();
    });
  } catch (e) {
    DX_AN.err = (e && e.message) ? String(e.message) : 'Cannot connect to Realtime Database';
  }

  // 2. Public live presence listener (anonymous counts — safe for all users)
  try {
    DX_AN.unsubLive = onValue(ref(rtdb, 'dx_stats/live'), snap => {
      const res = anCountValidLive(snap.val());
      DX_AN.liveCount = Math.max(1, res.count);
      DX_AN.liveMap = res.users;
      anMaybeUpdatePeak(DX_AN.liveCount);
      anUpdateBadges();
    }, err => {
      DX_AN.err = (err && err.message) ? String(err.message) : 'Permission denied reading live count';
      anUpdateBadges();
    });
  } catch (e) {}

  // 3. Public counters listener (Total Users, Today, Peak, Registered)
  try {
    DX_AN.unsubCnt = onValue(ref(rtdb, 'dx_stats/counters'), snap => {
      const c = snap.val() || {};
      const day = anDayKey();
      DX_AN.totalUsers = Math.max(0, +c.totalUsers || 0);
      DX_AN.regUsers   = Math.max(0, +c.regUsers || 0);
      DX_AN.dailyCounts = (c.today && typeof c.today === 'object') ? c.today : {};
      DX_AN.todayUsers = Math.max(0, +(DX_AN.dailyCounts[day]) || 0);
      DX_AN.peakToday  = Math.max(DX_AN.liveCount, +((c.peak && c.peak[day]) || 0));
      anUpdateBadges();
    }, () => {});
  } catch (e) {}

  // 4. Heartbeat every 45s while tab is open
  clearInterval(DX_AN.hbTmr);
  DX_AN.hbTmr = setInterval(() => {
    if (DX_AN.connected) anWritePresence(true);
  }, 45000);

  if (anIsAdmin()) anAttachAdminListeners();
}

function anOnAuthChange() {
  if (DX_AN.connected) {
    anWritePresence(false);
    anRecordUniqueVisit();
  }
  if (anIsAdmin()) anAttachAdminListeners();
  else {
    anDetachAdminListeners();
    if (DX_AN.modalOpen) anCloseDashboard();
  }
  anUpdateBadges();
}

function anPingActivity() {
  if (!DX_AN.connected) return;
  clearTimeout(DX_AN.pingTmr);
  DX_AN.pingTmr = setTimeout(() => {
    anWritePresence(true);
  }, 700);
}

// --- PRIVATE ADMIN ANALYTICS DASHBOARD MODAL (#anm) ---
function anEnsureModal() {
  if ($('#anm')) return $('#anm');
  const m = document.createElement('div');
  m.id = 'anm';
  m.innerHTML = `<div id="anb">
    <div class="hd">
      <div class="an-hd-l">
        <span class="an-hd-ic">📊</span>
        <div>
          <b>DreamX Live Analytics</b>
          <span class="an-badge">ADMIN ONLY</span>
        </div>
      </div>
      <span id="an-conn" class="an-conn">● Connecting…</span>
      <button type="button" id="an-sync" title="Sync existing Firebase Auth user count">⚙</button>
      <button type="button" id="an-ref" title="Refresh data">↻</button>
      <button type="button" id="anx" title="Close">✕</button>
    </div>
    <div id="anc"></div>
  </div>`;
  document.body.appendChild(m);
  m.onclick = e => { if (e.target.id === 'anm') anCloseDashboard(); };
  $('#anx').onclick = anCloseDashboard;
  $('#an-sync').onclick = async () => {
    if (!anIsAdmin() || !DX_AUTH.rtdb || !DX_AUTH.mod || !DX_AUTH.mod.rtdbMod) return;
    const curReg = Math.max(DX_AN.regUsers || 0, Object.keys(DX_AN.adminUsersMap || {}).length);
    const curTot = Math.max(DX_AN.totalUsers || 0, curReg, DX_AN.todayUsers || 0);
    const rIn = prompt('Enter total Registered Users from Firebase Authentication:', String(curReg));
    if (rIn === null) return;
    const nReg = Math.max(0, parseInt(rIn, 10));
    if (isNaN(nReg)) { toast('Invalid number'); return; }
    const tIn = prompt('Enter Total Unique Users (must be >= Registered Users):', String(Math.max(curTot, nReg)));
    if (tIn === null) return;
    const nTot = Math.max(nReg, parseInt(tIn, 10) || nReg);
    try {
      const { ref, set } = DX_AUTH.mod.rtdbMod;
      await set(ref(DX_AUTH.rtdb, 'dx_stats/counters/regUsers'), nReg);
      await set(ref(DX_AUTH.rtdb, 'dx_stats/counters/totalUsers'), nTot);
      toast(`Synced: ${nReg} registered · ${nTot} total users ✓`);
    } catch (e) {
      toast('Failed to update counters — check RTDB Rules');
    }
  };
  $('#an-ref').onclick = () => {
    anWritePresence(true);
    anRecordUniqueVisit();
    anRenderDashboard();
    toast('Analytics refreshed');
  };
  return m;
}

function anOpenDashboard() {
  if (!anIsAdmin()) {
    toast('Admin access required');
    return;
  }
  cm();
  anEnsureModal();
  anAttachAdminListeners();
  DX_AN.modalOpen = true;
  $('#anm').style.display = 'flex';
  anRenderDashboard();
}

function anCloseDashboard() {
  DX_AN.modalOpen = false;
  const m = $('#anm');
  if (m) m.style.display = 'none';
}

function anRenderDashboard() {
  const c = $('#anc');
  if (!c) return;
  const stEl = $('#an-conn');
  if (stEl) {
    if (DX_AN.connected && !DX_AN.err) {
      stEl.textContent = '● Live Sync Active';
      stEl.className = 'an-conn ok';
    } else if (DX_AN.err) {
      stEl.textContent = '⚠ Check RTDB Setup';
      stEl.className = 'an-conn err';
    } else {
      stEl.textContent = '○ Connecting RTDB…';
      stEl.className = 'an-conn';
    }
  }

  // Merge detailed admin_live with anonymous liveMap fallback
  const liveList = Object.keys(DX_AN.adminLiveMap).length
    ? Object.values(DX_AN.adminLiveMap)
    : Object.values(DX_AN.liveMap);
  liveList.sort((a, b) => (+b.ts || 0) - (+a.ts || 0));

  const liveTotal = Math.max(DX_AN.liveCount, liveList.length);
  let liveReg = 0, liveChart = 0, liveHome = 0, livePc = 0, liveMob = 0;
  const symCounts = {};
  liveList.forEach(u => {
    if (u.reg) liveReg++;
    if (u.pg === 'home') liveHome++; else liveChart++;
    if (u.dev === 'mob') liveMob++; else livePc++;
    if (u.pg !== 'home' && u.sym) symCounts[u.sym] = (symCounts[u.sym] || 0) + 1;
  });
  const liveGuest = Math.max(0, liveTotal - liveReg);
  const topSyms = Object.entries(symCounts).sort((a, b) => b[1] - a[1]).slice(0, 6);
  const maxSymCnt = topSyms.length ? topSyms[0][1] : 1;

  // Last 7 days daily visitors
  const days7 = [];
  let maxDayV = 1;
  for (let i = 6; i >= 0; i--) {
    const ts = Date.now() - i * 864e5;
    const dk = anDayKey(ts);
    const val = Math.max(0, +(DX_AN.dailyCounts[dk]) || 0);
    if (val > maxDayV) maxDayV = val;
    const dObj = new Date(ts + 19800000);
    const lbl = i === 0 ? 'Today' : (MN[dObj.getUTCMonth()] + ' ' + dObj.getUTCDate());
    days7.push({ dk, lbl, val, isToday: i === 0 });
  }
  const yestVal = days7.length >= 2 ? days7[days7.length - 2].val : 0;
  const dayDelta = DX_AN.todayUsers - yestVal;
  const dayDeltaTxt = yestVal > 0 ? ((dayDelta >= 0 ? '+' : '−') + Math.abs(dayDelta) + ' vs yesterday') : `Peak live today: ${anFmtNum(DX_AN.peakToday)}`;

  // Registered accounts table
  const regList = Object.entries(DX_AN.adminUsersMap || {}).map(([uid, u]) => Object.assign({ uid }, u || {}));
  regList.sort((a, b) => (+b.lastSeen || 0) - (+a.lastSeen || 0));
  const regTotal = Math.max(DX_AN.regUsers, regList.length);

  let warnHtml = '';
  if (!DX_AN.hasDbUrl || DX_AN.err) {
    warnHtml = `<div class="an-warn">
      <b>⚠ Firebase Realtime Database Setup Needed:</b>
      ${!DX_AN.hasDbUrl ? 'Add your <code>databaseURL</code> inside <code>firebase-config.js</code>.' : esc(DX_AN.err)}
    </div>`;
  }

  const pct = (part, tot) => tot > 0 ? Math.round((part / tot) * 100) : 0;

  c.innerHTML = `${warnHtml}
    <div class="an-kpis">
      <div class="an-kpi live">
        <div class="an-klb"><span class="dx-lp-dot"></span> Live Online Now</div>
        <div class="an-kval">${anFmtNum(liveTotal)}</div>
        <div class="an-ksub">${anFmtNum(liveReg)} signed-in · ${anFmtNum(liveGuest)} guest</div>
      </div>
      <div class="an-kpi">
        <div class="an-klb">Today's Unique Visitors</div>
        <div class="an-kval">${anFmtNum(DX_AN.todayUsers)}</div>
        <div class="an-ksub">${esc(dayDeltaTxt)}</div>
      </div>
      <div class="an-kpi">
        <div class="an-klb">Total Unique Users</div>
        <div class="an-kval">${anFmtNum(Math.max(DX_AN.totalUsers, DX_AN.todayUsers, regTotal, liveTotal))}</div>
        <div class="an-ksub">Peak live today: ${anFmtNum(DX_AN.peakToday)}</div>
      </div>
      <div class="an-kpi">
        <div class="an-klb">Registered Accounts</div>
        <div class="an-kval">${anFmtNum(regTotal)}</div>
        <div class="an-ksub">Google &amp; Email users</div>
      </div>
    </div>

    <div class="an-grid2">
      <div class="an-card">
        <div class="an-ctit"><span>Last 7 Days Unique Visitors</span><small>${esc(anDayKey())} (UTC+5:30)</small></div>
        <div class="an-bars">
          ${days7.map(d => {
            const hPct = d.val > 0 ? Math.max(10, Math.round((d.val / maxDayV) * 100)) : 4;
            return `<div class="an-bcol ${d.isToday ? 'today' : ''}" title="${esc(d.dk)}: ${anFmtNum(d.val)} visitors">
              <span class="an-bnum">${d.val ? anFmtCompact(d.val) : '0'}</span>
              <div class="an-bwrap"><div class="an-bfill" style="height:${hPct}%"></div></div>
              <span class="an-blbl">${esc(d.lbl)}</span>
            </div>`;
          }).join('')}
        </div>
      </div>

      <div class="an-card">
        <div class="an-ctit"><span>Live Breakdown Right Now</span><small>${anFmtNum(liveTotal)} active</small></div>
        <div class="an-split">
          <div class="an-srow">
            <span>📈 Supercharts: <b>${liveChart}</b> (${pct(liveChart, liveTotal)}%)</span>
            <span>🏠 Home: <b>${liveHome}</b> (${pct(liveHome, liveTotal)}%)</span>
          </div>
          <div class="an-pbar"><i style="width:${pct(liveChart, liveTotal)}%;background:#7c5cff"></i></div>
          <div class="an-srow" style="margin-top:8px">
            <span>💻 Desktop PC: <b>${livePc}</b> (${pct(livePc, liveTotal)}%)</span>
            <span>📱 Mobile: <b>${liveMob}</b> (${pct(liveMob, liveTotal)}%)</span>
          </div>
          <div class="an-pbar"><i style="width:${pct(livePc, liveTotal)}%;background:#26c6da"></i></div>
        </div>
        <div class="an-subhd">Top Live Symbols</div>
        <div class="an-syms">
          ${topSyms.length ? topSyms.map(([s, cnt]) => `<div class="an-symrow">
            <span class="an-snm">${esc(lab(s))}</span>
            <div class="an-sbar"><i style="width:${Math.round((cnt / maxSymCnt) * 100)}%"></i></div>
            <span class="an-scnt">${cnt}</span>
          </div>`).join('') : '<div class="an-empty">No live chart symbols yet</div>'}
        </div>
      </div>
    </div>

    <div class="an-card">
      <div class="an-ctit"><span>Live Active Traders (${anFmtNum(liveList.length)})</span><small>Auto-updates instantly on connect / disconnect</small></div>
      <div class="an-tblw">
        <table class="an-tbl">
          <thead><tr><th>Trader</th><th>Page</th><th>Active Chart</th><th>Device</th><th>Tabs</th><th>Online</th></tr></thead>
          <tbody>
            ${liveList.length ? liveList.slice(0, 60).map(u => {
              const isMe = u.key === DX_AN.userKey;
              const nmTxt = u.name || (u.reg ? 'Trader' : 'Guest');
              const dur = u.joinedAt ? anFmtDur(Date.now() - u.joinedAt) : 'Live';
              return `<tr>
                <td><b>${esc(nmTxt)}</b>${isMe ? ' <span class="an-tag me">YOU</span>' : ''} ${u.reg ? '<span class="an-tag reg">PRO</span>' : '<span class="an-tag gst">GUEST</span>'}${u.email ? `<br><small class="mu">${esc(u.email)}</small>` : ''}</td>
                <td>${u.pg === 'home' ? '🏠 Home' : '📈 Supercharts'}</td>
                <td>${u.pg === 'home' ? '—' : `<b>${esc(lab(u.sym || 'BTCUSDT'))}</b> <small class="mu">${esc(u.tf || '')}</small>`}</td>
                <td>${u.dev === 'mob' ? '📱 Mobile' : '💻 PC'}</td>
                <td>${u.tabs || 1}</td>
                <td>${esc(dur)}</td>
              </tr>`;
            }).join('') : '<tr><td colspan="6" class="an-empty">Waiting for live sessions…</td></tr>'}
          </tbody>
        </table>
      </div>
    </div>

    <div class="an-card">
      <div class="an-ctit"><span>Registered Accounts (${anFmtNum(regList.length)})</span><small>Most recently active</small></div>
      <div class="an-tblw">
        <table class="an-tbl">
          <thead><tr><th>Name</th><th>Email</th><th>Provider</th><th>Last Chart</th><th>Visits</th><th>Last Active</th></tr></thead>
          <tbody>
            ${regList.length ? regList.slice(0, 50).map(u => `<tr>
              <td><b>${esc(u.name || 'Trader')}</b></td>
              <td>${esc(u.email || '—')}</td>
              <td>${u.provider && u.provider.includes('google') ? 'Google' : 'Email'}</td>
              <td>${esc(lab(u.lastSym || 'BTCUSDT'))}</td>
              <td>${anFmtNum(u.visits || 1)}</td>
              <td>${esc(anFmtAgo(u.lastSeen))}</td>
            </tr>`).join('') : '<tr><td colspan="6" class="an-empty">No registered user activity recorded yet</td></tr>'}
          </tbody>
        </table>
      </div>
    </div>`;
}

// Secret Admin hotkey: Alt + Shift + A
addEventListener('keydown', e => {
  if (e.altKey && e.shiftKey && e.code === 'KeyA' && !/INPUT|TEXTAREA|SELECT/.test((e.target && e.target.tagName) || '')) {
    if (anIsAdmin()) { e.preventDefault(); anOpenDashboard(); }
  }
});

anEnsureTopBadge();
anUpdateBadges();
addEventListener('resize', () => anUpdateBadges());

if (location.hash === '#chart') {
  HOME_CHART_BOOTED = true;
  go();
} else {
  hmOpen();
}
